chapter('book', 3, "03-early-earth-as-search-space.md", "3. The early Earth as a chemical search space").
sentence(s_book_03_0001, 'book', 3, 3, 'unmarked', "Before life existed, Earth contained an enormous variety of chemical environments.").
sentence(s_book_03_0002, 'book', 3, 5, 'unmarked', "Sunlight, heat, lightning, volcanic activity, minerals, water, tides, and atmospheric chemistry created many opportunities for molecules to interact.").
sentence(s_book_03_0003, 'book', 3, 5, 'unmarked', "Day–night cycles, seasonal changes, wet–dry cycles, temperature gradients, and differences in chemical composition continually altered local conditions.").
sentence(s_book_03_0004, 'book', 3, 7, 'unmarked', "Molecules moved through diffusion and Brownian motion — the ceaseless jostling that thermal energy imparts to anything small enough to be pushed around by it.").
sentence(s_book_03_0005, 'book', 3, 7, 'unmarked', "Some accumulated in particular environments; others dispersed.").
sentence(s_book_03_0006, 'book', 3, 7, 'unmarked', "Surfaces, pores, mineral structures, and interfaces could concentrate molecules or influence which reactions occurred.").
sentence(s_book_03_0007, 'book', 3, 9, 'unmarked', "This created an enormous parallel search space.").
sentence(s_book_03_0008, 'book', 3, 13, 'unmarked', "None of that chemistry would have gone anywhere without a sustained supply of energy.").
sentence(s_book_03_0009, 'book', 3, 13, 'unmarked', "Early Earth had three largely independent sources.").
number(s_book_03_0009, 3, 'largely').
keywords(s_book_03_0009, ['early', 'earth', 'independent', 'largely', 'source', 'three']).
sentence(s_book_03_0010, 'book', 3, 13, 'unmarked', "Each pushed in one direction, and none of them was going to run out.").
sentence(s_book_03_0011, 'book', 3, 15, 'unmarked', "The Sun delivered ultraviolet radiation and heat.").
sentence(s_book_03_0012, 'book', 3, 15, 'unmarked', "Ultraviolet light carries enough energy to break and form chemical bonds directly, and the day–night cycle meant it arrived in pulses rather than at a constant rate.").
sentence(s_book_03_0013, 'book', 3, 17, 'unmarked', "The planet's interior supplied heat, chemically reduced minerals, and hydrothermal circulation.").
sentence(s_book_03_0014, 'book', 3, 17, 'unmarked', "Volcanic systems produced steep thermal and chemical gradients where hot volcanic lava met cold water, and lightning in ash plumes added bursts of electrical energy of the kind later shown to drive organic synthesis in the laboratory.").
sentence(s_book_03_0015, 'book', 3, 19, 'unmarked', "Volcanoes also supplied raw material: sulfur dioxide and hydrogen sulfide, which dissolve in water as sulfite and sulfide, and silica-rich hot-spring water that crusts surfaces with sinter.").
sentence(s_book_03_0016, 'book', 3, 19, 'unmarked', "The same lightning, like that of ordinary storms, turned nitrogen from the air into nitrogen oxides, which end up in water as nitrite and, mostly, nitrate.").
sentence(s_book_03_0017, 'book', 3, 19, 'unmarked', "Coarse ash blankets the ground near the vent; sulfur gas lofted high becomes sulfate droplets that stay aloft for about a year, spreading on the wind.").
sentence(s_book_03_0018, 'book', 3, 19, 'unmarked', "Whether these compounds were at concentrations to matter is still contested, although one can imagine smaller pools and lakes accumulating meaningful levels more so than the ocean.").
hedged(s_book_03_0018).
sentence(s_book_03_0019, 'book', 3, 21, 'unmarked', "The Moon supplied motion on a schedule.").
sentence(s_book_03_0020, 'book', 3, 21, 'unmarked', "Tides stirred shallow water, flooded margins and drained them again, and did so predictably.").
sentence(s_book_03_0021, 'book', 3, 21, 'unmarked', "The Moon orbited closer to Earth's surface then and Earth's day was shorter, so tides arrived more often and reached further than they do now.").
sentence(s_book_03_0022, 'book', 3, 23, 'unmarked', "The three together matter more than any one of them.").
number(s_book_03_0022, 3, 'together').
keywords(s_book_03_0022, ['matter', 'three', 'together']).
sentence(s_book_03_0023, 'book', 3, 23, 'unmarked', "A system can build and hold local organization while energy flows through it and waste heat leaves — this is what a dissipative structure is, and it is ordinary physics rather than an exception to it.").
sentence(s_book_03_0024, 'book', 3, 23, 'unmarked', "What early Earth had was not a single energy source but a continuous, varied, and rhythmic supply, which is exactly the condition under which such structures form and persist.").
sentence(s_book_03_0025, 'book', 3, 27, 'unmarked', "\"Billions of years\" is the phrase that usually carries the weight in explanations of life's origin, and it carries it poorly.").
sentence(s_book_03_0026, 'book', 3, 27, 'unmarked', "The number is too large to picture, so it functions less as an argument than as a request to stop asking.").
sentence(s_book_03_0027, 'book', 3, 27, 'unmarked', "It also points at the wrong quantity.").
sentence(s_book_03_0028, 'book', 3, 29, 'unmarked', "The useful question is not how long Earth has existed.").
sentence(s_book_03_0029, 'book', 3, 29, 'unmarked', "It is how often the experiment ran.").
sentence(s_book_03_0030, 'book', 3, 31, 'unmarked', "Consider a shallow pool at a tidal margin.").
sentence(s_book_03_0031, 'book', 3, 31, 'unmarked', "It is flooded, agitated, partly dried, and refilled.").
sentence(s_book_03_0032, 'book', 3, 31, 'unmarked', "Amphiphilic molecules in it — the kind with a water-attracting end and a water-repelling end — assemble into films and droplets, hold together for a time, and are broken apart again.").
sentence(s_book_03_0033, 'book', 3, 31, 'unmarked', "Each assembly is a trial: a slightly different mixture, enclosed for a slightly different interval, under slightly different conditions.").
sentence(s_book_03_0034, 'book', 3, 33, 'unmarked', "Suppose one such cycle completes every six minutes.").
number(s_book_03_0034, 6, 'minute').
keywords(s_book_03_0034, ['complete', 'cycle', 'minute', 'suppose']).
sentence(s_book_03_0035, 'book', 3, 33, 'unmarked', "Then that single pool runs:").
sentence(s_book_03_0036, 'book', 3, 42, 'unmarked', "Ten million years is a rounding error in Earth's history.").
number(s_book_03_0036, 1e+07, 'year').
keywords(s_book_03_0036, ['earth', 'error', 'history', 'million', 'rounding']).
sentence(s_book_03_0037, 'book', 3, 44, 'unmarked', "Earth is about 4.54 billion years old, so its history holds about 450 ten-million-year spans.").
number(s_book_03_0037, 4.54e+09, 'year').
number(s_book_03_0037, 450, 'ten-million-year').
number(s_book_03_0037, 1e+07, 'year').
keywords(s_book_03_0037, ['billion', 'earth', 'history', 'ten-million-year']).
sentence(s_book_03_0038, 'book', 3, 46, 'unmarked', "The six-minute figure is invented, and the honest thing is to say so and then show that it does not matter.").
number(s_book_03_0038, 6, 'minute').
keywords(s_book_03_0038, ['figure', 'honest', 'invented', 'matter', 'six-minute', 'thing']).
sentence(s_book_03_0039, 'book', 3, 46, 'unmarked', "Make the cycle an hour instead and the trial count falls by a factor of ten, to around 9 × 10<sup>10</sup>.").
number(s_book_03_0039, 9, 'sup').
number(s_book_03_0039, 10, 'sup').
number(s_book_03_0039, 10, 'sup').
number(s_book_03_0039, 10, 'sup').
keywords(s_book_03_0039, ['count', 'cycle', 'factor', 'instead', 'trial']).
sentence(s_book_03_0040, 'book', 3, 46, 'unmarked', "Make it a full day and it falls by a factor of 240, to around 4 × 10<sup>9</sup>.").
number(s_book_03_0040, 240, 'sup').
number(s_book_03_0040, 4, 'sup').
number(s_book_03_0040, 10, 'sup').
number(s_book_03_0040, 9, 'sup').
keywords(s_book_03_0040, ['factor']).
sentence(s_book_03_0041, 'book', 3, 46, 'unmarked', "Even at the most pessimistic end that is billions of trials, in one pool, over an interval geology would not bother to name.").
sentence(s_book_03_0042, 'book', 3, 46, 'unmarked', "Across any plausible cycle time the conclusion is the same, which is a sign the argument rests on the structure of the situation rather than on a number someone chose.").
hedged(s_book_03_0042).
sentence(s_book_03_0043, 'book', 3, 48, 'unmarked', "And there was a planet's worth of such places — tidal margins, hydrothermal vents, hot springs, pores in wet rock, films on mineral surfaces — all running at once, independently, for hundreds of millions of years.").
sentence(s_book_03_0044, 'book', 3, 50, 'unmarked', "So the picture is not one slow process grinding away for four billion years.").
number(s_book_03_0044, 4e+09, 'year').
keywords(s_book_03_0044, ['billion', 'grinding', 'picture', 'process']).
sentence(s_book_03_0045, 'book', 3, 50, 'unmarked', "It is an extremely large number of short, parallel, independent, cheap experiments, nearly all of which failed within minutes, running simultaneously across an entire planet.").
sentence(s_book_03_0046, 'book', 3, 50, 'unmarked', "Deep time supplies the opportunity.").
sentence(s_book_03_0047, 'book', 3, 50, 'unmarked', "Cycling supplies the throughput.").
sentence(s_book_03_0048, 'book', 3, 50, 'unmarked', "The second is doing more of the work than it usually gets credit for.").
sentence(s_book_03_0049, 'book', 3, 52, 'unmarked', "This way of framing the problem is the author's, and the figures above are an order-of-magnitude illustration rather than a measurement.").
sentence(s_book_03_0050, 'book', 3, 52, 'unmarked', "The underlying components — wet–dry cycling, spontaneous assembly of amphiphiles, the role of mineral surfaces — are well established and are taken up again in chapters 4, 5, and 17.").
number(s_book_03_0050, 17, 'none').
keywords(s_book_03_0050, ['again', 'amphiphile', 'assembly', 'chapter', 'component', 'cycling', 'established', 'mineral', 'spontaneou', 'surface', 'taken', 'underlying']).
xref(s_book_03_0050, 4).
xref(s_book_03_0050, 5).
sentence(s_book_03_0051, 'book', 3, 56, 'unmarked', "A familiar image for this kind of process is the one about enough monkeys at enough typewriters eventually producing Shakespeare.").
sentence(s_book_03_0052, 'book', 3, 56, 'unmarked', "It is useful for conveying how large numbers make improbable outcomes ordinary, and it is misleading in one important respect.").
sentence(s_book_03_0053, 'book', 3, 58, 'unmarked', "Chemistry is not a random typist.").
sentence(s_book_03_0054, 'book', 3, 58, 'unmarked', "Molecular properties, bond energies, reaction rates, concentrations, temperature, and the geometry of available surfaces all strongly constrain what can happen.").
sentence(s_book_03_0055, 'book', 3, 58, 'unmarked', "Most of the possible arrangements of a given set of atoms are never explored at all, because they are not reachable from where the system actually is.").
certainty_word(s_book_03_0055, 'never').
sentence(s_book_03_0056, 'book', 3, 58, 'unmarked', "The search is vast, but it is not uniform, and it is not blind in the way the image suggests.").
hedged(s_book_03_0056).
sentence(s_book_03_0057, 'book', 3, 62, 'unmarked', "This matters because it cuts the problem down.").
sentence(s_book_03_0058, 'book', 3, 62, 'unmarked', "A process that samples randomly from everything possible would need far more time than Earth has had.").
sentence(s_book_03_0059, 'book', 3, 62, 'unmarked', "A process whose next steps are heavily constrained by the chemistry already present is exploring a much smaller space — and exploring it in parallel, in enormous numbers, continuously.").
sentence(s_book_03_0060, 'book', 3, 64, 'unmarked', "Nothing in this requires foresight.").
sentence(s_book_03_0061, 'book', 3, 64, 'unmarked', "Physical conditions created possibilities, and the properties of the resulting chemical systems determined which ones lasted long enough to matter.").
sentence(s_book_03_0062, 'book', 3, 68, 'unmarked', "One caution belongs at the end of any argument of this shape.").
sentence(s_book_03_0063, 'book', 3, 70, 'unmarked', "What is visible from the present is the chemistry that led to life.").
sentence(s_book_03_0064, 'book', 3, 70, 'unmarked', "The pathways that failed, stalled, or were destroyed left nothing behind to examine.").
sentence(s_book_03_0065, 'book', 3, 70, 'unmarked', "This is selection bias, and it is unusually severe in this case, because the surviving lineage is the only one that produced observers capable of asking about it.").
sentence(s_book_03_0066, 'book', 3, 72, 'unmarked', "That a pathway persisted does not establish that it was likely, and it certainly does not establish that it was inevitable.").
certainty_word(s_book_03_0066, 'certainly').
certainty_word(s_book_03_0066, 'inevitable').
hedged(s_book_03_0066).
sentence(s_book_03_0067, 'book', 3, 72, 'unmarked', "A planet running an enormous number of parallel experiments will produce some improbable outcome; the one it produced is the one being looked at.").
sentence(s_book_03_0068, 'book', 3, 72, 'unmarked', "How probable life was, given early Earth's conditions, remains genuinely unknown.").
hedged(s_book_03_0068).
sentence(s_book_03_0069, 'book', 3, 72, 'unmarked', "The sample size is one.").
heading_count('book', 3, 11, "Three engines", 3, 3).
chapter('book', 4, "04-chemical-networks.md", "4. From chemical reactions to self-sustaining networks").
sentence(s_book_04_0001, 'book', 4, 3, 'unmarked', "Chapter 3 described an enormous number of chemical trials running in parallel.").
xref(s_book_04_0001, 3).
sentence(s_book_04_0002, 'book', 4, 3, 'unmarked', "Most produced nothing that lasted.").
sentence(s_book_04_0003, 'book', 4, 3, 'unmarked', "This chapter is about the ones that did, and about what \"lasting\" can mean for a reaction.").
sentence(s_book_04_0004, 'book', 4, 5, 'unmarked', "A chemical reaction can produce a compound that participates in further reactions.").
sentence(s_book_04_0005, 'book', 4, 5, 'unmarked', "Some reactions reinforce the production of their own components, or help sustain a whole network of reactions.").
sentence(s_book_04_0006, 'book', 4, 5, 'unmarked', "Several ideas are needed to describe how:").
sentence(s_book_04_0007, 'book', 4, 7, 'unmarked', "- Catalysis: a substance increases the rate of a reaction without being consumed in the overall reaction. - Autocatalysis: a reaction product helps catalyse the production of more of itself. - Autocatalytic sets: networks in which the components collectively sustain the network, with no member required to catalyse itself. - Reaction networks: connected sets of reactions in which products and reactants participate in multiple processes. - Dissipative structures: organized patterns that arise and persist in systems driven away from equilibrium by flows of energy or matter.").
sentence(s_book_04_0008, 'book', 4, 13, 'unmarked', "Those are definitions.").
sentence(s_book_04_0009, 'book', 4, 13, 'unmarked', "The rest of this chapter is given over to the demonstrations, because each of these is something that has been observed rather than something the argument needs to be true.").
sentence(s_book_04_0010, 'book', 4, 17, 'unmarked', "A catalyst does not make an impossible reaction possible.").
certainty_word(s_book_04_0010, 'impossible').
sentence(s_book_04_0011, 'book', 4, 17, 'unmarked', "It makes a slow reaction fast, by offering a path with a lower barrier.").
sentence(s_book_04_0012, 'book', 4, 19, 'unmarked', "The distinction matters for the early Earth.").
sentence(s_book_04_0013, 'book', 4, 19, 'unmarked', "Reactions that are thermodynamically allowed but take ten thousand years at ambient temperature might as well not happen in most places, because few conditions hold still that long.").
number(s_book_04_0013, 10000, 'year').
keywords(s_book_04_0013, ['allowed', 'ambient', 'because', 'condition', 'happen', 'might', 'place', 'reaction', 'temperature', 'thermodynamically', 'thousand']).
hedged(s_book_04_0013).
sentence(s_book_04_0014, 'book', 4, 19, 'unmarked', "A mineral surface or a small molecule that drops the barrier turns a reaction that effectively never occurs into one that occurs constantly.").
certainty_word(s_book_04_0014, 'never').
sentence(s_book_04_0015, 'book', 4, 21, 'unmarked', "Catalysis therefore does not change what chemistry is possible.").
sentence(s_book_04_0016, 'book', 4, 21, 'unmarked', "It changes which possibilities are reachable within the time a given environment stays put.").
sentence(s_book_04_0017, 'book', 4, 23, 'unmarked', "Environment is doing quiet work in that sentence.").
sentence(s_book_04_0018, 'book', 4, 23, 'unmarked', "It names a concept people made, not a unit nature hands over.").
sentence(s_book_04_0019, 'book', 4, 23, 'unmarked', "The skin of a face is an environment for the bacteria living on it.").
sentence(s_book_04_0020, 'book', 4, 23, 'unmarked', "So is a yard, and so are a house, a town, a region, and the whole of nature, overlapping and nested, with edges drawn wherever it is convenient to draw them.").
sentence(s_book_04_0021, 'book', 4, 23, 'unmarked', "The timescale is as loose as the edges.").
sentence(s_book_04_0022, 'book', 4, 23, 'unmarked', "How long an environment stays put depends on where its line is drawn, and the only measure that matters is whether there was enough time for something to happen.").
sentence(s_book_04_0023, 'book', 4, 23, 'unmarked', "For a tidal pool, splashed by waves and refilled by tides, that may be minutes or hours; for water held in a pore deep in rock it may be far longer.").
hedged(s_book_04_0023).
sentence(s_book_04_0024, 'book', 4, 23, 'unmarked', "A catalyst matters because it brings a reaction inside whichever window applies.").
sentence(s_book_04_0025, 'book', 4, 27, 'unmarked', "Autocatalysis is the point where a reaction starts to have something like an interest in its own continuation, and it is worth seeing concretely rather than taking on trust.").
sentence(s_book_04_0026, 'book', 4, 29, 'unmarked', "The formose reaction is the standard prebiotic case, known since Butlerov described it in 1861.").
year(s_book_04_0026, 1861).
keywords(s_book_04_0026, ['butlerov', 'described', 'formose', 'known', 'prebiotic', 'reaction', 'since', 'standard']).
sentence(s_book_04_0027, 'book', 4, 29, 'unmarked', "Formaldehyde, a simple molecule plausibly abundant on the early Earth, reacts with itself in the presence of a base to produce sugars.").
hedged(s_book_04_0027).
sentence(s_book_04_0028, 'book', 4, 29, 'unmarked', "The reaction is autocatalytic: one of its early products, glycolaldehyde, catalyses the process that produces more of it.").
sentence(s_book_04_0029, 'book', 4, 29, 'unmarked', "The characteristic behaviour is a long sluggish period in which almost nothing happens, followed by a sudden acceleration as the product that speeds the reaction begins to accumulate.").
sentence(s_book_04_0030, 'book', 4, 29, 'unmarked', "The reaction builds the thing that makes it faster.").
sentence(s_book_04_0031, 'book', 4, 31, 'unmarked', "That shape — slow, then abruptly fast — is the signature of autocatalysis, and it is the same shape as a population growing or a rumour spreading.").
sentence(s_book_04_0032, 'book', 4, 33, 'unmarked', "The second demonstration is more direct.").
sentence(s_book_04_0033, 'book', 4, 33, 'unmarked', "In 1996 a research group reported a peptide (a short protein-like chain) 32 amino acids long — its structure borrowed from a small unit of an ordinary yeast protein — that catalyses its own formation.").
year(s_book_04_0033, 1996).
number(s_book_04_0033, 32, 'amino').
keywords(s_book_04_0033, ['amino', 'borrowed', 'catalyse', 'chain', 'formation', 'group', 'ordinary', 'peptide', 'protein', 'protein-like', 'reported', 'research', 'short', 'small', 'structure', 'yeast']).
sentence(s_book_04_0034, 'book', 4, 33, 'unmarked', "Presented with two shorter fragments corresponding to its own halves, it binds them against itself and accelerates their joining into another complete copy.").
number(s_book_04_0034, 2, 'shorter').
keywords(s_book_04_0034, ['accelerate', 'against', 'complete', 'corresponding', 'fragment', 'halve', 'itself', 'joining', 'presented', 'shorter']).
sentence(s_book_04_0035, 'book', 4, 33, 'unmarked', "A molecule making copies of itself, built from ordinary amino acids, with nothing biological involved.").
sentence(s_book_04_0036, 'book', 4, 33, 'unmarked', "Comparable systems had already been built from short nucleic acid strands a decade earlier, and more capable ones have been built since — pairs of RNA enzymes that make each other, multiplying exponentially with no proteins involved.").
sentence(s_book_04_0037, 'book', 4, 35, 'unmarked', "These are laboratory systems, designed rather than found, and that limits what they establish.").
sentence(s_book_04_0038, 'book', 4, 35, 'unmarked', "They do not show that such molecules arose on the early Earth.").
sentence(s_book_04_0039, 'book', 4, 37, 'unmarked', "The newest result narrows that limit without removing it.").
sentence(s_book_04_0040, 'book', 4, 37, 'unmarked', "In 2026 a group reported an RNA enzyme only 45 nucleotides long that copies RNA templates.").
year(s_book_04_0040, 2026).
number(s_book_04_0040, 45, 'nucleotide').
keywords(s_book_04_0040, ['enzyme', 'group', 'nucleotide', 'reported', 'template']).
sentence(s_book_04_0041, 'book', 4, 37, 'unmarked', "It began as a find rather than a design: it was selected from pools of random sequences, then improved by further rounds of laboratory evolution and engineering.").
sentence(s_book_04_0042, 'book', 4, 37, 'unmarked', "Working in mildly alkaline ice, from building blocks three letters long, it can make both its complementary strand and a copy of itself, which are the two halves of a replication cycle.").
number(s_book_04_0042, 3, 'letter').
number(s_book_04_0042, 2, 'halve').
keywords(s_book_04_0042, ['alkaline', 'block', 'building', 'complementary', 'cycle', 'halve', 'itself', 'letter', 'mildly', 'replication', 'strand', 'three', 'working']).
sentence(s_book_04_0043, 'book', 4, 37, 'unmarked', "It does them only in separate reactions, though, with yields of about 0.2 per cent after 72 days and about 6 per cent of letters copied wrongly, and the paper's own model finds that at this accuracy almost none of the copies would still work.").
number(s_book_04_0043, 0.2, 'cent').
number(s_book_04_0043, 72, 'day').
number(s_book_04_0043, 6, 'cent').
keywords(s_book_04_0043, ['accuracy', 'copied', 'letter', 'model', 'paper', 'reaction', 'separate', 'though', 'would', 'wrongly', 'yield']).
sentence(s_book_04_0044, 'book', 4, 37, 'unmarked', "Its discoverers note that 45 letters approaches the lengths unaided chemistry may be able to string together, and read the find as a sign that copying molecules are commoner among random RNA sequences than had been thought.").
number(s_book_04_0044, 45, 'letter').
keywords(s_book_04_0044, ['among', 'approache', 'chemistry', 'commoner', 'copying', 'discoverer', 'length', 'letter', 'molecule', 'random', 'sequence', 'string', 'thought', 'together', 'unaided']).
hedged(s_book_04_0044).
sentence(s_book_04_0045, 'book', 4, 37, 'unmarked', "They are equally clear that faster and more accurate copying is still needed before replication could sustain itself.").
sentence(s_book_04_0046, 'book', 4, 39, 'unmarked', "There is a second limit, more interesting than the first.").
sentence(s_book_04_0047, 'book', 4, 39, 'unmarked', "The 1996 peptide's reproduction is parabolic rather than exponential: the rate rises with the square root of how much template is present, not in proportion to it.").
year(s_book_04_0047, 1996).
keywords(s_book_04_0047, ['exponential', 'parabolic', 'peptide', 'present', 'proportion', 'rather', 'reproduction', 'square', 'template']).
sentence(s_book_04_0048, 'book', 4, 39, 'unmarked', "The reason is that copies tend to stick to one another, and a molecule bound to its own product is not available to catalyse anything.").
sentence(s_book_04_0049, 'book', 4, 39, 'unmarked', "Parabolic growth has a consequence that matters for everything downstream — a faster variant cannot drive a slower one to extinction, because its advantage shrinks as it becomes common.").
sentence(s_book_04_0050, 'book', 4, 39, 'unmarked', "Competition of the kind evolution requires does not get started.").
sentence(s_book_04_0051, 'book', 4, 39, 'unmarked', "The same difficulty appears in most self-replicating chemical systems built since.").
hedged(s_book_04_0051).
sentence(s_book_04_0052, 'book', 4, 41, 'unmarked', "So what these experiments establish is narrower than it first appears, and still substantial.").
hedged(s_book_04_0052).
sentence(s_book_04_0053, 'book', 4, 41, 'unmarked', "Self-reproduction is a chemical property available to fairly simple molecules, and not something that had to wait for life to invent it.").
sentence(s_book_04_0054, 'book', 4, 41, 'unmarked', "Self-reproduction good enough to support open-ended selection is a further step, and it is one nobody has yet demonstrated.").
sentence(s_book_04_0055, 'book', 4, 45, 'unmarked', "A molecule that catalyses its own production is one route.").
sentence(s_book_04_0056, 'book', 4, 45, 'unmarked', "There is another, and it may be more plausible, because it does not require any single molecule to do anything remarkable.").
hedged(s_book_04_0056).
sentence(s_book_04_0057, 'book', 4, 47, 'unmarked', "Consider a set of molecules in which A catalyses the formation of B, B catalyses C, and C catalyses A.").
sentence(s_book_04_0058, 'book', 4, 47, 'unmarked', "No member catalyses itself.").
sentence(s_book_04_0059, 'book', 4, 47, 'unmarked', "The set as a whole catalyses itself.").
sentence(s_book_04_0060, 'book', 4, 47, 'unmarked', "Given a supply of raw material, it persists and reproduces its own composition, and the property of self-maintenance belongs to the network rather than to any part of it.").
sentence(s_book_04_0061, 'book', 4, 49, 'unmarked', "Stuart Kauffman argued in 1986 that such collectively autocatalytic sets should appear almost unavoidably in sufficiently large and varied chemical mixtures — that past some density of molecules and reactions, the probability of a closed catalytic loop existing somewhere in the mixture approaches certainty.").
year(s_book_04_0061, 1986).
keywords(s_book_04_0061, ['appear', 'approache', 'argued', 'autocatalytic', 'catalytic', 'certainty', 'chemical', 'closed', 'collectively', 'density', 'existing', 'kauffman', 'large', 'mixture', 'molecule', 'probability', 'reaction', 'should', 'somewhere', 'stuart', 'sufficiently', 'unavoidably', 'varied']).
hedged(s_book_04_0061).
cites(s_book_04_0061, 'Kauffman', 1986).
sentence(s_book_04_0062, 'book', 4, 49, 'unmarked', "The argument has since been formalized and explored computationally.").
sentence(s_book_04_0063, 'book', 4, 51, 'unmarked', "The status of this is worth stating precisely, because it is a case where the mathematics is stronger than the chemistry.").
sentence(s_book_04_0064, 'book', 4, 51, 'unmarked', "The theoretical result is solid: in a sufficiently rich network, self-sustaining subsets are expected.").
sentence(s_book_04_0065, 'book', 4, 51, 'unmarked', "Whether real prebiotic chemistry was rich enough, and whether the catalysts available were specific enough, is not settled.").
sentence(s_book_04_0066, 'book', 4, 51, 'unmarked', "Experimental systems demonstrating collective autocatalysis exist but are small and mostly constructed rather than discovered.").
sentence(s_book_04_0067, 'book', 4, 53, 'unmarked', "This is also the first appearance of something the rest of the book returns to repeatedly: a property that belongs to a set of components and to none of them individually.").
sentence(s_book_04_0068, 'book', 4, 57, 'unmarked', "The last idea is the one that explains why any of this persists.").
sentence(s_book_04_0069, 'book', 4, 59, 'unmarked', "Heat a shallow layer of liquid evenly from below.").
sentence(s_book_04_0070, 'book', 4, 59, 'unmarked', "At small temperature differences, heat passes through by conduction and nothing visible happens.").
sentence(s_book_04_0071, 'book', 4, 59, 'unmarked', "Past a threshold, the liquid abruptly organizes itself into a tiling of convection cells, often hexagonal, each circulating in a fixed direction.").
sentence(s_book_04_0072, 'book', 4, 59, 'unmarked', "The pattern is orderly, it is not imposed from outside, and it appears spontaneously.").
hedged(s_book_04_0072).
sentence(s_book_04_0073, 'book', 4, 61, 'unmarked', "Stop the heating and it does not freeze in place.").
sentence(s_book_04_0074, 'book', 4, 63, 'unmarked', "That is a dissipative structure: organization that exists because energy is flowing through, and only for as long as it is.").
sentence(s_book_04_0075, 'book', 4, 63, 'unmarked', "Ilya Prigogine's work on these systems, recognized with a Nobel Prize in 1977, is the reason the phrase exists.").
year(s_book_04_0075, 1977).
keywords(s_book_04_0075, ['exist', 'nobel', 'phrase', 'prigogine', 'prize', 'reason', 'recognized', 'system']).
sentence(s_book_04_0076, 'book', 4, 63, 'unmarked', "The crucial point is that the structure is not a thing that was built and now persists.").
sentence(s_book_04_0077, 'book', 4, 63, 'unmarked', "It is a process that maintains an appearance of being a thing.").
sentence(s_book_04_0078, 'book', 4, 65, 'unmarked', "Chemistry has its own version.").
sentence(s_book_04_0079, 'book', 4, 65, 'unmarked', "The Belousov–Zhabotinsky reaction, in a shallow dish, cycles between states and generates travelling waves and rotating spiral patterns that can continue for an hour or more before the reagents are exhausted.").
sentence(s_book_04_0080, 'book', 4, 65, 'unmarked', "Its mechanism includes an autocatalytic step.").
sentence(s_book_04_0081, 'book', 4, 65, 'unmarked', "It was initially disbelieved — a chemical reaction that oscillates rather than settling looked to reviewers like an error — and it is now a standard demonstration.").
sentence(s_book_04_0082, 'book', 4, 65, 'unmarked', "(The spirals it produces are the fifth category in chapter 10 — a wave front curling around its own free end, with nothing material rotating at all.)").
xref(s_book_04_0082, 10).
sentence(s_book_04_0083, 'book', 4, 67, 'unmarked', "The same description applies to every organism, which is the reason the concept appears here rather than in a chapter on physics.").
hedged(s_book_04_0083).
sentence(s_book_04_0084, 'book', 4, 67, 'unmarked', "A cell is not a structure that was assembled and now endures.").
sentence(s_book_04_0085, 'book', 4, 67, 'unmarked', "It is a set of processes that rebuild it continuously, and it persists for exactly as long as they continue.").
sentence(s_book_04_0086, 'book', 4, 71, 'unmarked', "Putting these together, a possible sequence:").
sentence(s_book_04_0087, 'book', 4, 73, 'unmarked', "Chemical exploration produces many molecular combinations.").
sentence(s_book_04_0088, 'book', 4, 73, 'unmarked', "Some reactions generate compounds that participate in further reactions.").
sentence(s_book_04_0089, 'book', 4, 73, 'unmarked', "Catalysis makes particular pathways fast enough to matter on environmental timescales.").
sentence(s_book_04_0090, 'book', 4, 73, 'unmarked', "Interconnected reactions begin to reinforce one another.").
sentence(s_book_04_0091, 'book', 4, 73, 'unmarked', "Some networks persist longer than isolated reactions.").
sentence(s_book_04_0092, 'book', 4, 73, 'unmarked', "More stable networks become coupled to energy capture, containment, and eventually information retention.").
sentence(s_book_04_0093, 'book', 4, 80, 'unmarked', "The steps are not equally supported.").
sentence(s_book_04_0094, 'book', 4, 80, 'unmarked', "Steps 1 through 3 are directly demonstrated: mixtures that diversify, products that feed further reactions, catalysts that make particular pathways fast.").
number(s_book_04_0094, 1, 'directly').
number(s_book_04_0094, 3, 'directly').
keywords(s_book_04_0094, ['catalyst', 'demonstrated', 'directly', 'diversify', 'further', 'mixture', 'particular', 'pathway', 'product', 'reaction']).
sentence(s_book_04_0095, 'book', 4, 80, 'unmarked', "Steps 4 and 5 have been shown only in the laboratory, in systems that are small and mostly designed rather than found, and whether early Earth's chemistry was rich enough to produce them unaided is, as above, not settled.").
number(s_book_04_0095, 4, 'have').
number(s_book_04_0095, 5, 'have').
keywords(s_book_04_0095, ['above', 'chemistry', 'designed', 'early', 'earth', 'enough', 'found', 'laboratory', 'mostly', 'produce', 'rather', 'settled', 'shown', 'small', 'system', 'unaided', 'whether']).
sentence(s_book_04_0096, 'book', 4, 80, 'unmarked', "So the sequence as a whole is a conjecture, and stays a conjecture until the chemistry is better understood.").
sentence(s_book_04_0097, 'book', 4, 80, 'unmarked', "Step 6 is where the account becomes genuinely incomplete.").
number(s_book_04_0097, 6, 'none').
keywords(s_book_04_0097, ['account', 'become', 'genuinely', 'incomplete']).
sentence(s_book_04_0098, 'book', 4, 84, 'unmarked', "Three honest limits, since a chapter that presents only the encouraging results is not worth much.").
number(s_book_04_0098, 3, 'honest').
keywords(s_book_04_0098, ['chapter', 'encouraging', 'honest', 'limit', 'present', 'result', 'since', 'three', 'worth']).
sentence(s_book_04_0099, 'book', 4, 86, 'unmarked', "The formose reaction, the usual example, has a serious problem as an origin-of-life mechanism: it is indiscriminate.").
sentence(s_book_04_0100, 'book', 4, 86, 'unmarked', "It produces a complex mixture of sugars and degradation products — described in the literature, not unfairly, as tar — in which the biologically relevant sugar is a minor component and is unstable besides.").
sentence(s_book_04_0101, 'book', 4, 86, 'unmarked', "Selectivity, not reactivity, is the difficulty.").
sentence(s_book_04_0102, 'book', 4, 86, 'unmarked', "Some minerals and borate compounds improve matters, and whether they improve them enough is unresolved.").
sentence(s_book_04_0103, 'book', 4, 88, 'unmarked', "The self-replicating molecules described above were designed, or, in the newest case, selected from random sequences and then refined by chemists.").
sentence(s_book_04_0104, 'book', 4, 88, 'unmarked', "Showing that a chemist can build or find one does not show that chemistry can find one unaided, and the search space from chapter 3, large as it is, is not self-evidently large enough.").
xref(s_book_04_0104, 3).
sentence(s_book_04_0105, 'book', 4, 90, 'unmarked', "Most importantly — and this is the parabolic-growth problem generalized — no demonstrated autocatalytic system evolves open-endedly.").
sentence(s_book_04_0106, 'book', 4, 90, 'unmarked', "They sustain themselves and they copy themselves.").
sentence(s_book_04_0107, 'book', 4, 90, 'unmarked', "What has not been shown is a chemical system in which better variants keep displacing worse ones, so that improvements accumulate across generations without limit.").
sentence(s_book_04_0108, 'book', 4, 90, 'unmarked', "That is what separates persistent chemistry from life, it is the subject of chapter 8, and it remains the largest unfilled step in this account.").
xref(s_book_04_0108, 8).
chapter('book', 5, "05-compartments.md", "5. Compartments: creating local systems").
sentence(s_book_05_0001, 'book', 5, 3, 'unmarked', "One important transition in the development of life may have been the emergence of compartments.").
hedged(s_book_05_0001).
sentence(s_book_05_0002, 'book', 5, 5, 'unmarked', "A compartment separates a local chemical environment from its surroundings.").
sentence(s_book_05_0003, 'book', 5, 5, 'unmarked', "This can happen through physical boundaries such as lipid membranes, mineral pores, or other structures.").
sentence(s_book_05_0004, 'book', 5, 7, 'unmarked', "The central fact about such boundaries is that the simplest of them require nothing to build them.").
sentence(s_book_05_0005, 'book', 5, 11, 'unmarked', "Oil and vinegar shaken together in a bottle disperse into droplets and then separate again within minutes.").
sentence(s_book_05_0006, 'book', 5, 11, 'unmarked', "Oil and water do not mix, and shaking only postpones the outcome.").
sentence(s_book_05_0007, 'book', 5, 13, 'unmarked', "Add egg yolk and the result is mayonnaise, which does not separate.").
sentence(s_book_05_0008, 'book', 5, 15, 'unmarked', "The difference is a class of molecule present in the yolk.").
sentence(s_book_05_0009, 'book', 5, 15, 'unmarked', "Amphiphiles have two ends with opposite preferences: one that associates readily with water, one that does not.").
number(s_book_05_0009, 2, 'end').
keywords(s_book_05_0009, ['amphiphile', 'associate', 'opposite', 'preference', 'readily', 'water']).
sentence(s_book_05_0010, 'book', 5, 15, 'unmarked', "A molecule like that cannot be comfortable anywhere in a mixture of oil and water except at the boundary between them, with each end in the phase it prefers.").
certainty_word(s_book_05_0010, 'cannot be').
sentence(s_book_05_0011, 'book', 5, 15, 'unmarked', "Enough of them arrive at that boundary, coat the oil droplets, and the droplets stop merging.").
sentence(s_book_05_0012, 'book', 5, 15, 'unmarked', "Nothing assembled them.").
sentence(s_book_05_0013, 'book', 5, 15, 'unmarked', "Each molecule found its lowest-energy position, and a stable structure is what the sum of those positions looks like.").
sentence(s_book_05_0014, 'book', 5, 17, 'unmarked', "Soap works by the same principle in reverse.").
sentence(s_book_05_0015, 'book', 5, 17, 'unmarked', "Above a certain concentration in water, soap molecules cluster with their water-repelling ends turned inward and their water-attracting ends facing out.").
sentence(s_book_05_0016, 'book', 5, 17, 'unmarked', "The result is a micelle — a ball of tails wrapped in heads.").
sentence(s_book_05_0017, 'book', 5, 17, 'unmarked', "Grease dissolves into the interior, which is why the technique works.").
sentence(s_book_05_0018, 'book', 5, 19, 'unmarked', "A micelle is not yet a compartment in the sense that matters here, and the distinction is easy to lose.").
sentence(s_book_05_0019, 'book', 5, 19, 'unmarked', "A micelle has no interior space: its centre is a knot of hydrocarbon tails with nowhere for water to be.").
sentence(s_book_05_0020, 'book', 5, 19, 'unmarked', "Nothing dissolved in water can be contained inside one.").
sentence(s_book_05_0021, 'book', 5, 21, 'unmarked', "The structure that does contain something is a bilayer vesicle — two sheets of amphiphiles back to back, tails meeting in the middle, water-facing heads on both outer surfaces, the whole thing curved around and closed.").
number(s_book_05_0021, 2, 'sheet').
keywords(s_book_05_0021, ['amphiphile', 'bilayer', 'closed', 'contain', 'curved', 'meeting', 'middle', 'outer', 'sheet', 'something', 'structure', 'surface', 'thing', 'vesicle', 'water-facing', 'whole']).
sentence(s_book_05_0022, 'book', 5, 21, 'unmarked', "That arrangement encloses a volume of water, separated from the water outside by a film two molecules thick.").
number(s_book_05_0022, 2, 'molecule').
keywords(s_book_05_0022, ['arrangement', 'enclose', 'molecule', 'outside', 'separated', 'thick', 'volume', 'water']).
sentence(s_book_05_0023, 'book', 5, 23, 'unmarked', "Which structure forms is largely a matter of molecular shape.").
sentence(s_book_05_0024, 'book', 5, 23, 'unmarked', "Amphiphiles with one tail tend to pack into micelles.").
sentence(s_book_05_0025, 'book', 5, 23, 'unmarked', "Those with two tails, which cannot taper to a point, pack into sheets instead, and sheets close into vesicles.").
number(s_book_05_0025, 2, 'tail').
keywords(s_book_05_0025, ['cannot', 'close', 'instead', 'point', 'sheet', 'taper', 'vesicle']).
sentence(s_book_05_0026, 'book', 5, 23, 'unmarked', "The phospholipids in every cell membrane have two tails.").
number(s_book_05_0026, 2, 'tail').
keywords(s_book_05_0026, ['membrane', 'phospholipid']).
sentence(s_book_05_0027, 'book', 5, 25, 'unmarked', "This matters for the origin of life because the simpler molecules are the plausible ones.").
hedged(s_book_05_0027).
sentence(s_book_05_0028, 'book', 5, 25, 'unmarked', "Fatty acids are short, single-tailed, and form readily under prebiotic conditions and in meteorites.").
sentence(s_book_05_0029, 'book', 5, 25, 'unmarked', "Under the right concentration and acidity they also form vesicles rather than micelles.").
sentence(s_book_05_0030, 'book', 5, 25, 'unmarked', "Laboratory work has shown such vesicles growing by taking up more fatty acid, dividing when pushed through narrow pores or agitated, and enclosing larger molecules including RNA while they do it.").
sentence(s_book_05_0031, 'book', 5, 29, 'unmarked', "Compartments provide several advantages:").
sentence(s_book_05_0032, 'book', 5, 31, 'unmarked', "- They concentrate molecules in a limited space. - They reduce the dispersal of useful reaction products. - They create differences between internal and external environments. - They allow chemical networks to interact repeatedly. - They make it possible for local conditions to be maintained. - They create units that may persist, grow, divide, or be selected as a whole.").
hedged(s_book_05_0032).
sentence(s_book_05_0033, 'book', 5, 38, 'unmarked', "The last of these does more work than the others.").
sentence(s_book_05_0034, 'book', 5, 38, 'unmarked', "The first five improve the chemistry.").
number(s_book_05_0034, 5, 'improve').
keywords(s_book_05_0034, ['chemistry', 'first', 'improve']).
sentence(s_book_05_0035, 'book', 5, 38, 'unmarked', "The sixth changes what the chemistry is subject to.").
sentence(s_book_05_0036, 'book', 5, 42, 'unmarked', "Without a boundary, a productive reaction is a local event whose products diffuse away and benefit nothing in particular.").
sentence(s_book_05_0037, 'book', 5, 42, 'unmarked', "With a boundary, the products stay with the system that made them, and systems can be compared.").
sentence(s_book_05_0038, 'book', 5, 44, 'unmarked', "That comparison does not require heredity, genes, or life.").
sentence(s_book_05_0039, 'book', 5, 44, 'unmarked', "It requires only variation among compartments and differences in how long they last — which is the minimum condition for selection stated in chapter 2.").
xref(s_book_05_0039, 2).
sentence(s_book_05_0040, 'book', 5, 46, 'unmarked', "There is a demonstrated version of this that is worth describing, because it shows the mechanism rather than asserting it.").
sentence(s_book_05_0041, 'book', 5, 46, 'unmarked', "Fatty acid vesicles are in constant exchange with their surroundings and with each other; molecules leave the membrane and join other membranes.").
sentence(s_book_05_0042, 'book', 5, 46, 'unmarked', "A vesicle containing more dissolved material has higher osmotic pressure inside, which places its membrane under tension.").
sentence(s_book_05_0043, 'book', 5, 46, 'unmarked', "A membrane under tension takes up fatty acid more readily.").
sentence(s_book_05_0044, 'book', 5, 46, 'unmarked', "The consequence, observed in the laboratory, is that vesicles with more encapsulated content grow — and they grow at the expense of emptier vesicles nearby, which shrink as their membrane molecules migrate.").
sentence(s_book_05_0045, 'book', 5, 48, 'unmarked', "A compartment that happens to contain more is therefore better at acquiring the material it is made of.").
sentence(s_book_05_0046, 'book', 5, 48, 'unmarked', "No information is copied, nothing is inherited, and no organism is involved.").
sentence(s_book_05_0047, 'book', 5, 48, 'unmarked', "Physical competition between compartments is already underway, driven by osmotic pressure and membrane mechanics alone.").
sentence(s_book_05_0048, 'book', 5, 50, 'unmarked', "This is as close as chemistry comes to selection without life, and it arrives early, from the geometry of amphiphilic molecules and the behaviour of water.").
sentence(s_book_05_0049, 'book', 5, 54, 'unmarked', "A membrane also does something beyond containment.").
sentence(s_book_05_0050, 'book', 5, 54, 'unmarked', "It can hold a difference in the concentration and electrical charge of ions between its two sides — an electrochemical gradient.").
number(s_book_05_0050, 2, 'side').
keywords(s_book_05_0050, ['charge', 'concentration', 'difference', 'electrical', 'electrochemical', 'gradient']).
sentence(s_book_05_0051, 'book', 5, 56, 'unmarked', "A watermill is a reasonable way to picture this, kept as a picture rather than a mechanism.").
sentence(s_book_05_0052, 'book', 5, 56, 'unmarked', "A watermill does no work on its own; it extracts work from water moving down a height difference that something else maintains.").
sentence(s_book_05_0053, 'book', 5, 56, 'unmarked', "A membrane holding more of a given ion on one side than the other maintains a difference of the same general kind, and processes in the membrane can be driven by letting that difference discharge.").
sentence(s_book_05_0054, 'book', 5, 56, 'unmarked', "Instead of water and differences in elevation along a river, the energy is derived from charged ions and differential charges across a membrane.").
sentence(s_book_05_0055, 'book', 5, 58, 'unmarked', "This is central to how modern cells handle energy.").
sentence(s_book_05_0056, 'book', 5, 58, 'unmarked', "Both respiration and photosynthesis work by pumping protons across a membrane and then using the return flow to drive synthesis.").
sentence(s_book_05_0057, 'book', 5, 58, 'unmarked', "Imagine the watermill again, with buckets of water carried by hand back to the top of the river so that more water flows through the mill and keeps it turning; the pumping is the carrying.").
sentence(s_book_05_0058, 'book', 5, 58, 'unmarked', "The analogy is useful; the inference that early compartments possessed anything like this machinery is not available.").
sentence(s_book_05_0059, 'book', 5, 58, 'unmarked', "Modern membrane bioenergetics is elaborate and evolved.").
sentence(s_book_05_0060, 'book', 5, 58, 'unmarked', "What the earliest compartments plausibly had was the simpler precondition: a boundary across which a difference could exist at all.").
hedged(s_book_05_0060).
sentence(s_book_05_0061, 'book', 5, 60, 'unmarked', "Some proposals for the origin of life invert the usual order here and start from gradients that already existed — the natural differences in acidity and chemistry across the mineral walls of alkaline hydrothermal vents, where the geology supplies the gradient and the first membranes only have to take advantage of it.").
sentence(s_book_05_0062, 'book', 5, 62, 'unmarked', "Compartmentalization makes local chemical organization possible.").
sentence(s_book_05_0063, 'book', 5, 62, 'unmarked', "It also makes local chemical organization comparable, which is the part that matters for everything after.").
chapter('book', 6, "06-metacompartmentalization.md", "6. Metacompartmentalization, distributed labour, and emergence").
sentence(s_book_06_0001, 'book', 6, 3, 'unmarked', "Compartmentalization can happen more than once.").
sentence(s_book_06_0002, 'book', 6, 5, 'unmarked', "A compartment can contain smaller compartments, and multiple compartments can be organized into a larger one.").
sentence(s_book_06_0003, 'book', 6, 5, 'unmarked', "This nested arrangement can be called metacompartmentalization, and it describes organization developing across several levels at once:").
sentence(s_book_06_0004, 'book', 6, 7, 'unmarked', "- Molecules form interacting chemical networks. - Networks operate within compartments. - Compartments develop into or contribute to cells. - Cells organize into tissues. - Tissues combine into organs. - Organs operate together within organisms. - Organisms interact within populations and ecosystems.").
sentence(s_book_06_0005, 'book', 6, 15, 'unmarked', "At each level the larger system can develop properties absent from any component alone.").
sentence(s_book_06_0006, 'book', 6, 19, 'unmarked', "Nesting creates the opportunity for distributed labour.").
sentence(s_book_06_0007, 'book', 6, 21, 'unmarked', "In a chemical network, different reactions contribute different functions.").
sentence(s_book_06_0008, 'book', 6, 21, 'unmarked', "In a cell, different molecules and structures perform specialized tasks.").
sentence(s_book_06_0009, 'book', 6, 21, 'unmarked', "In a multicellular organism, cells become specialized; in organisms with organs, tissues perform complementary functions.").
sentence(s_book_06_0010, 'book', 6, 23, 'unmarked', "Specialization increases what the whole can do.").
sentence(s_book_06_0011, 'book', 6, 23, 'unmarked', "Rather than every component doing everything adequately, components become good at particular things.").
sentence(s_book_06_0012, 'book', 6, 25, 'unmarked', "It is also irreversible in a specific and consequential way.").
sentence(s_book_06_0013, 'book', 6, 25, 'unmarked', "A component that becomes highly effective at one task generally loses the ability to function alone.").
sentence(s_book_06_0014, 'book', 6, 25, 'unmarked', "A liver cell cannot live as a free organism.").
sentence(s_book_06_0015, 'book', 6, 25, 'unmarked', "A mitochondrion cannot be cultured.").
certainty_word(s_book_06_0015, 'cannot be').
sentence(s_book_06_0016, 'book', 6, 25, 'unmarked', "The larger system must then coordinate its parts, move resources between them, regulate internal conditions, and manage conflicts between what suits a component and what suits the whole.").
sentence(s_book_06_0017, 'book', 6, 27, 'unmarked', "So the route to complexity runs:").
sentence(s_book_06_0018, 'book', 6, 29, 'unmarked', "Containment → interaction → specialization → interdependence → coordination → emergence").
sentence(s_book_06_0019, 'book', 6, 31, 'unmarked', "This is a pattern, not a progression.").
sentence(s_book_06_0020, 'book', 6, 31, 'unmarked', "Greater complexity is not more stable or more successful; specialization introduces dependencies, and a failure in one component propagates.").
sentence(s_book_06_0021, 'book', 6, 31, 'unmarked', "Many lineages have become simpler, and parasites routinely discard entire organ systems their hosts can supply instead.").
sentence(s_book_06_0022, 'book', 6, 35, 'unmarked', "Evolutionary biology has a name for the events this chapter describes, and a short list of them.").
sentence(s_book_06_0023, 'book', 6, 37, 'unmarked', "John Maynard Smith and Eörs Szathmáry proposed in 1995 that the history of life is punctuated by a small number of major transitions, each sharing a common signature: entities capable of independent replication before the transition become capable of replicating only as part of a larger whole afterwards.").
year(s_book_06_0023, 1995).
keywords(s_book_06_0023, ['afterward', 'become', 'capable', 'common', 'entity', 'history', 'independent', 'larger', 'major', 'maynard', 'number', 'proposed', 'punctuated', 'replicating', 'replication', 'sharing', 'signature', 'small', 'smith', 'szathm', 'transition', 'whole']).
hedged(s_book_06_0023).
cites(s_book_06_0023, 'Maynard Smith', 1995).
cites(s_book_06_0023, 'Szathmáry', 1995).
sentence(s_book_06_0024, 'book', 6, 39, 'unmarked', "Their list has eight entries.").
number(s_book_06_0024, 8, 'entry').
keywords(s_book_06_0024, ['eight', 'entry']).
sentence(s_book_06_0025, 'book', 6, 39, 'unmarked', "It runs from replicating molecules becoming enclosed in compartments; through independent replicators becoming linked into chromosomes; through the division of labour between DNA as information and protein as function; through prokaryotic cells becoming eukaryotic; through asexual lineages becoming sexual populations; through single cells becoming multicellular organisms; through solitary individuals becoming colonies in which most members do not reproduce; to human societies organized by language.").
sentence(s_book_06_0026, 'book', 6, 41, 'unmarked', "The specific list is disputed, and the disputes are instructive.").
hedged(s_book_06_0026).
sentence(s_book_06_0027, 'book', 6, 41, 'unmarked', "Critics have argued that the eight entries lack theoretical unity — that they were assembled because each is a large change rather than because they share a mechanism.").
number(s_book_06_0027, 8, 'entry').
keywords(s_book_06_0027, ['argued', 'assembled', 'because', 'change', 'critic', 'eight', 'entry', 'large', 'mechanism', 'rather', 'share', 'theoretical', 'unity']).
hedged(s_book_06_0027).
sentence(s_book_06_0028, 'book', 6, 41, 'unmarked', "The sexual-reproduction entry in particular is questioned, since it is not obvious that it fits that signature.").
sentence(s_book_06_0029, 'book', 6, 41, 'unmarked', "Some argue the appearance of nervous systems should be on the list and is not.").
sentence(s_book_06_0030, 'book', 6, 41, 'unmarked', "The framework has been revised more than once since.").
sentence(s_book_06_0031, 'book', 6, 43, 'unmarked', "The signature is the part that survives the dispute, and it is the useful part.").
sentence(s_book_06_0032, 'book', 6, 43, 'unmarked', "Each transition converts independent things into parts, and the conversion is what the word metacompartmentalization is pointing at.").
sentence(s_book_06_0033, 'book', 6, 43, 'unmarked', "A free-living bacterium becomes an organelle.").
sentence(s_book_06_0034, 'book', 6, 43, 'unmarked', "A free-living cell becomes a tissue cell.").
sentence(s_book_06_0035, 'book', 6, 43, 'unmarked', "An organism that could reproduce becomes a sterile worker.").
sentence(s_book_06_0036, 'book', 6, 45, 'unmarked', "Something is given up every time, and it is always the same thing: the capacity to continue alone, exchanged for a dependency on cooperation.").
certainty_word(s_book_06_0036, 'always').
sentence(s_book_06_0037, 'book', 6, 49, 'unmarked', "The sharpest documented case is the origin of mitochondria and chloroplasts.").
sentence(s_book_06_0038, 'book', 6, 51, 'unmarked', "The endosymbiotic account holds that both descend from free-living bacteria taken up by ancestral eukaryotic cells, which then developed permanent relationships with their hosts.").
sentence(s_book_06_0039, 'book', 6, 51, 'unmarked', "Mitochondria trace to a group of bacteria related to modern alphaproteobacteria; chloroplasts to cyanobacteria.").
sentence(s_book_06_0040, 'book', 6, 53, 'unmarked', "The evidence is unusually direct.").
sentence(s_book_06_0041, 'book', 6, 53, 'unmarked', "Both organelles retain their own circular DNA, distinct from the cell's nuclear genome.").
sentence(s_book_06_0042, 'book', 6, 53, 'unmarked', "Both have their own ribosomes, and those ribosomes resemble bacterial ribosomes rather than the host's — closely enough that some antibiotics targeting bacterial protein synthesis also affect them.").
sentence(s_book_06_0043, 'book', 6, 53, 'unmarked', "Both are enclosed by a double membrane, consistent with having been engulfed.").
sentence(s_book_06_0044, 'book', 6, 53, 'unmarked', "Both divide by splitting rather than being built from scratch.").
sentence(s_book_06_0045, 'book', 6, 55, 'unmarked', "The proposal was not well received.").
hedged(s_book_06_0045).
sentence(s_book_06_0046, 'book', 6, 55, 'unmarked', "Lynn Margulis — publishing in 1967 under the name Lynn Sagan — recalled that the paper that set out the modern case was turned down by around fifteen journals before the Journal of Theoretical Biology took it.").
year(s_book_06_0046, 1967).
number(s_book_06_0046, 15, 'journal').
keywords(s_book_06_0046, ['biology', 'fifteen', 'journal', 'marguli', 'modern', 'paper', 'publishing', 'recalled', 'sagan', 'theoretical', 'turned']).
cites(s_book_06_0046, 'Margulis', 1967).
sentence(s_book_06_0047, 'book', 6, 55, 'unmarked', "The idea remained marginal for years afterwards.").
sentence(s_book_06_0048, 'book', 6, 55, 'unmarked', "Molecular sequencing eventually made it difficult to dispute.").
sentence(s_book_06_0049, 'book', 6, 55, 'unmarked', "It is now standard biology, taught as settled.").
sentence(s_book_06_0050, 'book', 6, 57, 'unmarked', "The episode is worth remembering for the same reason the appendix is worth remembering in chapter 9: the confidence of a field at a given moment is not the same thing as the evidence.").
xref(s_book_06_0050, 9).
sentence(s_book_06_0051, 'book', 6, 57, 'unmarked', "It is also worth not over-reading.").
sentence(s_book_06_0052, 'book', 6, 57, 'unmarked', "A theory being rejected many times and later vindicated is a real pattern, and it is not evidence about any particular rejected theory.").
sentence(s_book_06_0053, 'book', 6, 57, 'unmarked', "Most ideas that fifteen journals decline are declined correctly.").
number(s_book_06_0053, 15, 'journal').
keywords(s_book_06_0053, ['correctly', 'decline', 'declined', 'fifteen', 'journal']).
sentence(s_book_06_0054, 'book', 6, 59, 'unmarked', "The most telling detail concerns where the genes went.").
sentence(s_book_06_0055, 'book', 6, 59, 'unmarked', "The ancestral bacterium would have carried something on the order of a few thousand genes.").
sentence(s_book_06_0056, 'book', 6, 59, 'unmarked', "The human mitochondrial genome carries thirty-seven.").
number(s_book_06_0056, 37, 'none').
keywords(s_book_06_0056, ['carry', 'genome', 'human', 'mitochondrial', 'thirty-seven']).
sentence(s_book_06_0057, 'book', 6, 59, 'unmarked', "The rest were not discarded — the great majority migrated to the host cell's nucleus, where they remain, still producing proteins that are manufactured in the main body of the cell and then imported back into the mitochondrion.").
sentence(s_book_06_0058, 'book', 6, 61, 'unmarked', "The organelle did not merely become dependent.").
sentence(s_book_06_0059, 'book', 6, 61, 'unmarked', "It handed over the instructions for building itself.").
sentence(s_book_06_0060, 'book', 6, 61, 'unmarked', "Integration at this level is not cooperation between two parties; it is the construction of a single system that can no longer be separated into the things it was made from.").
number(s_book_06_0060, 2, 'party').
keywords(s_book_06_0060, ['construction', 'cooperation', 'integration', 'level', 'longer', 'party', 'separated', 'single', 'system', 'thing']).
sentence(s_book_06_0061, 'book', 6, 63, 'unmarked', "Endosymbiosis also shows that new levels of organization need not arise by one lineage gradually specializing.").
sentence(s_book_06_0062, 'book', 6, 63, 'unmarked', "They can arise by combination — two evolutionary histories merging into one.").
number(s_book_06_0062, 2, 'evolutionary').
keywords(s_book_06_0062, ['arise', 'combination', 'evolutionary', 'history', 'merging']).
sentence(s_book_06_0063, 'book', 6, 67, 'unmarked', "Every statement above has described nesting as though it happened and then stayed.").
sentence(s_book_06_0064, 'book', 6, 67, 'unmarked', "It does not stay by itself.").
sentence(s_book_06_0065, 'book', 6, 69, 'unmarked', "A multicellular organism is a cooperative arrangement among cells, many of which remain, individually, capable of replicating.").
sentence(s_book_06_0066, 'book', 6, 69, 'unmarked', "They carry machinery for division that predates animal multicellularity by a billion years.").
sentence(s_book_06_0067, 'book', 6, 69, 'unmarked', "The organism works only because that capacity is held in check — by signals that tell a cell when to divide and when to stop, by programmed cell death removing cells that malfunction, by immune surveillance.").
sentence(s_book_06_0068, 'book', 6, 71, 'unmarked', "Cancer is what the arrangement looks like when the checks fail.").
sentence(s_book_06_0069, 'book', 6, 71, 'unmarked', "A lineage of cells resumes doing what single cells do: proliferating as circumstances allow, without regard to the larger system.").
sentence(s_book_06_0070, 'book', 6, 71, 'unmarked', "It is not an invasion from outside.").
sentence(s_book_06_0071, 'book', 6, 71, 'unmarked', "It is a reversion to the level below, by cells that never lost the ability.").
certainty_word(s_book_06_0071, 'never').
sentence(s_book_06_0072, 'book', 6, 73, 'unmarked', "The same tension appears at other levels.").
hedged(s_book_06_0072).
sentence(s_book_06_0073, 'book', 6, 73, 'unmarked', "Stretches of DNA exist that are good at getting themselves copied and do nothing for the organism carrying them, sometimes at its expense.").
sentence(s_book_06_0074, 'book', 6, 73, 'unmarked', "Mechanisms exist by which a gene can bias its own chances of ending up in a gamete, against the interests of the rest of the genome.").
sentence(s_book_06_0075, 'book', 6, 73, 'unmarked', "In colonies of social insects, workers police one another's attempts to reproduce — an odd behaviour that leaves one queen bee laying nearly all of a hive's eggs while most of the population works and dies without ever reproducing.").
sentence(s_book_06_0076, 'book', 6, 75, 'unmarked', "The general shape is this: a higher level of organization persists only while it suppresses competition at the level below it, and the suppression is never complete.").
certainty_word(s_book_06_0076, 'never').
sentence(s_book_06_0077, 'book', 6, 75, 'unmarked', "Every level of nesting is an ongoing arrangement rather than a settled fact, maintained against a lower level that has not forgotten how to act for itself.").
sentence(s_book_06_0078, 'book', 6, 77, 'unmarked', "This is the same structure as chapter 4's dissipative structures, one scale up.").
xref(s_book_06_0078, 4).
sentence(s_book_06_0079, 'book', 6, 77, 'unmarked', "A convection cell persists only while energy flows through it.").
sentence(s_book_06_0080, 'book', 6, 77, 'unmarked', "A multicellular organism persists only while it keeps putting down its own cells.").
sentence(s_book_06_0081, 'book', 6, 77, 'unmarked', "Neither is a thing that was built and now endures.").
sentence(s_book_06_0082, 'book', 6, 77, 'unmarked', "Both are processes that have to keep going to survive, almost like a tontine the cells never signed up for but are locked into all the same.").
certainty_word(s_book_06_0082, 'never').
sentence(s_book_06_0083, 'book', 6, 79, 'unmarked', "It also supplies the caution this chapter needs.").
sentence(s_book_06_0084, 'book', 6, 79, 'unmarked', "Nesting is not an achievement that accumulates safely.").
sentence(s_book_06_0085, 'book', 6, 79, 'unmarked', "It is a cost that has to be paid continuously, and when payment stops, the level below is still there — be it cancer, parasites, or death.").
chapter('book', 7, "07-the-human-microbiome.md", "7. The human microbiome: an organism within a larger ecosystem").
sentence(s_book_07_0001, 'book', 7, 3, 'unmarked', "The human microbiome provides another important example of metacompartmentalization and distributed biological labour.").
sentence(s_book_07_0002, 'book', 7, 5, 'unmarked', "The human body is not a collection of human cells operating independently.").
sentence(s_book_07_0003, 'book', 7, 5, 'unmarked', "It is also home to diverse microbial communities — bacteria, archaea, fungi, and viruses — occupying different environments including the skin, mouth, gut, and other sites.").
sentence(s_book_07_0004, 'book', 7, 7, 'unmarked', "Those populations are not distributed uniformly.").
sentence(s_book_07_0005, 'book', 7, 7, 'unmarked', "Different parts of the body present different physical and chemical conditions, and different conditions support different communities.").
sentence(s_book_07_0006, 'book', 7, 11, 'unmarked', "The gut contains a complex microbial ecosystem whose members interact with one another, with food, and with the host.").
sentence(s_book_07_0007, 'book', 7, 11, 'unmarked', "Microbial functions there include:").
sentence(s_book_07_0008, 'book', 7, 13, 'unmarked', "- Breaking down dietary compounds that human enzymes cannot fully digest. - Producing metabolites usable by the host or by other microbes. - Contributing to the development and regulation of immune responses. - Competing with potential pathogens for space and resources. - Transforming compounds, including some involved in drug metabolism. - Participating in networks of metabolic exchange.").
sentence(s_book_07_0009, 'book', 7, 20, 'unmarked', "These functions are distributed across many organisms.").
sentence(s_book_07_0010, 'book', 7, 20, 'unmarked', "One species may produce a compound another species consumes.").
hedged(s_book_07_0010).
sentence(s_book_07_0011, 'book', 7, 20, 'unmarked', "The products of one metabolic pathway become the inputs of another.").
sentence(s_book_07_0012, 'book', 7, 20, 'unmarked', "The community's overall activity therefore depends on interactions among organisms rather than on the capabilities of any single species.").
sentence(s_book_07_0013, 'book', 7, 22, 'unmarked', "This resembles the distributed labour of a multicellular organism, and the resemblance has a limit worth stating.").
sentence(s_book_07_0014, 'book', 7, 22, 'unmarked', "Microbes are separate organisms with their own evolutionary interests.").
sentence(s_book_07_0015, 'book', 7, 22, 'unmarked', "Their interactions include cooperation, competition, and exploitation, and the balance shifts with conditions.").
sentence(s_book_07_0016, 'book', 7, 22, 'unmarked', "Cells in a body share a genome and mostly share a fate.").
sentence(s_book_07_0017, 'book', 7, 22, 'unmarked', "Members of a microbial community do not.").
sentence(s_book_07_0018, 'book', 7, 26, 'unmarked', "The skin makes the same point from a different direction, and more sharply, because it is the surface where host and microbe actually negotiate.").
sentence(s_book_07_0019, 'book', 7, 28, 'unmarked', "Terrestrial life did not emerge into a sterile world.").
sentence(s_book_07_0020, 'book', 7, 28, 'unmarked', "By the time the first vertebrates moved onto land, bacteria had been colonizing every available surface for billions of years — in biofilms on rock, in soil consortia, in mats along tidal margins.").
sentence(s_book_07_0021, 'book', 7, 28, 'unmarked', "Skin as it now exists — layered, cornified, chemically selective — evolved into that environment.").
sentence(s_book_07_0022, 'book', 7, 28, 'unmarked', "It did not evolve first and then get colonized.").
sentence(s_book_07_0023, 'book', 7, 30, 'unmarked', "That changes what the barrier is for.").
sentence(s_book_07_0024, 'book', 7, 30, 'unmarked', "The outermost layer, the stratum corneum, is often described as bricks and mortar: flattened dead cells called corneocytes, embedded in a lipid matrix of ceramides, cholesterol, and free fatty acids.").
sentence(s_book_07_0025, 'book', 7, 30, 'unmarked', "The usual reading is a wall built to keep organisms out.").
sentence(s_book_07_0026, 'book', 7, 30, 'unmarked', "A better reading is an interface tuned over long co-evolution to be habitable by some organisms and not others.").
sentence(s_book_07_0027, 'book', 7, 32, 'unmarked', "Consider what those cells give up.").
sentence(s_book_07_0028, 'book', 7, 32, 'unmarked', "As a keratinocyte moves towards the surface it degrades its own nucleus and organelles, ending as a protein-filled husk.").
sentence(s_book_07_0029, 'book', 7, 32, 'unmarked', "It cannot divide, repair itself, or respond.").
sentence(s_book_07_0030, 'book', 7, 32, 'unmarked', "It also cannot be hijacked by a pathogen that needs host machinery to replicate, and it cannot accumulate ultraviolet damage in a genome it no longer has.").
certainty_word(s_book_07_0030, 'cannot be').
sentence(s_book_07_0031, 'book', 7, 32, 'unmarked', "The cell trades everything it could do for the one property the barrier needs, which is to be inert.").
sentence(s_book_07_0032, 'book', 7, 34, 'unmarked', "The surface is not uniform.").
sentence(s_book_07_0033, 'book', 7, 34, 'unmarked', "Moist sites such as the armpit, oily sites such as the forehead and upper back, and dry exposed sites such as the forearm differ in acidity, lipid composition, moisture, and antimicrobial peptide concentration.").
sentence(s_book_07_0034, 'book', 7, 34, 'unmarked', "Different communities occupy each.").
sentence(s_book_07_0035, 'book', 7, 34, 'unmarked', "Bacteria tolerant of oil-rich, low-oxygen conditions dominate sebaceous (\"greasy\") sites; different types of bacteria dominate moist ones.").
sentence(s_book_07_0036, 'book', 7, 34, 'unmarked', "Two sites on the same person can differ more from each other than the same site differs between two people.").
number(s_book_07_0036, 2, 'site').
number(s_book_07_0036, 2, 'people').
keywords(s_book_07_0036, ['differ', 'people', 'person']).
sentence(s_book_07_0037, 'book', 7, 36, 'unmarked', "That variation is not noise.").
sentence(s_book_07_0038, 'book', 7, 36, 'unmarked', "It is a record of how many separate arrangements one organism's surface maintains at once.").
sentence(s_book_07_0039, 'book', 7, 40, 'unmarked', "Two things follow that are worth stating plainly.").
number(s_book_07_0039, 2, 'thing').
keywords(s_book_07_0039, ['follow', 'plainly', 'stating', 'thing', 'worth']).
sentence(s_book_07_0040, 'book', 7, 42, 'unmarked', "The first is that the skin does not assemble its microbiome.").
sentence(s_book_07_0041, 'book', 7, 42, 'unmarked', "It sets conditions — acidity, available lipids, moisture, salt, antimicrobial peptides — and the community that establishes itself is whichever one happens to tolerate them.").
sentence(s_book_07_0042, 'book', 7, 42, 'unmarked', "The barrier specifies an envelope and lets chemistry resolve the rest.").
sentence(s_book_07_0043, 'book', 7, 42, 'unmarked', "This is the same procedure as the tidal pool in chapter 3, on a different substrate and timescale: produce conditions, let differential persistence sort the outcome.").
xref(s_book_07_0043, 3).
sentence(s_book_07_0044, 'book', 7, 42, 'unmarked', "Nothing selects in the sense of choosing.").
sentence(s_book_07_0045, 'book', 7, 44, 'unmarked', "The second is that the barrier is not a structure so much as a process.").
sentence(s_book_07_0046, 'book', 7, 44, 'unmarked', "The stratum corneum is continuously rebuilt from beneath and continuously shed, turning over on a timescale of weeks.").
sentence(s_book_07_0047, 'book', 7, 44, 'unmarked', "The outer layer of skin on a hand at this moment was not there a month ago and will not be there a month from now.").
sentence(s_book_07_0048, 'book', 7, 44, 'unmarked', "It is a dissipative structure at the scale of an organ — its persistence depends entirely on not stopping.").
sentence(s_book_07_0049, 'book', 7, 44, 'unmarked', "Interrupt the turnover and the result is not a stable barrier but one that fails at the first injury or test of its stability.").
sentence(s_book_07_0050, 'book', 7, 46, 'unmarked', "The relationship runs both ways, which is the part that resists the wall metaphor most.").
sentence(s_book_07_0051, 'book', 7, 46, 'unmarked', "Animals raised without any microbial exposure develop differently: their skin immune environment does not mature normally, and specific commensal (\"resident\") bacteria have been shown to tune local immune responses independently of anything happening in the gut.").
sentence(s_book_07_0052, 'book', 7, 46, 'unmarked', "The microbial community is not a population the barrier tolerates.").
sentence(s_book_07_0053, 'book', 7, 46, 'unmarked', "It participates in building it.").
sentence(s_book_07_0054, 'book', 7, 50, 'unmarked', "A brief detour into method, because the measurement technique is itself an instance of the book's subject.").
sentence(s_book_07_0055, 'book', 7, 52, 'unmarked', "Most of what is known about microbial communities comes from sequencing a single gene: the one encoding the 16S ribosomal RNA, a structural component of the bacterial ribosome.").
sentence(s_book_07_0056, 'book', 7, 52, 'unmarked', "It has an unusual property.").
sentence(s_book_07_0057, 'book', 7, 52, 'unmarked', "Along its length, stretches that are nearly identical across the entire bacterial domain alternate with stretches that differ substantially between lineages.").
sentence(s_book_07_0058, 'book', 7, 54, 'unmarked', "Neither pattern is accidental.").
sentence(s_book_07_0059, 'book', 7, 54, 'unmarked', "The conserved stretches sit in the parts of the molecule that do the work of translation (protein building), and translation is not optional — a lineage that mutates there does not continue.").
sentence(s_book_07_0060, 'book', 7, 54, 'unmarked', "The variable stretches sit in parts where the sequence matters less, and over billions of years they have drifted freely.").
sentence(s_book_07_0061, 'book', 7, 56, 'unmarked', "So a single molecule carries two records at once: what selection could never permit to change, and what it never had reason to protect.").
number(s_book_07_0061, 2, 'record').
keywords(s_book_07_0061, ['carry', 'change', 'could', 'molecule', 'never', 'permit', 'protect', 'reason', 'record', 'selection', 'single']).
certainty_word(s_book_07_0061, 'never').
certainty_word(s_book_07_0061, 'never').
sentence(s_book_07_0062, 'book', 7, 56, 'unmarked', "The gene is a map of its own constraint.").
sentence(s_book_07_0063, 'book', 7, 58, 'unmarked', "That structure is what makes the measurement possible at all.").
sentence(s_book_07_0064, 'book', 7, 58, 'unmarked', "The conserved regions give chemical handles that work on essentially any bacterium, known or unknown.").
hedged(s_book_07_0064).
sentence(s_book_07_0065, 'book', 7, 58, 'unmarked', "The variable regions in between carry the differences that identify which bacterium it was.").
sentence(s_book_07_0066, 'book', 7, 58, 'unmarked', "Amplify the gene from a sample, read the variable regions, compare against a reference, and the organisms present can be named without any of them ever being grown in culture — which matters, because most of them cannot be.").
certainty_word(s_book_07_0066, 'cannot be').
sentence(s_book_07_0067, 'book', 7, 60, 'unmarked', "Carl Woese used this gene in 1977 to establish that archaea are a primary branch of life distinct from bacteria — what he later named a domain — which is among the larger revisions in the history of biological classification and was arrived at by reading a single molecule's record of its own constraints.").
year(s_book_07_0067, 1977).
keywords(s_book_07_0067, ['among', 'archaea', 'arrived', 'bacteria', 'biological', 'branch', 'classification', 'constraint', 'distinct', 'domain', 'establish', 'history', 'larger', 'later', 'molecule', 'named', 'primary', 'reading', 'record', 'revision', 'single', 'woese']).
cites(s_book_07_0067, 'Woese', 1977).
sentence(s_book_07_0068, 'book', 7, 62, 'unmarked', "The method has real limits and the honesty of the chapter depends on naming them.").
sentence(s_book_07_0069, 'book', 7, 62, 'unmarked', "Species carry different numbers of copies of the gene, which distorts abundance estimates.").
sentence(s_book_07_0070, 'book', 7, 62, 'unmarked', "Resolution often stops at genus.").
sentence(s_book_07_0071, 'book', 7, 62, 'unmarked', "The amplification step introduces biases.").
sentence(s_book_07_0072, 'book', 7, 62, 'unmarked', "And it sees bacteria and archaea only — the fungi and viruses in the same communities require other approaches entirely.").
sentence(s_book_07_0073, 'book', 7, 66, 'unmarked', "A microbial community can collectively perform transformations no single member performs alone.").
sentence(s_book_07_0074, 'book', 7, 66, 'unmarked', "Its composition affects nutrient availability, metabolite production, resistance to colonization by pathogens, and interaction with the immune system.").
sentence(s_book_07_0075, 'book', 7, 68, 'unmarked', "These effects depend on which organisms are present, in what proportions, doing what, in which environment.").
sentence(s_book_07_0076, 'book', 7, 68, 'unmarked', "The same species can have different effects in different contexts; a function useful in one community may be useless or harmful in another.").
hedged(s_book_07_0076).
sentence(s_book_07_0077, 'book', 7, 70, 'unmarked', "The microbiome therefore cannot be understood as a list of species.").
certainty_word(s_book_07_0077, 'cannot be').
sentence(s_book_07_0078, 'book', 7, 70, 'unmarked', "What matters is the relationships — among organisms, their genes, their chemical products, and the conditions they share.").
sentence(s_book_07_0079, 'book', 7, 72, 'unmarked', "This also complicates where an individual organism begins and ends.").
sentence(s_book_07_0080, 'book', 7, 72, 'unmarked', "A human body has a clear physical boundary, but a great many of its functions are influenced by organisms living within and upon it.").
sentence(s_book_07_0081, 'book', 7, 74, 'unmarked', "The term holobiont is sometimes used for a host together with its associated microorganisms.").
sentence(s_book_07_0082, 'book', 7, 74, 'unmarked', "It usefully emphasizes interdependence.").
sentence(s_book_07_0083, 'book', 7, 74, 'unmarked', "It should not be taken to mean that host and microbes form a single evolutionary individual: the degree of integration, the stability of the association, and the extent of shared interest all vary, and in many cases the interests diverge outright.").
sentence(s_book_07_0084, 'book', 7, 76, 'unmarked', "The microbiome illustrates several recurring concepts:").
sentence(s_book_07_0085, 'book', 7, 78, 'unmarked', "- Metacompartmentalization: microbial communities occupy specialized environments within a larger organism. - Distributed labour: different organisms contribute different metabolic and ecological functions. - Interdependence: organisms exchange resources and influence one another's survival. - Emergence: community-level properties arise through interactions among members. - Selection: host conditions and microbial competition determine which populations persist. - Feedback: microbial activity alters the environment, which alters the community.").
sentence(s_book_07_0086, 'book', 7, 85, 'unmarked', "It is a useful example because it shows that biological complexity does not always come from one organism becoming more internally specialized.").
certainty_word(s_book_07_0086, 'always').
sentence(s_book_07_0087, 'book', 7, 85, 'unmarked', "It can also arise from relationships among organisms that remain distinct.").
sentence(s_book_07_0088, 'book', 7, 89, 'unmarked', "The same kind of community can be grown from a handful of mud.").
sentence(s_book_07_0089, 'book', 7, 89, 'unmarked', "A Winogradsky column, named for the microbiologist Sergei Winogradsky, who devised it, is a clear tube filled with sediment enriched with a source of cellulose, such as leaf litter, and a source of sulfate, then left in the light.").
sentence(s_book_07_0090, 'book', 7, 89, 'unmarked', "No organisms are added.").
sentence(s_book_07_0091, 'book', 7, 89, 'unmarked', "Over the following weeks the mud sorts itself into layers, and the sorting can be watched through the wall.").
sentence(s_book_07_0092, 'book', 7, 91, 'unmarked', "The colours are chemistry.").
sentence(s_book_07_0093, 'book', 7, 91, 'unmarked', "At the top there is oxygen, and it falls away with depth, so the mud below is anoxic, without oxygen.").
sentence(s_book_07_0094, 'book', 7, 91, 'unmarked', "Decomposers break the cellulose into simpler carbon compounds that other microbes ferment.").
sentence(s_book_07_0095, 'book', 7, 91, 'unmarked', "Down in the anoxic mud, bacteria respire sulfate in place of oxygen and release hydrogen sulfide, which combines with iron to form ferrous sulfide; the mud turns black, in one study within the first week.").
sentence(s_book_07_0096, 'book', 7, 91, 'unmarked', "The sulfide diffuses upwards towards the oxygen, so each depth offers a different mix, and a different niche.").
sentence(s_book_07_0097, 'book', 7, 93, 'unmarked', "Bacteria that use hydrogen sulfide in photosynthesis live where light and sulfide overlap.").
sentence(s_book_07_0098, 'book', 7, 93, 'unmarked', "Green sulfur bacteria typically form a green zone in the lower middle of the column, and purple bacteria a red-violet zone above it.").
sentence(s_book_07_0099, 'book', 7, 93, 'unmarked', "Near the top, patches of orange appear, most likely iron oxides.").
hedged(s_book_07_0099).
sentence(s_book_07_0100, 'book', 7, 93, 'unmarked', "On the inside of the tube, a biofilm grows that is less diverse than the mud behind it, with cyanobacteria among its commonest members; in columns kept in the dark, no visible surface community forms.").
sentence(s_book_07_0101, 'book', 7, 93, 'unmarked', "The textbook bands are typical, not guaranteed: in one survey of columns, distinct green and red-violet zones did not appear.").
hedged(s_book_07_0101).
sentence(s_book_07_0102, 'book', 7, 95, 'unmarked', "Two results matter more than the colours.").
number(s_book_07_0102, 2, 'result').
keywords(s_book_07_0102, ['colour', 'matter', 'result']).
sentence(s_book_07_0103, 'book', 7, 95, 'unmarked', "Organisms that are rare in the starting mud can become abundant once conditions suit them, so the column does not import a community; it selects one from what was already there.").
sentence(s_book_07_0104, 'book', 7, 95, 'unmarked', "And no layer is independent of the others: what grows at each depth depends on what the layers around it produce and use up.").
sentence(s_book_07_0105, 'book', 7, 97, 'author', "Here the author would go further.").
sentence(s_book_07_0106, 'book', 7, 97, 'author', "A column is not a holobiont in the sense used above, because there is no host.").
sentence(s_book_07_0107, 'book', 7, 97, 'author', "But the whole tube behaves a little like one: a self-contained system whose members live on one another's by-products, with a boundary, a division of labour, and conditions that its own residents keep remaking.").
sentence(s_book_07_0108, 'book', 7, 97, 'author', "That is where the analogy stops.").
sentence(s_book_07_0109, 'book', 7, 97, 'author', "There is no host whose interests the community serves, and no shared descent for selection to act on as a whole.").
chapter('book', 8, "08-biological-information.md", "8. The origin and development of biological information").
sentence(s_book_08_0001, 'book', 8, 3, 'unmarked', "One of the central questions in the origin of life is how chemical systems began to retain and transmit information.").
sentence(s_book_08_0002, 'book', 8, 5, 'unmarked', "The RNA world hypothesis proposes that RNA may have played an early role in both information storage and catalysis.").
hedged(s_book_08_0002).
sentence(s_book_08_0003, 'book', 8, 5, 'unmarked', "RNA can store sequence information, and some RNA molecules — ribozymes — can catalyse chemical reactions.").
sentence(s_book_08_0004, 'book', 8, 5, 'unmarked', "A single class of molecule doing both jobs is an attractive way to connect chemical activity with heredity, because it removes the need for two separate inventions.").
number(s_book_08_0004, 2, 'separate').
keywords(s_book_08_0004, ['activity', 'attractive', 'because', 'chemical', 'class', 'connect', 'doing', 'heredity', 'invention', 'molecule', 'remove', 'separate', 'single']).
sentence(s_book_08_0005, 'book', 8, 7, 'unmarked', "The RNA world remains a hypothesis about early evolution, not a complete or universally accepted account of life's origin.").
sentence(s_book_08_0006, 'book', 8, 7, 'unmarked', "Other proposals involve peptides (small protein units), metabolic networks, mineral surfaces, or some combination of these.").
sentence(s_book_08_0007, 'book', 8, 7, 'unmarked', "The framework here does not require any one of them to be correct; it identifies the organizational transition that every successful account has to explain.").
sentence(s_book_08_0008, 'book', 8, 9, 'unmarked', "Modern biological systems distribute the work across several components:").
sentence(s_book_08_0009, 'book', 8, 11, 'unmarked', "- DNA stores hereditary information. - RNA transfers and regulates it. - Proteins perform structural and catalytic work. - Ribosomes translate genetic information into proteins. - ATP moves usable chemical energy around the cell.").
sentence(s_book_08_0010, 'book', 8, 19, 'unmarked', "Something worth examining closely sits in the middle of that list: the mapping between DNA sequence and protein, the genetic code.").
sentence(s_book_08_0011, 'book', 8, 21, 'unmarked', "The mechanics are simple enough to state.").
sentence(s_book_08_0012, 'book', 8, 21, 'unmarked', "Three nucleotides make a codon.").
number(s_book_08_0012, 3, 'nucleotide').
keywords(s_book_08_0012, ['codon', 'nucleotide', 'three']).
sentence(s_book_08_0013, 'book', 8, 21, 'unmarked', "Four possible nucleotides in three positions gives 4 × 4 × 4 combinations — 64 codons.").
number(s_book_08_0013, 4, 'combination').
number(s_book_08_0013, 4, 'combination').
number(s_book_08_0013, 4, 'combination').
number(s_book_08_0013, 64, 'codon').
number(s_book_08_0013, 4, 'possible').
number(s_book_08_0013, 3, 'position').
keywords(s_book_08_0013, ['codon', 'combination', 'nucleotide', 'position', 'possible', 'three']).
sentence(s_book_08_0014, 'book', 8, 21, 'unmarked', "Those 64 specify 20 standard amino acids plus a stop instruction.").
number(s_book_08_0014, 64, 'specify').
number(s_book_08_0014, 20, 'standard').
keywords(s_book_08_0014, ['amino', 'instruction', 'specify', 'standard']).
sentence(s_book_08_0015, 'book', 8, 21, 'unmarked', "More codons than meanings means the code is redundant — several different codons specify the same amino acid.").
sentence(s_book_08_0016, 'book', 8, 23, 'unmarked', "The interesting part is that the redundancy is not spread evenly.").
sentence(s_book_08_0017, 'book', 8, 23, 'unmarked', "It has a shape.").
sentence(s_book_08_0018, 'book', 8, 25, 'unmarked', "Most of the slack sits in the third position.").
sentence(s_book_08_0019, 'book', 8, 25, 'unmarked', "For many amino acids, all four nucleotides in the third position of the codon specify the same amino acid.").
number(s_book_08_0019, 4, 'nucleotide').
keywords(s_book_08_0019, ['amino', 'codon', 'nucleotide', 'position', 'specify', 'third']).
sentence(s_book_08_0020, 'book', 8, 25, 'unmarked', "A copying error there frequently changes nothing about the resulting protein.").
sentence(s_book_08_0021, 'book', 8, 25, 'unmarked', "Such changes are called synonymous, and they are common.").
sentence(s_book_08_0022, 'book', 8, 25, 'unmarked', "The flexibility of this position is sometimes described through the wobble in how transfer RNA pairs with the third base, a mechanism proposed by Crick in 1966.").
year(s_book_08_0022, 1966).
keywords(s_book_08_0022, ['crick', 'described', 'flexibility', 'mechanism', 'position', 'proposed', 'sometime', 'third', 'transfer', 'wobble']).
hedged(s_book_08_0022).
cites(s_book_08_0022, 'Crick', 1966).
sentence(s_book_08_0023, 'book', 8, 27, 'unmarked', "The first two positions carry most of the meaning.").
number(s_book_08_0023, 2, 'position').
keywords(s_book_08_0023, ['carry', 'first', 'meaning', 'position']).
sentence(s_book_08_0024, 'book', 8, 27, 'unmarked', "A change there usually does change the amino acid.").
sentence(s_book_08_0025, 'book', 8, 27, 'unmarked', "But not arbitrarily: codons that differ at the first position tend to specify amino acids with broadly similar chemical character.").
sentence(s_book_08_0026, 'book', 8, 27, 'unmarked', "A substitution is more likely to swap one water-repelling residue for another than to replace it with something chemically opposite, and proteins frequently tolerate the former.").
hedged(s_book_08_0026).
sentence(s_book_08_0027, 'book', 8, 29, 'unmarked', "The control instructions are the least forgiving.").
sentence(s_book_08_0028, 'book', 8, 29, 'unmarked', "Start and stop signals mark where a protein begins and ends.").
sentence(s_book_08_0029, 'book', 8, 29, 'unmarked', "Disrupting them tends to produce more serious consequences than an internal substitution, because the error affects the whole product rather than one position in it.").
sentence(s_book_08_0030, 'book', 8, 29, 'unmarked', "This is a matter of degree rather than an absolute: bacteria use several alternative start codons, read-through of stop signals occurs, and some organisms and organelles run variant codes in which a standard stop has been reassigned.").
sentence(s_book_08_0031, 'book', 8, 29, 'unmarked', "The pattern holds; the exceptions are real and are part of why the code is studied as something that evolved rather than something fixed.").
sentence(s_book_08_0032, 'book', 8, 31, 'unmarked', "So errors are not treated uniformly.").
sentence(s_book_08_0033, 'book', 8, 31, 'unmarked', "Where a mistake would be cheap, the code absorbs it.").
sentence(s_book_08_0034, 'book', 8, 31, 'unmarked', "Where a mistake would be expensive, it does not.").
sentence(s_book_08_0035, 'book', 8, 35, 'unmarked', "That arrangement is what information compression looks like when it is working well: discard what can be discarded without losing the message, and protect what cannot.").
sentence(s_book_08_0036, 'book', 8, 37, 'unmarked', "The comparison is not merely impressionistic, and the standard code turns out to be unusually good at this.").
sentence(s_book_08_0037, 'book', 8, 37, 'unmarked', "Freeland and Hurst compared it in 1998 against large numbers of randomly generated alternative codes, scoring each by how much damage a copying or reading error would do.").
year(s_book_08_0037, 1998).
keywords(s_book_08_0037, ['against', 'alternative', 'compared', 'copying', 'damage', 'error', 'freeland', 'generated', 'hurst', 'large', 'number', 'randomly', 'reading', 'scoring', 'would']).
cites(s_book_08_0037, 'Freeland', 1998).
cites(s_book_08_0037, 'Hurst', 1998).
sentence(s_book_08_0038, 'book', 8, 37, 'unmarked', "Allowing for the fact that some kinds of error are more common than others, they found roughly one in a million random codes performed better than the real one.").
sentence(s_book_08_0039, 'book', 8, 37, 'unmarked', "Their paper is titled accordingly.").
sentence(s_book_08_0040, 'book', 8, 39, 'unmarked', "The figure depends on which chemical property is weighted and which model of error is assumed, and it has been argued over since.").
hedged(s_book_08_0040).
sentence(s_book_08_0041, 'book', 8, 39, 'unmarked', "One line of criticism is specific and substantial: when the differing frequencies with which organisms actually use particular codons are taken into account, the apparent optimization shrinks considerably.").
sentence(s_book_08_0042, 'book', 8, 39, 'unmarked', "The general finding — that the standard code sits far out in the tail rather than in the middle — has held up.").
sentence(s_book_08_0043, 'book', 8, 39, 'unmarked', "How far out is contested.").
hedged(s_book_08_0043).
sentence(s_book_08_0044, 'book', 8, 41, 'unmarked', "Three readings of that fact compete, and the differences matter:").
number(s_book_08_0044, 3, 'reading').
keywords(s_book_08_0044, ['compete', 'difference', 'matter', 'reading', 'three']).
sentence(s_book_08_0045, 'book', 8, 43, 'unmarked', "- Error minimization.").
sentence(s_book_08_0046, 'book', 8, 43, 'unmarked', "The code was shaped by selection, because lineages whose codes mistranslated and mutated more gracefully, without wrecking the proteins built from them, left more descendants.").
sentence(s_book_08_0047, 'book', 8, 43, 'unmarked', "The structure is then an adaptation to the error rate of the machinery reading it. - Frozen accident.").
sentence(s_book_08_0048, 'book', 8, 43, 'unmarked', "Crick's 1968 proposal: the assignments were largely arbitrary, fixed very early, and became impossible to change afterwards, since altering what a codon means rewrites every protein in the organism simultaneously.").
year(s_book_08_0048, 1968).
keywords(s_book_08_0048, ['afterward', 'altering', 'arbitrary', 'assignment', 'became', 'change', 'codon', 'crick', 'early', 'fixed', 'impossible', 'largely', 'organism', 'proposal', 'protein', 'rewrite', 'simultaneously', 'since']).
certainty_word(s_book_08_0048, 'impossible').
hedged(s_book_08_0048).
cites(s_book_08_0048, 'Crick', 1968).
sentence(s_book_08_0049, 'book', 8, 43, 'unmarked', "Any error tolerance would be partly incidental. - Neutral origin.").
sentence(s_book_08_0050, 'book', 8, 43, 'unmarked', "The most interesting of the three for this book's purposes, and the one most easily missed.").
number(s_book_08_0050, 3, 'book').
keywords(s_book_08_0050, ['easily', 'interesting', 'missed', 'purpose', 'three']).
sentence(s_book_08_0051, 'book', 8, 43, 'unmarked', "If the code grew by adding amino acids one at a time, with each new arrival assigned codons near those of a chemically similar amino acid already present, substantial error tolerance falls out of the growth process itself.").
sentence(s_book_08_0052, 'book', 8, 43, 'unmarked', "No selection for robustness is required at any point.").
sentence(s_book_08_0053, 'book', 8, 43, 'unmarked', "Models of this kind produce codes nearly as error-tolerant as the real one.").
sentence(s_book_08_0054, 'book', 8, 47, 'unmarked', "There are further proposals — direct chemical affinities between amino acids and their codons, or a code that developed alongside the biosynthetic pathways producing the amino acids.").
sentence(s_book_08_0055, 'book', 8, 47, 'unmarked', "These are not mutually exclusive, and the current picture probably involves more than one.").
hedged(s_book_08_0055).
sentence(s_book_08_0056, 'book', 8, 47, 'unmarked', "The question is open.").
sentence(s_book_08_0057, 'book', 8, 49, 'unmarked', "The third reading deserves the extra weight because of what it would mean.").
sentence(s_book_08_0058, 'book', 8, 49, 'unmarked', "It describes a structure that looks optimized, performs as though optimized, and was never optimized for anything — the apparent design falling out of the order in which parts arrived.").
certainty_word(s_book_08_0058, 'never').
sentence(s_book_08_0059, 'book', 8, 49, 'unmarked', "That possibility is worth holding onto, because it is the form every claim in this book is most at risk of taking.").
sentence(s_book_08_0060, 'book', 8, 51, 'unmarked', "What is not in dispute is the structure itself.").
sentence(s_book_08_0061, 'book', 8, 51, 'unmarked', "Whatever produced it, the code distinguishes between positions where information can be lost safely and positions where it cannot, and it concentrates its tolerance in the former.").
sentence(s_book_08_0062, 'book', 8, 53, 'unmarked', "There is a resemblance here to error-correcting codes in engineering, and it is worth noticing without overstating it.").
sentence(s_book_08_0063, 'book', 8, 53, 'unmarked', "An engineered code adds redundant symbols deliberately so that corruption can be detected and reversed.").
sentence(s_book_08_0064, 'book', 8, 53, 'unmarked', "The genetic code does nothing of the kind: it tolerates error by how the mapping is arranged, not by adding check data, and it cannot detect or repair anything on its own.").
sentence(s_book_08_0065, 'book', 8, 53, 'unmarked', "(Cells do have dedicated repair machinery, but that is separate from the code.").
sentence(s_book_08_0066, 'book', 8, 53, 'unmarked', "The two arrive at related behaviour by unrelated means — which is a resemblance, not a shared mechanism.").
number(s_book_08_0066, 2, 'arrive').
keywords(s_book_08_0066, ['arrive', 'behaviour', 'mechanism', 'related', 'resemblance', 'shared', 'unrelated']).
sentence(s_book_08_0067, 'book', 8, 57, 'unmarked', "One further point about DNA specifically.").
sentence(s_book_08_0068, 'book', 8, 57, 'unmarked', "The molecule stores information in sequence, but it also has a shape, and the shape carries consequences.").
sentence(s_book_08_0069, 'book', 8, 57, 'unmarked', "Strands bend and loop so that regions far apart in sequence can come into physical contact, and in many organisms this is part of how genes are switched on and off.").
sentence(s_book_08_0070, 'book', 8, 57, 'unmarked', "The same sequence can therefore be read differently depending on how the molecule is folded and what is bound to it.").
sentence(s_book_08_0071, 'book', 8, 59, 'unmarked', "Information in biological systems is not held in one place or in one form.").
sentence(s_book_08_0072, 'book', 8, 59, 'unmarked', "It is distributed across sequence, structure, chemical modification, and the state of the cell doing the reading.").
sentence(s_book_08_0073, 'book', 8, 63, 'unmarked', "The arrival of a system capable of reliable heredity, variation, and reproduction was a major transition.").
sentence(s_book_08_0074, 'book', 8, 63, 'unmarked', "Before it, chemical systems could persist.").
sentence(s_book_08_0075, 'book', 8, 63, 'unmarked', "After it, they could accumulate.").
sentence(s_book_08_0076, 'book', 8, 63, 'unmarked', "A pattern that is copied with occasional error, in a population where some copies do better than others, will change across generations without anything directing the change.").
sentence(s_book_08_0077, 'book', 8, 65, 'unmarked', "The exact route by which this transition occurred remains an open scientific question — and it is the largest remaining gap in the account this book is assembling.").
sentence(s_book_08_0078, 'book', 8, 65, 'unmarked', "Chapters 3 through 5 describe chemistry that organizes, localizes, and sustains itself without any of it being inherited.").
xref(s_book_08_0078, 3).
xref(s_book_08_0078, 5).
sentence(s_book_08_0079, 'book', 8, 65, 'unmarked', "Everything after this chapter assumes heredity already exists — as, strictly, do chapters 6 and 7, which take up the theme of boundaries ahead of their place in the sequence.").
xref(s_book_08_0079, 6).
xref(s_book_08_0079, 7).
sentence(s_book_08_0080, 'book', 8, 65, 'unmarked', "How the first reliably copied pattern arose is the step in between, and it is not yet known.").
sentence(s_book_08_0081, 'book', 8, 65, 'unmarked', "The nearest approach so far is the 45-nucleotide RNA described in chapter 4, which can make both itself and its complement, slowly, inaccurately, and in separate reactions.").
number(s_book_08_0081, 45, 'nucleotide').
keywords(s_book_08_0081, ['approach', 'chapter', 'complement', 'described', 'inaccurately', 'itself', 'nearest', 'nucleotide', 'reaction', 'separate', 'slowly']).
xref(s_book_08_0081, 4).
sentence(s_book_08_0082, 'book', 8, 65, 'unmarked', "Its discoverers still write that how the capacity for heredity first emerged is unknown.").
hedged(s_book_08_0082).
chapter('book', 9, "09-biological-evolution.md", "9. Biological evolution and increasing organization").
sentence(s_book_09_0001, 'book', 9, 3, 'unmarked', "Once systems capable of heredity and reproduction existed, biological evolution could produce increasingly diverse forms of organization.").
sentence(s_book_09_0002, 'book', 9, 5, 'unmarked', "The components are few.").
sentence(s_book_09_0003, 'book', 9, 5, 'unmarked', "Traits are inherited.").
sentence(s_book_09_0004, 'book', 9, 5, 'unmarked', "Copying introduces variation through mutation.").
sentence(s_book_09_0005, 'book', 9, 5, 'unmarked', "Some variants reproduce or survive better than others, so their frequency rises — natural selection.").
sentence(s_book_09_0006, 'book', 9, 5, 'unmarked', "Chance alone shifts frequencies too, especially in small populations — genetic drift — and populations exchange material through gene flow.").
sentence(s_book_09_0007, 'book', 9, 5, 'unmarked', "Ecological relationships change, which changes what counts as advantageous.").
sentence(s_book_09_0008, 'book', 9, 7, 'unmarked', "Nothing in that list specifies an outcome.").
sentence(s_book_09_0009, 'book', 9, 7, 'unmarked', "Evolution has no predetermined destination and no tendency towards complexity.").
sentence(s_book_09_0010, 'book', 9, 7, 'unmarked', "Simpler organisms are frequently the more successful ones by any measure that counts individuals or biomass, and complex structures are lost whenever maintaining them costs more than their function is worth.").
sentence(s_book_09_0011, 'book', 9, 7, 'unmarked', "Whales lost their hind limbs.").
sentence(s_book_09_0012, 'book', 9, 7, 'unmarked', "Cave fish lose their eyes.").
sentence(s_book_09_0013, 'book', 9, 7, 'unmarked', "Parasites routinely shed organ systems their hosts can supply instead.").
sentence(s_book_09_0014, 'book', 9, 9, 'unmarked', "What evolution does leave is a record — not only of what worked, but of the route taken to get there.").
sentence(s_book_09_0015, 'book', 9, 9, 'unmarked', "Two kinds of evidence are worth examining closely, because they point in opposite directions and are both informative.").
number(s_book_09_0015, 2, 'kind').
keywords(s_book_09_0015, ['because', 'closely', 'direction', 'evidence', 'examining', 'informative', 'opposite', 'point', 'worth']).
sentence(s_book_09_0016, 'book', 9, 13, 'unmarked', "Unrelated lineages facing similar problems frequently arrive at similar answers.").
sentence(s_book_09_0017, 'book', 9, 15, 'unmarked', "Eyes are the standard illustration.").
sentence(s_book_09_0018, 'book', 9, 15, 'unmarked', "Light-sensitive structures have arisen independently many times across the animal kingdom — a frequently cited survey put the number somewhere above 40, though counts vary with how strictly \"independent\" and \"eye\" are defined.").
number(s_book_09_0018, 40, 'though').
keywords(s_book_09_0018, ['above', 'across', 'animal', 'arisen', 'cited', 'count', 'defined', 'frequently', 'independent', 'independently', 'kingdom', 'light-sensitive', 'number', 'somewhere', 'strictly', 'structure', 'survey', 'though']).
sentence(s_book_09_0019, 'book', 9, 15, 'unmarked', "Vertebrates built a camera eye with a single lens.").
sentence(s_book_09_0020, 'book', 9, 15, 'unmarked', "Insects built a compound eye from many small units.").
sentence(s_book_09_0021, 'book', 9, 15, 'unmarked', "Cephalopods built a camera eye too, separately.").
sentence(s_book_09_0022, 'book', 9, 17, 'unmarked', "Oxygen transport tells a similar story.").
sentence(s_book_09_0023, 'book', 9, 17, 'unmarked', "Vertebrates use haemoglobin, which carries oxygen on an iron atom held in a porphyrin ring made of mostly carbon.").
sentence(s_book_09_0024, 'book', 9, 17, 'unmarked', "Many molluscs and arthropods use haemocyanin, which uses copper instead, held directly by the protein rather than in a ring, and is not related to haemoglobin by descent.").
sentence(s_book_09_0025, 'book', 9, 17, 'unmarked', "Some marine invertebrates use a third protein again.").
sentence(s_book_09_0026, 'book', 9, 17, 'unmarked', "Different molecules, independently arrived at, doing the same reversible job.").
sentence(s_book_09_0027, 'book', 9, 19, 'unmarked', "Powered flight evolved in insects, in pterosaurs, in birds, and in bats — four times, from four different starting anatomies.").
number(s_book_09_0027, 4, 'four').
number(s_book_09_0027, 4, 'different').
keywords(s_book_09_0027, ['anatomy', 'different', 'evolved', 'flight', 'insect', 'powered', 'pterosaur', 'starting']).
sentence(s_book_09_0028, 'book', 9, 21, 'unmarked', "This is not coincidence, and it is not a tendency towards any particular form.").
sentence(s_book_09_0029, 'book', 9, 21, 'unmarked', "The physics of focusing light, of binding oxygen reversibly, and of generating lift are the same everywhere, and they permit only a limited range of workable solutions.").
sentence(s_book_09_0030, 'book', 9, 21, 'unmarked', "Evolution does not invent from nothing.").
sentence(s_book_09_0031, 'book', 9, 21, 'unmarked', "It finds its way into the set of configurations that physics and chemistry leave open, and when the same problem recurs the same region of that set keeps getting found.").
sentence(s_book_09_0032, 'book', 9, 23, 'unmarked', "There is a complication worth stating, because it is more interesting than the clean version.").
sentence(s_book_09_0033, 'book', 9, 23, 'unmarked', "The optical structures of eyes did arise separately, but the genetic machinery that initiates eye development is deeply shared — a regulatory gene family common to animals with eyes of all kinds is involved in building most of them.").
sentence(s_book_09_0034, 'book', 9, 23, 'unmarked', "So \"independent\" describes the engineering, not the entire toolkit.").
sentence(s_book_09_0035, 'book', 9, 23, 'unmarked', "Lineages reached similar destinations partly because they set out carrying similar equipment.").
sentence(s_book_09_0036, 'book', 9, 27, 'unmarked', "Convergence shows what the constraints allow.").
sentence(s_book_09_0037, 'book', 9, 27, 'unmarked', "The second kind of evidence shows what history imposes.").
sentence(s_book_09_0038, 'book', 9, 29, 'unmarked', "Consider the recurrent laryngeal nerve.").
sentence(s_book_09_0039, 'book', 9, 29, 'unmarked', "It runs from the brain to the larynx, in the throat.").
sentence(s_book_09_0040, 'book', 9, 29, 'unmarked', "It does not go there directly.").
sentence(s_book_09_0041, 'book', 9, 29, 'unmarked', "It branches off the vagus nerve, descends into the chest, loops beneath a major artery near the heart — the aortic arch on the left side, the subclavian artery on the right — and climbs back up to a destination a few centimetres from where it started.").
sentence(s_book_09_0042, 'book', 9, 29, 'unmarked', "In a giraffe the same loop runs the length of the neck and back, about four and a half metres of nerve to span a gap of inches.").
number(s_book_09_0042, 4.5, 'metre').
keywords(s_book_09_0042, ['giraffe', 'inche', 'length', 'metre', 'nerve']).
sentence(s_book_09_0043, 'book', 9, 31, 'unmarked', "The explanation is developmental and historical.").
sentence(s_book_09_0044, 'book', 9, 31, 'unmarked', "In fish, the equivalent nerve runs a short, direct course to its corresponding gill arch.").
sentence(s_book_09_0045, 'book', 9, 31, 'unmarked', "As the ancestors of land vertebrates evolved, the heart and great vessels shifted backwards into the chest, and the nerve, hooked around a vessel, was carried along.").
sentence(s_book_09_0046, 'book', 9, 31, 'unmarked', "Each incremental shift was small enough to tolerate.").
sentence(s_book_09_0047, 'book', 9, 31, 'unmarked', "No step could undo the arrangement without disconnecting the nerve, and so the detour was retained and extended every time a neck got longer.").
sentence(s_book_09_0048, 'book', 9, 31, 'unmarked', "The direct route was never restored: evolution worked around the rest of the body's layout, and the long way round cost too little to be selected away.").
certainty_word(s_book_09_0048, 'never').
sentence(s_book_09_0049, 'book', 9, 33, 'unmarked', "If easier, imagine an old city with old tiny roads.").
sentence(s_book_09_0050, 'book', 9, 33, 'unmarked', "The tiny roads still lead where a driver needs to go, but the city grew around them, within limits set by the area's geography, and a drive across town can mean a weird \"detour\" a few blocks longer than walking directly there, free of one-way streets forcing odd turns.").
sentence(s_book_09_0051, 'book', 9, 33, 'unmarked', "Old cities optimized around different conditions, and their streets are like the detour this nerve takes.").
sentence(s_book_09_0052, 'book', 9, 35, 'unmarked', "The mammalian middle ear is the same kind of story told forward.").
sentence(s_book_09_0053, 'book', 9, 35, 'unmarked', "Two of the three small bones that transmit sound from the eardrum to the inner ear are modified from bones that formed the jaw joint in earlier vertebrates — the reptilian quadrate and articular became the mammalian incus and malleus.").
number(s_book_09_0053, 2, 'three').
number(s_book_09_0053, 3, 'small').
keywords(s_book_09_0053, ['articular', 'became', 'eardrum', 'earlier', 'formed', 'inner', 'joint', 'malleu', 'mammalian', 'modified', 'quadrate', 'reptilian', 'small', 'sound', 'three', 'transmit', 'vertebrate']).
sentence(s_book_09_0054, 'book', 9, 37, 'unmarked', "This transition is unusually well documented, and it has an intermediate that settles the question of how such a change is even possible.").
sentence(s_book_09_0055, 'book', 9, 37, 'unmarked', "Some early mammal relatives had two working jaw joints at once: the older one, between quadrate and articular, and a new one between different bones alongside it.").
number(s_book_09_0055, 2, 'working').
keywords(s_book_09_0055, ['alongside', 'articular', 'different', 'early', 'joint', 'mammal', 'older', 'quadrate', 'relative', 'working']).
sentence(s_book_09_0056, 'book', 9, 37, 'unmarked', "With the load carried by the second joint, the first was free to be repurposed without the animal ever losing the ability to chew.").
sentence(s_book_09_0057, 'book', 9, 37, 'unmarked', "There was no moment at which a jaw had to stop working in order for an ear to start.").
sentence(s_book_09_0058, 'book', 9, 39, 'unmarked', "The homology was proposed from embryology before the fossils were found, and the fossils then confirmed it.").
hedged(s_book_09_0058).
sentence(s_book_09_0059, 'book', 9, 41, 'unmarked', "Human development carries similar marks.").
sentence(s_book_09_0060, 'book', 9, 41, 'unmarked', "Early vertebrate embryos — fish, birds, and mammals alike — develop a series of pharyngeal arches, ridges of tissue in the neck region.").
sentence(s_book_09_0061, 'book', 9, 41, 'unmarked', "In fish these contribute to the supporting structures of gills.").
sentence(s_book_09_0062, 'book', 9, 41, 'unmarked', "In mammals the same arches give rise to the jaw, parts of the middle ear, and structures of the larynx.").
sentence(s_book_09_0063, 'book', 9, 41, 'unmarked', "The arches are homologous; what they become is not.").
sentence(s_book_09_0064, 'book', 9, 41, 'unmarked', "(Human embryos do not have gills, and the older claim that an embryo replays its ancestry is not correct.").
sentence(s_book_09_0065, 'book', 9, 41, 'unmarked', "What is shared is the developmental starting material, not the sequence of adult forms.)").
sentence(s_book_09_0066, 'book', 9, 43, 'unmarked', "Some structures persist after their original role has diminished.").
sentence(s_book_09_0067, 'book', 9, 43, 'unmarked', "Third molars — wisdom teeth — frequently lack room in a jaw that has become shorter than the one they evolved in.").
sentence(s_book_09_0068, 'book', 9, 43, 'unmarked', "The coccyx is a set of fused vertebrae left from a tail; it no longer functions as one, though it is not inert, since pelvic floor muscles and ligaments attach to it.").
sentence(s_book_09_0069, 'book', 9, 45, 'unmarked', "The appendix is worth a paragraph of its own, because it used to be the standard example in lists like this one and it should no longer be.").
sentence(s_book_09_0070, 'book', 9, 45, 'unmarked', "Evidence has accumulated that it has immune functions and may serve as a reservoir of gut microorganisms that helps repopulate the intestine after disruption.").
hedged(s_book_09_0070).
sentence(s_book_09_0071, 'book', 9, 45, 'unmarked', "It has also evolved independently many times in mammals, which is difficult to square with its being useless.").
sentence(s_book_09_0072, 'book', 9, 45, 'unmarked', "The lesson is not that the category of retained structures is empty.").
sentence(s_book_09_0073, 'book', 9, 45, 'unmarked', "It is that \"of unknown function\" and \"of no function\" are different claims, and that the first has repeatedly been mistaken for the second.").
hedged(s_book_09_0073).
sentence(s_book_09_0074, 'book', 9, 47, 'unmarked', "Taken together these are the signature of a process that can only modify what is already present.").
sentence(s_book_09_0075, 'book', 9, 47, 'unmarked', "It cannot set a structure aside and begin again, because every intermediate form has to be a working organism.").
sentence(s_book_09_0076, 'book', 9, 47, 'unmarked', "It therefore reaches its solutions by the route that was available rather than the route that would be shortest, and the route stays visible in the result.").
sentence(s_book_09_0077, 'book', 9, 53, 'unmarked', "One more feature of biological history complicates the familiar branching picture.").
sentence(s_book_09_0078, 'book', 9, 55, 'unmarked', "Genetic material does not travel only from parent to offspring.").
sentence(s_book_09_0079, 'book', 9, 55, 'unmarked', "It also moves sideways, between organisms that are not related, by several mechanisms — including viruses, which carry sequence from one host and deposit it in another.").
sentence(s_book_09_0080, 'book', 9, 55, 'unmarked', "Among bacteria and archaea this horizontal gene transfer is common enough that a lineage's history is better described as a network than a branch.").
sentence(s_book_09_0081, 'book', 9, 57, 'unmarked', "Viruses are consequently poorly described as parasites alone.").
sentence(s_book_09_0082, 'book', 9, 57, 'unmarked', "They are also a transport system, and material they have moved has repeatedly been put to use.").
sentence(s_book_09_0083, 'book', 9, 57, 'unmarked', "The clearest mammalian example is syncytin, a gene derived from a retroviral envelope protein.").
sentence(s_book_09_0084, 'book', 9, 57, 'unmarked', "Its original function was helping a virus fuse with a host cell membrane.").
sentence(s_book_09_0085, 'book', 9, 57, 'unmarked', "In placental mammals it fuses cells to each other, forming a layer essential to the placenta — mice engineered without it fail to form a working placenta, and the embryos do not survive.").
sentence(s_book_09_0086, 'book', 9, 59, 'unmarked', "The striking part is how often this happened.").
sentence(s_book_09_0087, 'book', 9, 59, 'unmarked', "Syncytins have been identified in primates, in several separate rodent groups, in carnivores, in ruminants, and in marsupials.").
sentence(s_book_09_0088, 'book', 9, 59, 'unmarked', "They are not variants of one captured gene inherited from a common ancestor.").
sentence(s_book_09_0089, 'book', 9, 59, 'unmarked', "They come from unrelated retroviruses, captured independently at different times in different lineages, and co-opted for the same job each time.").
sentence(s_book_09_0090, 'book', 9, 59, 'unmarked', "Placental mammals did not acquire this capability once.").
sentence(s_book_09_0091, 'book', 9, 59, 'unmarked', "They acquired it repeatedly, from whatever virus was available, which is convergent evolution running on borrowed parts.").
sentence(s_book_09_0092, 'book', 9, 61, 'unmarked', "A substantial fraction of the human genome consists of sequence of viral origin, most of it inert, some of it in use.").
sentence(s_book_09_0093, 'book', 9, 63, 'unmarked', "Archaea matter to this picture too.").
sentence(s_book_09_0094, 'book', 9, 63, 'unmarked', "They occupy conditions — extremes of temperature, salinity, pH — where other cells cannot persist, and their biochemistry differs from that of bacteria in fundamental ways including the chemistry of their membranes.").
sentence(s_book_09_0095, 'book', 9, 63, 'unmarked', "They are not a marginal variation on bacteria.").
sentence(s_book_09_0096, 'book', 9, 63, 'unmarked', "They are evidence that the early diversification of life explored genuinely different solutions.").
sentence(s_book_09_0097, 'book', 9, 65, 'unmarked', "All of this bears on how the base of the tree should be understood.").
sentence(s_book_09_0098, 'book', 9, 65, 'unmarked', "There is strong evidence for a last universal common ancestor, in the form of features shared by everything alive: the same genetic code, the same ribosome, the same energy currency, the same handedness of key molecules.").
sentence(s_book_09_0099, 'book', 9, 65, 'unmarked', "Reconstructions from those shared features describe something fairly specific — a small single-celled organism that would not look remarkable among modern bacteria.").
sentence(s_book_09_0100, 'book', 9, 67, 'unmarked', "Two complications sit on top of that.").
number(s_book_09_0100, 2, 'complication').
keywords(s_book_09_0100, ['complication']).
sentence(s_book_09_0101, 'book', 9, 67, 'unmarked', "\"Ancestor\" in this context means a population rather than an individual, as it does everywhere else in evolutionary biology.").
sentence(s_book_09_0102, 'book', 9, 67, 'unmarked', "And the early tree appears to have been genuinely web-like, with so much sideways transfer that the lines between branches are blurred near the base; one influential suggestion is that lineages only began behaving as distinct lineages once that exchange slowed.").
hedged(s_book_09_0102).
sentence(s_book_09_0103, 'book', 9, 67, 'unmarked', "How far down the blurring goes, and whether it reaches the root, is not settled.").
sentence(s_book_09_0104, 'book', 9, 69, 'author', "Here the author would go further: that early Earth, running an enormous number of parallel chemical experiments across many environments, is more likely to have produced self-sustaining systems in several places than in exactly one, and that what appears in retrospect as a single origin may be the merge point of a network that already had several.").
hedged(s_book_09_0104).
sentence(s_book_09_0105, 'book', 9, 69, 'author', "This is a minority position.").
sentence(s_book_09_0106, 'book', 9, 69, 'author', "The universal features listed above are real and do constrain how much independent origination the evidence will bear.").
sentence(s_book_09_0107, 'book', 9, 69, 'author', "It is offered as the author's reading, not as the current scientific consensus.").
sentence(s_book_09_0108, 'book', 9, 73, 'unmarked', "Against a history this contingent, it is still true that biological organization has repeatedly found new levels.").
sentence(s_book_09_0109, 'book', 9, 75, 'unmarked', "Multicellularity arose independently in several lineages.").
sentence(s_book_09_0110, 'book', 9, 75, 'unmarked', "Cells specialized, and specialization required coordination: signalling, regulation, shared developmental programmes, and mechanisms for resolving conflicts between what suits a cell and what suits the organism containing it.").
sentence(s_book_09_0111, 'book', 9, 75, 'unmarked', "Tissues, organs, nervous systems, and complex social behaviour followed in various lineages at various times.").
sentence(s_book_09_0112, 'book', 9, 77, 'unmarked', "Each of these is the pattern from chapter 6 appearing again — containment, interaction, specialization, interdependence, coordination — now operating on cells rather than molecules, and over evolutionary rather than chemical timescales.").
xref(s_book_09_0112, 6).
sentence(s_book_09_0113, 'book', 9, 79, 'unmarked', "The capability of the resulting system depends less on what its individual components can do than on how they are related.").
sentence(s_book_09_0114, 'book', 9, 79, 'unmarked', "That is the thread the later chapters follow, as it runs through nervous systems, language, and culture.").
chapter('book', 10, "10-spirals-and-geometry.md", "10. Spirals, helices, and recurring geometry").
sentence(s_book_10_0001, 'book', 10, 3, 'unmarked', "Spirals and helices turn up everywhere once noticed.").
sentence(s_book_10_0002, 'book', 10, 5, 'unmarked', "DNA is a double helix.").
sentence(s_book_10_0003, 'book', 10, 5, 'unmarked', "Many proteins contain helical segments.").
sentence(s_book_10_0004, 'book', 10, 5, 'unmarked', "Bacteria swim by rotating a helical filament.").
sentence(s_book_10_0005, 'book', 10, 5, 'unmarked', "Nautilus shells, ram horns, and elephant tusks grow as spirals.").
sentence(s_book_10_0006, 'book', 10, 5, 'unmarked', "Sunflower heads and pine cones are built from interlocking spiral families.").
sentence(s_book_10_0007, 'book', 10, 5, 'unmarked', "Climbing plants coil.").
sentence(s_book_10_0008, 'book', 10, 5, 'unmarked', "Water drains in a vortex, hurricanes rotate, and some galaxies carry spiral arms.").
sentence(s_book_10_0009, 'book', 10, 5, 'unmarked', "A whole class of animals is classified partly by the spiral pattern their earliest cell divisions follow.").
sentence(s_book_10_0010, 'book', 10, 5, 'unmarked', "And the same shapes are in the garage: a garden hose coiled for the winter, a rope, the line on a fishing reel — ordinary objects that, as a later section shows, are solving the problem a chromosome has.").
sentence(s_book_10_0011, 'book', 10, 7, 'unmarked', "The usual response to a list like that is either to treat it as a coincidence or to treat it as a sign of something deep.").
sentence(s_book_10_0012, 'book', 10, 7, 'unmarked', "Neither is right, and the reason why is more interesting than either.").
sentence(s_book_10_0013, 'book', 10, 11, 'unmarked', "A spiral is not one thing with one cause.").
sentence(s_book_10_0014, 'book', 10, 11, 'unmarked', "It is the output of several unrelated processes, each of which arrives there for its own reasons.").
sentence(s_book_10_0015, 'book', 10, 11, 'unmarked', "The recurrence is real; the explanation is plural.").
sentence(s_book_10_0016, 'book', 10, 13, 'unmarked', "Growth proportional to size.").
sentence(s_book_10_0017, 'book', 10, 13, 'unmarked', "A structure that adds material at its edge, with each increment scaled to the current size and set at a constant angle, cannot grow as anything but a logarithmic spiral.").
sentence(s_book_10_0018, 'book', 10, 13, 'unmarked', "A nautilus adds shell at the opening; the new chamber is larger than the last by a fixed ratio; the shape follows by necessity.").
sentence(s_book_10_0019, 'book', 10, 13, 'unmarked', "Snails grow in a similar manner.").
sentence(s_book_10_0020, 'book', 10, 13, 'unmarked', "The animal is not executing a spiral.").
sentence(s_book_10_0021, 'book', 10, 13, 'unmarked', "It is adding to its edge at a constant proportional rate, and a spiral is what that looks like from outside.").
sentence(s_book_10_0022, 'book', 10, 13, 'unmarked', "D'Arcy Wentworth Thompson worked this out in detail in 1917, and it remains the clearest demonstration in the subject: a growth rule produces a form without the form being specified anywhere.").
year(s_book_10_0022, 1917).
keywords(s_book_10_0022, ['anywhere', 'clearest', 'demonstration', 'detail', 'growth', 'produce', 'remain', 'specified', 'subject', 'thompson', 'wentworth', 'worked']).
cites(s_book_10_0022, 'Thompson', 1917).
sentence(s_book_10_0023, 'book', 10, 15, 'unmarked', "Rotation combined with advance.").
sentence(s_book_10_0024, 'book', 10, 15, 'unmarked', "Anything that turns while moving forward traces a helix.").
sentence(s_book_10_0025, 'book', 10, 15, 'unmarked', "DNA's double helix comes from stacking flat base pairs with a slight consistent twist.").
sentence(s_book_10_0026, 'book', 10, 15, 'unmarked', "A bacterial flagellum is a helical filament driven by a rotary motor.").
sentence(s_book_10_0027, 'book', 10, 15, 'unmarked', "A tendril coils because its two sides change length by different amounts.").
number(s_book_10_0027, 2, 'side').
keywords(s_book_10_0027, ['amount', 'because', 'change', 'different', 'length', 'tendril']).
sentence(s_book_10_0028, 'book', 10, 15, 'unmarked', "Same shape, three mechanisms with nothing in common.").
number(s_book_10_0028, 3, 'mechanism').
keywords(s_book_10_0028, ['common', 'mechanism', 'nothing', 'shape', 'three']).
sentence(s_book_10_0029, 'book', 10, 17, 'unmarked', "Sequential packing under constraint.").
sentence(s_book_10_0030, 'book', 10, 17, 'unmarked', "This is the one that looks most like design and is least like it.").
sentence(s_book_10_0031, 'book', 10, 17, 'unmarked', "A sunflower head produces new structures one at a time at its growing centre, and each appears in the largest gap available.").
hedged(s_book_10_0031).
sentence(s_book_10_0032, 'book', 10, 17, 'unmarked', "Repeat that rule and the angle between successive units converges on about 137.5 degrees, which generates the interlocking spiral families and the Fibonacci counts that go with them.").
number(s_book_10_0032, 137.5, 'degree').
keywords(s_book_10_0032, ['angle', 'converge', 'count', 'degree', 'family', 'fibonacci', 'generate', 'interlocking', 'repeat', 'spiral', 'successive']).
sentence(s_book_10_0033, 'book', 10, 17, 'unmarked', "The decisive evidence is that the pattern is not biological at all: Douady and Couder produced the same spirals in 1992 using drops of magnetized fluid repelling each other on a dish.").
year(s_book_10_0033, 1992).
keywords(s_book_10_0033, ['biological', 'couder', 'decisive', 'douady', 'evidence', 'fluid', 'magnetized', 'pattern', 'produced', 'repelling', 'spiral', 'using']).
cites(s_book_10_0033, 'Douady', 1992).
cites(s_book_10_0033, 'Couder', 1992).
sentence(s_book_10_0034, 'book', 10, 17, 'unmarked', "No genes, no organism, same geometry.").
sentence(s_book_10_0035, 'book', 10, 17, 'unmarked', "The pattern comes from the packing problem, not from the thing solving it.").
sentence(s_book_10_0036, 'book', 10, 19, 'unmarked', "Rotation with inward or outward flow.").
sentence(s_book_10_0037, 'book', 10, 19, 'unmarked', "Material converging while rotating conserves angular momentum and spins faster as it draws in.").
sentence(s_book_10_0038, 'book', 10, 19, 'unmarked', "Whirlpools, hurricanes, and accretion around a massive body all follow.").
sentence(s_book_10_0039, 'book', 10, 19, 'unmarked', "(Water leaving a household drain is not an instance of this at planetary scale — the direction is set by the basin's shape and whatever motion the water already had, not by the Earth's rotation.)").
sentence(s_book_10_0040, 'book', 10, 21, 'unmarked', "A wave curling around a free end.").
sentence(s_book_10_0041, 'book', 10, 21, 'unmarked', "The least familiar of the five, and the one that makes a turning spiral with no material rotation at all.").
number(s_book_10_0041, 5, 'one').
keywords(s_book_10_0041, ['familiar', 'material', 'rotation', 'spiral', 'turning']).
sentence(s_book_10_0042, 'book', 10, 21, 'unmarked', "In a medium where each point can be triggered by its neighbours and then needs time to recover before it can be triggered again, a travelling wave front that is broken — with a loose end rather than a closed ring — will pivot around that end.").
sentence(s_book_10_0043, 'book', 10, 21, 'unmarked', "The tip turns fastest because it has the least recovered tissue ahead of it, and the result is a rotating spiral wave that can persist for hours.").
sentence(s_book_10_0044, 'book', 10, 21, 'unmarked', "Nothing is moving in a spiral; the pattern is a sequence of excitations passing through a stationary medium.").
sentence(s_book_10_0045, 'book', 10, 21, 'unmarked', "The Belousov–Zhabotinsky reaction in chapter 4 produces exactly this in a dish, and the same mechanism generates certain dangerous cardiac arrhythmias, where a wave of electrical excitation circulates in heart tissue instead of sweeping across it once.").
xref(s_book_10_0045, 4).
sentence(s_book_10_0046, 'book', 10, 23, 'unmarked', "Five conditions, five mechanisms, one family of shapes.").
number(s_book_10_0046, 5, 'condition').
number(s_book_10_0046, 5, 'mechanism').
keywords(s_book_10_0046, ['condition', 'family', 'mechanism', 'shape']).
sentence(s_book_10_0047, 'book', 10, 27, 'unmarked', "The honest reading is this: a spiral is what extension looks like when something must keep a fixed relationship to where it has already been.").
sentence(s_book_10_0048, 'book', 10, 27, 'unmarked', "Spider webs and spiral staircases show it too.").
sentence(s_book_10_0049, 'book', 10, 29, 'unmarked', "That constraint is the common factor, and it is a real one.").
sentence(s_book_10_0050, 'book', 10, 29, 'unmarked', "A structure that grows only at its edge cannot revisit what it has already built.").
sentence(s_book_10_0051, 'book', 10, 29, 'unmarked', "A filament that turns while advancing cannot occupy the space it just left.").
sentence(s_book_10_0052, 'book', 10, 29, 'unmarked', "A head packing new units cannot displace the old ones.").
sentence(s_book_10_0053, 'book', 10, 29, 'unmarked', "In each case the system must extend without discarding its own history, and the set of shapes that permits is small.").
sentence(s_book_10_0054, 'book', 10, 29, 'unmarked', "The spiral is less a thing nature favours than a thing geometry leaves available.").
sentence(s_book_10_0055, 'book', 10, 31, 'unmarked', "Stated that way the claim is strong, and it is also the kind of claim that can be wrong.").
sentence(s_book_10_0056, 'book', 10, 31, 'unmarked', "It makes a prediction: systems that are free to rearrange themselves wholesale, or that have settled into a stable configuration, should not show this geometry.").
sentence(s_book_10_0057, 'book', 10, 31, 'unmarked', "Broadly they do not.").
sentence(s_book_10_0058, 'book', 10, 31, 'unmarked', "A mountain is a load-bearing compromise and is blocky or conical.").
sentence(s_book_10_0059, 'book', 10, 31, 'unmarked', "A planet large enough to pull itself into equilibrium is a sphere.").
sentence(s_book_10_0060, 'book', 10, 31, 'unmarked', "A crystal repeats a fixed cell.").
sentence(s_book_10_0061, 'book', 10, 31, 'unmarked', "These are shapes of having arrived rather than shapes of still going.").
sentence(s_book_10_0062, 'book', 10, 33, 'unmarked', "Two cautions keep this from running away.").
number(s_book_10_0062, 2, 'caution').
keywords(s_book_10_0062, ['caution', 'running']).
sentence(s_book_10_0063, 'book', 10, 35, 'unmarked', "The first is that similar form does not imply shared mechanism.").
sentence(s_book_10_0064, 'book', 10, 35, 'unmarked', "This is the point the whole book keeps returning to, and this chapter is where the temptation to forget it is strongest.").
sentence(s_book_10_0065, 'book', 10, 35, 'unmarked', "A nautilus shell and a spiral galaxy look alike in photographs and have nothing whatever in common underneath.").
sentence(s_book_10_0066, 'book', 10, 35, 'unmarked', "Galaxy arms are not material structures that wind up over time; they are better understood as waves of compression passing through the disc, with stars moving in and out of them.").
sentence(s_book_10_0067, 'book', 10, 35, 'unmarked', "Putting those two images side by side invites an inference that the physics does not support.").
number(s_book_10_0067, 2, 'image').
keywords(s_book_10_0067, ['image', 'inference', 'invite', 'physic', 'putting', 'support']).
sentence(s_book_10_0068, 'book', 10, 37, 'unmarked', "The second is that \"spiral\" is doing loose work across the list.").
sentence(s_book_10_0069, 'book', 10, 37, 'unmarked', "A logarithmic spiral, a helix, a phyllotactic lattice, and a vortex are distinct objects.").
sentence(s_book_10_0070, 'book', 10, 37, 'unmarked', "Grouping them under one word is a convenience, and conveniences of that kind are where arguments go wrong.").
sentence(s_book_10_0071, 'book', 10, 42, 'unmarked', "The constraint behind every spiral in this chapter — extension that cannot revisit what it has already laid down — has a working counterpart in how long, thin things are stored.").
sentence(s_book_10_0072, 'book', 10, 42, 'unmarked', "A rope, a cable, a fishing line, a garden hose, and a chromosome share a problem.").
sentence(s_book_10_0073, 'book', 10, 42, 'unmarked', "Each is long in one dimension, has to be kept in a small space without tangling, and has to come back out in order.").
sentence(s_book_10_0074, 'book', 10, 42, 'unmarked', "The answer, every time, is to coil it or wrap around something continuously.").
sentence(s_book_10_0075, 'book', 10, 44, 'unmarked', "Coiling has a cost that anyone who has wound a garden hose by hand has met.").
sentence(s_book_10_0076, 'book', 10, 44, 'unmarked', "A strand coiled in loops laid the same way each time picks up a full twist per loop, and when it is pulled straight again the twist has to go somewhere, which is why a hand-coiled hose kinks as it comes off the pile.").
sentence(s_book_10_0077, 'book', 10, 44, 'unmarked', "The accounting is exact.").
sentence(s_book_10_0078, 'book', 10, 44, 'unmarked', "For a strand whose ends cannot turn freely, a quantity called the linking number stays fixed, and it is the sum of two others: twist, how far the strand turns about its own axis, and writhe, how far that axis coils through space.").
number(s_book_10_0078, 2, 'other').
keywords(s_book_10_0078, ['called', 'cannot', 'fixed', 'freely', 'linking', 'number', 'quantity', 'space', 'strand', 'twist', 'writhe']).
sentence(s_book_10_0079, 'book', 10, 44, 'unmarked', "Coil the strand and writhe goes up, so twist must come down to compensate, and the reverse when it is uncoiled.").
sentence(s_book_10_0080, 'book', 10, 44, 'unmarked', "A reel that turns its drum lays a hose or a line down without this problem; a fixed-spool spinning reel, which wraps line around a stationary spool, twists the line with every cast and retrieve, and line twist is the familiar complaint about them.").
sentence(s_book_10_0081, 'book', 10, 44, 'unmarked', "Cable technicians coil over and under — twisting one loop, untwisting the next — so the twists cancel and the cable lies flat when it is thrown out.").
sentence(s_book_10_0082, 'book', 10, 44, 'unmarked', "Rope puts the same accounting to structural work: fibres are twisted into yarn one way, yarns into strands the other, and strands into rope the first way again, each counter-twist locking the layer beneath it.").
sentence(s_book_10_0083, 'book', 10, 44, 'unmarked', "What appears to be three-strand laid rope, about twenty-one thousand years old, was found in the cave at Lascaux.").
number(s_book_10_0083, 3, 'strand').
number(s_book_10_0083, 21000, 'year').
keywords(s_book_10_0083, ['appear', 'found', 'lascaux', 'thousand', 'three-strand', 'twenty-one']).
hedged(s_book_10_0083).
sentence(s_book_10_0084, 'book', 10, 46, 'unmarked', "DNA has every one of these problems, at a scale that makes them severe.").
sentence(s_book_10_0085, 'book', 10, 46, 'unmarked', "Circular DNA from a virus was found twisted on itself in 1965, and the writhing number was defined in 1971 in response to the questions that raised.").
year(s_book_10_0085, 1965).
year(s_book_10_0085, 1971).
keywords(s_book_10_0085, ['circular', 'defined', 'found', 'itself', 'number', 'question', 'raised', 'response', 'twisted', 'writhing']).
sentence(s_book_10_0086, 'book', 10, 46, 'unmarked', "In the cells of plants and animals the double helix is wrapped around cores of protein, 146 base pairs at a time and about thirty million times in each human cell, and the wrapped strand is folded again on itself.").
number(s_book_10_0086, 146, 'base').
number(s_book_10_0086, 3e+07, 'none').
keywords(s_book_10_0086, ['again', 'animal', 'double', 'folded', 'helix', 'human', 'itself', 'million', 'plant', 'protein', 'strand', 'thirty', 'wrapped']).
sentence(s_book_10_0087, 'book', 10, 46, 'unmarked', "And it is stored to be read in order.").
sentence(s_book_10_0088, 'book', 10, 46, 'unmarked', "Reading means opening the helix, and a machine moving along a twisted strand piles extra twist up ahead of it and leaves a deficit behind — the spinning reel's problem exactly.").
sentence(s_book_10_0089, 'book', 10, 46, 'unmarked', "Cells deal with it using enzymes that cut the DNA, let it turn or pass through itself, and join it again: topoisomerases, which do for a chromosome what a swivel does for a fishing line or an anchor chain.").
sentence(s_book_10_0090, 'book', 10, 48, 'author', "Here the author would go further.").
sentence(s_book_10_0091, 'book', 10, 48, 'author', "Rope, cable, line, and chromosome are one kind of object: a one-dimensional sequence that has to be packed into three dimensions and later unpacked in the order it went in.").
number(s_book_10_0091, 3, 'dimension').
keywords(s_book_10_0091, ['cable', 'chromosome', 'dimension', 'later', 'object', 'one-dimensional', 'order', 'packed', 'sequence', 'three', 'unpacked']).
sentence(s_book_10_0092, 'book', 10, 48, 'author', "A coil is the shape that does both.").
sentence(s_book_10_0093, 'book', 10, 48, 'author', "It is the stored form of something meant to be paid out, and its spiral is the record of how it was laid down — this chapter's principle, extension that keeps its own history, put to practical use.").
sentence(s_book_10_0094, 'book', 10, 48, 'author', "The resemblance holds in the mathematics, which is why one piece of accounting covers a hose and a chromosome.").
sentence(s_book_10_0095, 'book', 10, 48, 'author', "Whether it is more than that is the question chapter 17 asks of every resemblance in this book.").
xref(s_book_10_0095, 17).
sentence(s_book_10_0096, 'book', 10, 53, 'unmarked', "People have been making spirals for about as long as they have been making marks that last.").
sentence(s_book_10_0097, 'book', 10, 53, 'unmarked', "The passage tomb at Newgrange in Ireland, built around 3100 BCE, carries carvings that fall into a small number of recurring families — some curved, among them circles, arcs, and spirals, and some straight-edged, among them chevrons, parallel lines, and lozenges (diamond shapes).").
year(s_book_10_0097, -3100).
keywords(s_book_10_0097, ['among', 'built', 'carry', 'carving', 'chevron', 'circle', 'curved', 'diamond', 'family', 'ireland', 'lozenge', 'newgrange', 'number', 'parallel', 'passage', 'recurring', 'shape', 'small', 'spiral', 'straight-edged']).
sentence(s_book_10_0098, 'book', 10, 53, 'unmarked', "Its best-known stones set the two kinds side by side.").
number(s_book_10_0098, 2, 'kind').
keywords(s_book_10_0098, ['best-known', 'stone']).
sentence(s_book_10_0099, 'book', 10, 53, 'unmarked', "The entrance stone carries spirals with lozenges beside them.").
sentence(s_book_10_0100, 'book', 10, 53, 'unmarked', "On the stone directly opposite, at the back of the mound, spirals occupy the upper part of one panel and a lattice of lozenges fills the space beneath.").
sentence(s_book_10_0101, 'book', 10, 53, 'unmarked', "Inside, a triple spiral is carved on the wall of the chamber that the rising sun reaches once a year, at the winter solstice.").
sentence(s_book_10_0102, 'book', 10, 53, 'unmarked', "What any of it meant to the people who carved it cannot be recovered.").
certainty_word(s_book_10_0102, 'cannot be').
sentence(s_book_10_0103, 'book', 10, 55, 'author', "Here the author would go further.").
sentence(s_book_10_0104, 'book', 10, 55, 'author', "The pairing reads as a record of the two ways a bounded space gets filled.").
number(s_book_10_0104, 2, 'way').
keywords(s_book_10_0104, ['bounded', 'filled', 'pairing', 'record', 'space']).
sentence(s_book_10_0105, 'book', 10, 55, 'author', "A spiral extends from a centre, adding at its edge and never revisiting what it has already laid down, as the growing structures earlier in this chapter do — the shape of something still going.").
certainty_word(s_book_10_0105, 'never').
sentence(s_book_10_0106, 'book', 10, 55, 'author', "A lattice of lozenges repeats one cell until the edge of the stone stops it, as a crystal does — the shape this chapter called having arrived.").
sentence(s_book_10_0107, 'book', 10, 55, 'author', "Set together on a surface with fixed edges, they are growth and tiling, the organic and the crystalline, each filling the room it is given.").
sentence(s_book_10_0108, 'book', 10, 55, 'author', "Nothing is known about whether the carvers saw it that way.").
sentence(s_book_10_0109, 'book', 10, 55, 'author', "The resemblance is in the geometry rather than in any recorded meaning, and it is offered as a reading, under the same caution as everything else in this chapter.").
sentence(s_book_10_0110, 'book', 10, 57, 'unmarked', "Spirals were carved and painted independently in many places that had no contact with Ireland or with one another.").
sentence(s_book_10_0111, 'book', 10, 57, 'unmarked', "More than 1,400 petroglyphs at Las Plazuelas in central Mexico are mainly spirals, dot figures, and carved models of buildings, and spirals are among the Nazca lines in the Peruvian desert.").
number(s_book_10_0111, 1400, 'petroglyph').
keywords(s_book_10_0111, ['among', 'building', 'carved', 'central', 'desert', 'figure', 'mainly', 'mexico', 'model', 'nazca', 'peruvian', 'petroglyph', 'plazuela', 'spiral']).
sentence(s_book_10_0112, 'book', 10, 57, 'unmarked', "The Māori koru is a spiral modelled on the unfurling frond of a fern — a growth spiral copied from a growing thing.").
sentence(s_book_10_0113, 'book', 10, 57, 'unmarked', "In the Greater Antilles, Puerto Rico among them, the Taíno called the great storm juracán, the source of the word hurricane, and the Cuban scholar Fernando Ortiz argued in 1947 that Taíno images of the storm used a rotating figure, in its most abstract form a spiral: the storm drawn as the rotation it is.").
year(s_book_10_0113, 1947).
keywords(s_book_10_0113, ['abstract', 'among', 'antille', 'argued', 'called', 'cuban', 'drawn', 'fernando', 'figure', 'great', 'greater', 'hurricane', 'image', 'jurac', 'ortiz', 'puerto', 'rotating', 'rotation', 'scholar', 'source', 'spiral', 'storm']).
hedged(s_book_10_0113).
cites(s_book_10_0113, 'Ortiz', 1947).
sentence(s_book_10_0114, 'book', 10, 57, 'unmarked', "At Chaco Canyon in New Mexico, spirals pecked into a cliff on Fajada Butte are crossed by blades of sunlight, falling between leaning slabs of rock, at the solstices and equinoxes — a solar marker built around a spiral, like Newgrange.").
sentence(s_book_10_0115, 'book', 10, 57, 'unmarked', "Whether the slabs were set there or were a natural rockfall the carvers made use of is disputed; either way, the spirals appear to have been placed to be lit.").
hedged(s_book_10_0115).
sentence(s_book_10_0116, 'book', 10, 59, 'unmarked', "There are several candidate answers to why the same mark turns up in so many unconnected places.").
sentence(s_book_10_0117, 'book', 10, 59, 'unmarked', "Some spirals are copied from things that spiral, like the fern and the storm.").
sentence(s_book_10_0118, 'book', 10, 59, 'unmarked', "Some are tied to the sky.").
sentence(s_book_10_0119, 'book', 10, 59, 'unmarked', "And one proposal locates the source inside the observer.").
hedged(s_book_10_0119).
sentence(s_book_10_0120, 'book', 10, 59, 'unmarked', "Geometric hallucinations fall into four recurring families, two of which are lattices and spirals — the pair carved together at Newgrange — and mathematical models of the wiring between the eye and the visual cortex reproduce those families from the structure of the cortex itself.").
number(s_book_10_0120, 4, 'recurring').
number(s_book_10_0120, 2, 'none').
keywords(s_book_10_0120, ['carved', 'cortex', 'family', 'geometric', 'hallucination', 'itself', 'lattice', 'mathematical', 'model', 'newgrange', 'recurring', 'reproduce', 'spiral', 'structure', 'together', 'visual', 'wiring']).
sentence(s_book_10_0121, 'book', 10, 59, 'unmarked', "Archaeologists have argued that Irish passage-tomb art, and much older cave art, draws on imagery of this kind.").
hedged(s_book_10_0121).
sentence(s_book_10_0122, 'book', 10, 59, 'unmarked', "That argument is contested.").
hedged(s_book_10_0122).
sentence(s_book_10_0123, 'book', 10, 59, 'unmarked', "The answers are not exclusive, none is established for any particular stone, and a shared form says nothing about a shared meaning.").
sentence(s_book_10_0124, 'book', 10, 59, 'unmarked', "What the recurrence does show is this chapter's argument arriving from another direction: the spiral is available to anything that extends from a centre, a hand moving a tool included.").
sentence(s_book_10_0125, 'book', 10, 61, 'author', "A comment from the author, not a finding: the potter's wheel may be the plainest case of a person working with a spiral rather than drawing one.").
hedged(s_book_10_0125).
sentence(s_book_10_0126, 'book', 10, 61, 'author', "The wheel supplies the turning; the potter's hands supply the advance, drawing the clay up and out as it spins, and rotation combined with advance is this chapter's second way of making a spiral.").
sentence(s_book_10_0127, 'book', 10, 61, 'author', "The pot is the record of that path.").
sentence(s_book_10_0128, 'book', 10, 63, 'unmarked', "The most famous painted spiral has a better-documented history, and it turns the first caution above into a worked case.").
sentence(s_book_10_0129, 'book', 10, 63, 'unmarked', "Vincent van Gogh painted The Starry Night in June 1889, from the window of his room in the asylum at Saint-Rémy-de-Provence, where he had admitted himself the month before.").
year(s_book_10_0129, 1889).
keywords(s_book_10_0129, ['admitted', 'asylum', 'himself', 'month', 'my-de-provence', 'night', 'painted', 'saint-r', 'starry', 'vincent', 'window']).
sentence(s_book_10_0130, 'book', 10, 63, 'unmarked', "The village is invented, but much of the sky is not.").
sentence(s_book_10_0131, 'book', 10, 63, 'unmarked', "Venus, which he described in a letter as the morning star, was visible before dawn that spring at close to its greatest brightness, and it is the brightest point in the painting; the moon, by contrast, is shown in a phase it was not in.").
sentence(s_book_10_0132, 'book', 10, 63, 'unmarked', "The great swirl across the centre is the element nobody has been able to place.").
sentence(s_book_10_0133, 'book', 10, 63, 'unmarked', "An art historian proposed that it echoes the drawings of spiral nebulae — galaxies, as they were later understood to be — reproduced in the popular astronomy books of the day, and an astronomer studying the painting independently agreed, tracing the image to Lord Rosse's 1845 drawing of the Whirlpool galaxy, while also suggesting the mistral, the wind that dominated van Gogh's months in Provence.").
year(s_book_10_0133, 1845).
keywords(s_book_10_0133, ['agreed', 'astronomer', 'astronomy', 'dominated', 'drawing', 'echoe', 'galaxy', 'historian', 'image', 'independently', 'later', 'mistral', 'month', 'nebulae', 'painting', 'popular', 'proposed', 'provence', 'reproduced', 'rosse', 'spiral', 'studying', 'suggesting', 'tracing', 'understood', 'while', 'whirlpool']).
hedged(s_book_10_0133).
sentence(s_book_10_0134, 'book', 10, 63, 'unmarked', "Both readings are plausible.").
hedged(s_book_10_0134).
sentence(s_book_10_0135, 'book', 10, 63, 'unmarked', "Neither can be checked.").
sentence(s_book_10_0136, 'book', 10, 65, 'unmarked', "In 2024 a team of fluid dynamicists tried measuring the painting instead of interpreting it.").
year(s_book_10_0136, 2024).
keywords(s_book_10_0136, ['dynamicist', 'fluid', 'instead', 'interpreting', 'measuring', 'painting', 'tried']).
sentence(s_book_10_0137, 'book', 10, 65, 'unmarked', "Treating the brightness of the paint as a stand-in for a quantity carried by a flow, they found that its spectrum — how much variation there is at each scale, from the largest swirl to the smallest — falls off with the same slope that Andrei Kolmogorov's 1941 theory predicts for fully developed turbulence, and concluded that van Gogh must have observed real turbulent flow with unusual care.").
year(s_book_10_0137, 1941).
keywords(s_book_10_0137, ['andrei', 'brightness', 'carried', 'concluded', 'developed', 'found', 'fully', 'kolmogorov', 'largest', 'observed', 'paint', 'predict', 'quantity', 'scale', 'slope', 'smallest', 'spectrum', 'stand-in', 'swirl', 'theory', 'treating', 'turbulence', 'turbulent', 'unusual', 'variation']).
certainty_word(s_book_10_0137, 'must have').
cites(s_book_10_0137, 'Kolmogorov', 1941).
sentence(s_book_10_0138, 'book', 10, 65, 'unmarked', "An earlier study had reported a related match in the statistics of brightness across several of his late paintings.").
sentence(s_book_10_0139, 'book', 10, 67, 'unmarked', "The objections came from turbulence specialists, and they are the instructive part.").
sentence(s_book_10_0140, 'book', 10, 67, 'unmarked', "The theory being applied describes a physical quantity carried by a moving fluid; a painting has no such quantity, and nothing guarantees that its brightness behaves like one.").
sentence(s_book_10_0141, 'book', 10, 67, 'unmarked', "Then a second group ran the same analysis on a portrait by Degas of a woman seated beside a vase of flowers — no sky, no wind, nothing turbulent anywhere in it — and obtained the same slope.").
sentence(s_book_10_0142, 'book', 10, 67, 'unmarked', "A test that a vase of flowers also passes cannot be what identifies turbulence.").
certainty_word(s_book_10_0142, 'cannot be').
sentence(s_book_10_0143, 'book', 10, 69, 'unmarked', "That is the first caution in its most useful form.").
sentence(s_book_10_0144, 'book', 10, 69, 'unmarked', "This time the resemblance between a painting and a turbulent sky was not eyeballed.").
sentence(s_book_10_0145, 'book', 10, 69, 'unmarked', "It was measured, published, and still did not establish a shared mechanism, because the measurement turned out to be one that unrelated images pass as well.").
sentence(s_book_10_0146, 'book', 10, 69, 'unmarked', "The painting does not need the claim.").
sentence(s_book_10_0147, 'book', 10, 69, 'unmarked', "What van Gogh put on the canvas is a sky that looks as if it is moving, made by a hand moving paint.").
sentence(s_book_10_0148, 'book', 10, 71, 'author', "A comment from the author, not a finding: perhaps van Gogh was watching a turbulent river and was inspired by its texture, or, more literally, saw turbulence in fast-moving clouds turn the sky wispy and spiral-like.").
hedged(s_book_10_0148).
sentence(s_book_10_0149, 'book', 10, 71, 'author', "The measurement cannot settle that, so it stays a guess.").
sentence(s_book_10_0150, 'book', 10, 71, 'author', "The alternative is to accept that the spirals suit the painting, which its popularity seems to bear out.").
hedged(s_book_10_0150).
sentence(s_book_10_0151, 'book', 10, 75, 'author', "What follows is the author's reading rather than an established result.").
sentence(s_book_10_0152, 'book', 10, 77, 'author', "Take the observation seriously and it suggests a way of sorting systems.").
hedged(s_book_10_0152).
sentence(s_book_10_0153, 'book', 10, 77, 'author', "On one side, systems at or near equilibrium: settled, symmetric, finished, their shape determined by the balance of forces acting on them now.").
sentence(s_book_10_0154, 'book', 10, 77, 'author', "On the other, systems still running — growing, oscillating, circulating, recursing — whose shape records the path they took to get here as well as the forces acting on them.").
sentence(s_book_10_0155, 'book', 10, 79, 'author', "The second group is where the spirals are.").
sentence(s_book_10_0156, 'book', 10, 79, 'author', "Not because a spiral is optimal, and not because anything prefers it, but because a system that is still extending and cannot undo its own past has a restricted set of forms available, and this family is most of that set.").
sentence(s_book_10_0157, 'book', 10, 81, 'author', "This connects forward to chapter 13 more directly than it may appear.").
hedged(s_book_10_0157).
xref(s_book_10_0157, 13).
sentence(s_book_10_0158, 'book', 10, 81, 'author', "A mind modelling itself modelling never reaches a resting state; each pass takes the result of the last as its input.").
certainty_word(s_book_10_0158, 'never').
sentence(s_book_10_0159, 'book', 10, 81, 'author', "That is recursion rather than rotation, and calling it a spiral is a metaphor rather than a measurement.").
sentence(s_book_10_0160, 'book', 10, 81, 'author', "But it has the shape of the condition described above: continuation that carries its own history forward and cannot start over.").
sentence(s_book_10_0161, 'book', 10, 81, 'author', "Chapter 11 takes up the same structure in time rather than space.").
xref(s_book_10_0161, 11).
sentence(s_book_10_0162, 'book', 10, 85, 'unmarked', "A note on the limits of that reading, since the limits are instructive.").
sentence(s_book_10_0163, 'book', 10, 85, 'unmarked', "It is tempting to extend the argument to the hair whorl at the crown of the head — a visible spiral, sitting directly above the part of the brain most associated with deliberate thought.").
sentence(s_book_10_0164, 'book', 10, 85, 'unmarked', "The temptation should be refused.").
sentence(s_book_10_0165, 'book', 10, 85, 'unmarked', "Hair whorls arise from the orientation of follicles during skin development and have no relationship to the tissue underneath; the apparent significance is entirely an artefact of where the observer is standing.").
sentence(s_book_10_0166, 'book', 10, 85, 'unmarked', "The pull of that connection is strong, it is exactly the pull chapter 13 describes, and noticing it without acting on it is the only defence available.").
xref(s_book_10_0166, 13).
sentence(s_book_10_0167, 'book', 10, 89, 'unmarked', "One further place the geometry of oscillation shows up at scale, offered as a fact rather than an argument.").
sentence(s_book_10_0168, 'book', 10, 91, 'unmarked', "The gap between Earth's surface and the lower ionosphere forms a cavity, and lightning — roughly fifty strikes somewhere on the planet every second — rings it continuously.").
number(s_book_10_0168, 50, 'strike').
keywords(s_book_10_0168, ['cavity', 'continuously', 'earth', 'fifty', 'ionosphere', 'lightning', 'lower', 'planet', 'second', 'somewhere', 'strike', 'surface']).
sentence(s_book_10_0169, 'book', 10, 91, 'unmarked', "The cavity has resonant frequencies, the lowest around 7.8 Hz, and they are measurable with the right instruments anywhere on Earth.").
number(s_book_10_0169, 7.8, 'hz').
keywords(s_book_10_0169, ['anywhere', 'cavity', 'earth', 'frequency', 'instrument', 'lowest', 'measurable', 'resonant', 'right']).
sentence(s_book_10_0170, 'book', 10, 91, 'unmarked', "These are the Schumann resonances, predicted in 1952 and confirmed experimentally within the decade.").
year(s_book_10_0170, 1952).
keywords(s_book_10_0170, ['confirmed', 'decade', 'experimentally', 'predicted', 'resonance', 'schumann']).
cites(s_book_10_0170, 'Schumann', 1952).
sentence(s_book_10_0171, 'book', 10, 93, 'unmarked', "Separately, Earth's liquid core generates a magnetic field, and that field is shaped from outside by the solar wind — compressed on the sunward side, drawn into a long tail on the other, flexing continuously as solar activity rises and falls.").
sentence(s_book_10_0172, 'book', 10, 95, 'unmarked', "Neither of these is mysterious and neither is doing anything for life as far as is known.").
sentence(s_book_10_0173, 'book', 10, 95, 'unmarked', "They are included here because they are true and because they extend the chapter's subject to planetary scale: a system under continuous energy input, oscillating rather than settling, with a measurable geometry that exists only because it never stops being driven.").
certainty_word(s_book_10_0173, 'never').
sentence(s_book_10_0174, 'book', 10, 97, 'unmarked', "Nothing further is claimed for them.").
sentence(s_book_10_0175, 'book', 10, 97, 'unmarked', "Speculation about these signals interacting with biology, technology, or anything else is not supported by evidence and is not part of this account.").
heading_count('book', 10, 9, "Five ways to make a spiral", 5, 5).
chapter('book', 11, "11-time-cycles-accumulation.md", "11. Time as cycles plus accumulation").
sentence(s_book_11_0001, 'book', 11, 3, 'unmarked', "Many natural processes are cyclical.").
sentence(s_book_11_0002, 'book', 11, 5, 'unmarked', "Day and night, seasons, tides, biological rhythms, planetary orbits, and many chemical oscillations repeat over time.").
sentence(s_book_11_0003, 'book', 11, 5, 'unmarked', "But cycles rarely repeat into identical conditions.").
sentence(s_book_11_0004, 'book', 11, 5, 'unmarked', "Each one occurs in a system that has been changed by the ones before it.").
sentence(s_book_11_0005, 'book', 11, 7, 'unmarked', "A useful conceptual image is a series of circles accumulating along another axis, producing a spiral:").
sentence(s_book_11_0006, 'book', 11, 9, 'unmarked', "- The circular motion represents recurrence. - The progression along the axis represents elapsed time. - The expanding or shifting path represents accumulated change.").
sentence(s_book_11_0007, 'book', 11, 13, 'unmarked', "This is not a claim that physical time has a spiral geometry.").
sentence(s_book_11_0008, 'book', 11, 13, 'unmarked', "It is a way of holding two things at once — that a process repeats, and that repeating it changes what it repeats into.").
number(s_book_11_0008, 2, 'thing').
keywords(s_book_11_0008, ['change', 'holding', 'process', 'repeat', 'repeating', 'thing']).
sentence(s_book_11_0009, 'book', 11, 17, 'unmarked', "The combination is not abstract.").
sentence(s_book_11_0010, 'book', 11, 17, 'unmarked', "Several natural systems produce a physical record of it, which is why so much of what is known about the deep past comes from reading them.").
sentence(s_book_11_0011, 'book', 11, 19, 'unmarked', "A tree adds a growth ring each year.").
sentence(s_book_11_0012, 'book', 11, 19, 'unmarked', "The cycle is annual and the same each time; the ring is not.").
sentence(s_book_11_0013, 'book', 11, 19, 'unmarked', "Its width records that year's water, temperature, and competition, and because the rings accumulate rather than overwrite, a trunk holds an ordered sequence reaching back as far as the tree does.").
sentence(s_book_11_0014, 'book', 11, 19, 'unmarked', "Overlapping records from living trees, dead timber, and archaeological wood extend the sequence back thousands of years.").
sentence(s_book_11_0015, 'book', 11, 21, 'unmarked', "Ice does the same with snowfall.").
sentence(s_book_11_0016, 'book', 11, 21, 'unmarked', "Each year's accumulation is compressed by the next, and trapped air bubbles preserve samples of the atmosphere at the moment the snow closed over.").
sentence(s_book_11_0017, 'book', 11, 21, 'unmarked', "The longest continuous Antarctic record reaches back about 800,000 years, across eight glacial cycles, and carries a direct record of past carbon dioxide — not inferred from a proxy, but measured from the air itself.").
number(s_book_11_0017, 800000, 'year').
number(s_book_11_0017, 8, 'glacial').
keywords(s_book_11_0017, ['across', 'antarctic', 'carbon', 'carry', 'continuou', 'cycle', 'dioxide', 'direct', 'eight', 'glacial', 'inferred', 'itself', 'longest', 'measured', 'proxy', 'reache', 'record']).
sentence(s_book_11_0018, 'book', 11, 23, 'unmarked', "Lake sediments layer seasonally.").
sentence(s_book_11_0019, 'book', 11, 23, 'unmarked', "Some corals and shells band with the tides.").
sentence(s_book_11_0020, 'book', 11, 23, 'unmarked', "In each case a cycle that could in principle repeat unchanged instead leaves a residue, and the residue is what makes history legible.").
sentence(s_book_11_0021, 'book', 11, 25, 'unmarked', "The general form is worth naming.").
sentence(s_book_11_0022, 'book', 11, 25, 'unmarked', "A system whose current state depends not only on present conditions but on the path it took to reach them exhibits hysteresis.").
sentence(s_book_11_0023, 'book', 11, 25, 'unmarked', "The term comes from magnetism, where a material's response depends on what was done to it previously, and the same structure appears wherever a cycle leaves something behind.").
hedged(s_book_11_0023).
sentence(s_book_11_0024, 'book', 11, 29, 'unmarked', "Evolution is generational, and each generation starts from the population the last one produced.").
sentence(s_book_11_0025, 'book', 11, 29, 'unmarked', "Learning is repetition that alters what repetition does.").
sentence(s_book_11_0026, 'book', 11, 29, 'unmarked', "Development runs through stages that are similar across individuals and never identical, because each stage builds on the particular outcome of the one before.").
certainty_word(s_book_11_0026, 'never').
sentence(s_book_11_0027, 'book', 11, 29, 'unmarked', "Cultural transmission passes practices on, and what is passed on has been reshaped by every previous passing.").
sentence(s_book_11_0028, 'book', 11, 31, 'unmarked', "None of these is literally a spiral, and applying the word to them should be read as the convenience it is.").
sentence(s_book_11_0029, 'book', 11, 31, 'unmarked', "What they share is structural: a process that recurs, inside a system that retains the consequences of its earlier recurrences.").
sentence(s_book_11_0030, 'book', 11, 33, 'unmarked', "Chapter 10 described this in space — extension that cannot revisit its own past.").
xref(s_book_11_0030, 10).
sentence(s_book_11_0031, 'book', 11, 33, 'unmarked', "This is the same constraint operating in time.").
sentence(s_book_11_0032, 'book', 11, 33, 'unmarked', "A cycle that left nothing behind would be a closed loop, and a system made of closed loops would have no history to read.").
sentence(s_book_11_0033, 'book', 11, 37, 'unmarked', "What follows is the most speculative material in the book.").
sentence(s_book_11_0034, 'book', 11, 37, 'unmarked', "It is included because the pattern of this chapter has been proposed at cosmological scale too, and because the arguments are interesting.").
hedged(s_book_11_0034).
sentence(s_book_11_0035, 'book', 11, 37, 'unmarked', "None of it is established, and the chapter stands without it.").
sentence(s_book_11_0036, 'book', 11, 41, 'unmarked', "The question of whether the universe had a beginning or a previous state has several live answers, and at least three of them take a cyclic shape.").
number(s_book_11_0036, 3, 'take').
keywords(s_book_11_0036, ['answer', 'beginning', 'cyclic', 'previou', 'question', 'several', 'shape', 'state', 'three', 'universe', 'whether']).
sentence(s_book_11_0037, 'book', 11, 43, 'unmarked', "Loop quantum cosmology proposes that the Big Bang was not a singularity but a bounce: a prior contracting universe reaching a minimum volume at which quantum effects make gravity repulsive, and rebounding.").
sentence(s_book_11_0038, 'book', 11, 43, 'unmarked', "On this account the beginning was a transition rather than an origin.").
sentence(s_book_11_0039, 'book', 11, 45, 'unmarked', "Conformal cyclic cosmology, developed by Roger Penrose and set out for general readers in Cycles of Time (2010), proposes a sequence of aeons in which the remote future of one — expanded, cooled, with its black holes evaporated and little left but radiation — is geometrically equivalent to the hot dense beginning of the next.").
year(s_book_11_0039, 2010).
keywords(s_book_11_0039, ['beginning', 'black', 'conformal', 'cooled', 'cosmology', 'cycle', 'cyclic', 'dense', 'developed', 'equivalent', 'evaporated', 'expanded', 'future', 'general', 'geometrically', 'little', 'penrose', 'propose', 'radiation', 'reader', 'remote', 'roger', 'sequence']).
sentence(s_book_11_0040, 'book', 11, 45, 'unmarked', "Penrose and collaborators argued in 2020 that faint circular features in the cosmic microwave background are traces of black hole evaporation in a previous aeon.").
year(s_book_11_0040, 2020).
keywords(s_book_11_0040, ['argued', 'background', 'black', 'circular', 'collaborator', 'cosmic', 'evaporation', 'faint', 'feature', 'microwave', 'penrose', 'previou', 'trace']).
hedged(s_book_11_0040).
cites(s_book_11_0040, 'Penrose', 2020).
sentence(s_book_11_0041, 'book', 11, 45, 'unmarked', "Other groups have disputed the analysis, arguing the features are consistent with chance in random data, and the claim is not accepted.").
hedged(s_book_11_0041).
sentence(s_book_11_0042, 'book', 11, 47, 'unmarked', "Cosmological natural selection, proposed by Lee Smolin in 1992, is the most structurally interesting of the three for this book's purposes, because it applies the vocabulary of chapter 9 to physics itself.").
year(s_book_11_0042, 1992).
number(s_book_11_0042, 3, 'book').
keywords(s_book_11_0042, ['apply', 'because', 'chapter', 'cosmological', 'interesting', 'itself', 'natural', 'physic', 'proposed', 'purpose', 'selection', 'smolin', 'structurally', 'three', 'vocabulary']).
hedged(s_book_11_0042).
xref(s_book_11_0042, 9).
cites(s_book_11_0042, 'Smolin', 1992).
sentence(s_book_11_0043, 'book', 11, 47, 'unmarked', "The suggestion is that black holes produce new regions of spacetime with slightly different physical constants, that universes producing more black holes therefore leave more descendants, and that the constants observed here are the ones that happen to be good at making black holes.").
sentence(s_book_11_0044, 'book', 11, 49, 'unmarked', "Smolin's proposal deserves attention for a reason unrelated to whether it is true: a falsifiable prediction was derived from it.").
hedged(s_book_11_0044).
sentence(s_book_11_0045, 'book', 11, 49, 'unmarked', "Combined with calculations of how matter behaves in the cores of neutron stars, published in 1994, maximizing black hole production implies an upper limit on neutron star mass, which Smolin put at about 1.6 times the mass of the Sun.").
year(s_book_11_0045, 1994).
number(s_book_11_0045, 1.6, 'mass').
keywords(s_book_11_0045, ['behave', 'black', 'calculation', 'combined', 'imply', 'limit', 'matter', 'maximizing', 'neutron', 'production', 'published', 'smolin', 'upper']).
sentence(s_book_11_0046, 'book', 11, 49, 'unmarked', "He stated the stakes plainly in 2004: a neutron star heavier than about 1.5 solar masses would be troubling for the theory, and one of 2.5 would certainly refute it.").
year(s_book_11_0046, 2004).
number(s_book_11_0046, 1.5, 'solar').
number(s_book_11_0046, 2.5, 'would').
