sentence(s_book_11_0048, 'book', 11, 51, 'unmarked', "The limit he committed to has been exceeded several times.").
sentence(s_book_11_0049, 'book', 11, 51, 'unmarked', "The higher figure he named as certain refutation has not yet been reached.").
sentence(s_book_11_0050, 'book', 11, 53, 'unmarked', "Smolin has argued the proposal can be rescued; others treat it as refuted.").
hedged(s_book_11_0050).
sentence(s_book_11_0051, 'book', 11, 53, 'unmarked', "Either way it did the thing this book's own weakest material does not do, which is put a number where it could be checked, so that the result could come back wrong — and it did.").
sentence(s_book_11_0052, 'book', 11, 53, 'unmarked', "Chapter 17 returns to why that is harder than it sounds.").
xref(s_book_11_0052, 17).
sentence(s_book_11_0053, 'book', 11, 55, 'unmarked', "The attraction of all three is obvious, and it is worth being explicit about why that is a reason for caution rather than confidence.").
number(s_book_11_0053, 3, 'obviou').
keywords(s_book_11_0053, ['attraction', 'caution', 'confidence', 'explicit', 'obviou', 'rather', 'reason', 'three', 'worth']).
sentence(s_book_11_0054, 'book', 11, 55, 'unmarked', "A reader who has just been shown cycles that accumulate at every other scale will find a cosmic version satisfying, and that satisfaction is not evidence.").
sentence(s_book_11_0055, 'book', 11, 55, 'unmarked', "The physics here is contested among specialists, and the pattern-matching that makes it appealing is no substitute for their understanding.").
hedged(s_book_11_0055).
sentence(s_book_11_0056, 'book', 11, 55, 'unmarked', "It is included as an open question, and chapter 17 says more about why questions of this kind are where a framework like this one is most likely to mislead.").
