chapter('book', 12, "12-life-as-a-category.md", "12. Life as a category").
sentence(s_book_12_0001, 'book', 12, 3, 'unmarked', "The definition of life is less straightforward than it first appears, and the difficulty is more interesting than a definitional quibble.").
hedged(s_book_12_0001).
sentence(s_book_12_0002, 'book', 12, 5, 'unmarked', "Life is generally recognized through a cluster of characteristics: metabolism, energy use, organization, growth, response to the environment, reproduction, heredity, and evolution.").
sentence(s_book_12_0003, 'book', 12, 5, 'unmarked', "Not every living thing displays all of them in the same way, and various non-living systems display some of them convincingly.").
sentence(s_book_12_0004, 'book', 12, 9, 'unmarked', "Fire metabolizes, in a loose but not empty sense.").
sentence(s_book_12_0005, 'book', 12, 9, 'unmarked', "It consumes fuel, releases energy, maintains itself as long as supply lasts, grows, responds to its environment, and spreads from place to place in a way that resembles reproduction.").
sentence(s_book_12_0006, 'book', 12, 9, 'unmarked', "What it has no trace of is heredity.").
sentence(s_book_12_0007, 'book', 12, 9, 'unmarked', "One fire does not pass traits to the next, so nothing accumulates and nothing evolves.").
sentence(s_book_12_0008, 'book', 12, 9, 'unmarked', "Fire is the cleanest demonstration that the metabolic properties on their own are not sufficient.").
sentence(s_book_12_0009, 'book', 12, 11, 'unmarked', "Crystals grow by adding material in an ordered arrangement, and they propagate structure: a seed crystal placed in a solution produces more crystals of the same form.").
sentence(s_book_12_0010, 'book', 12, 11, 'unmarked', "Pattern is being copied.").
sentence(s_book_12_0011, 'book', 12, 11, 'unmarked', "But the pattern admits almost no variation that could be inherited and selected, so again nothing accumulates.").
sentence(s_book_12_0012, 'book', 12, 13, 'unmarked', "Stalagmites grow, are organized by physical and chemical conditions, and take on forms that depend on their local history.").
sentence(s_book_12_0013, 'book', 12, 13, 'unmarked', "They do not reproduce.").
sentence(s_book_12_0014, 'book', 12, 15, 'unmarked', "Prions are proteins that propagate a misfolded shape by inducing the same misfolding in normal copies of the same protein.").
sentence(s_book_12_0015, 'book', 12, 15, 'unmarked', "Structural information is copied from one molecule to another with no nucleic acid involved at all.").
sentence(s_book_12_0016, 'book', 12, 15, 'unmarked', "Whether this counts as heredity depends entirely on how the word is defined.").
sentence(s_book_12_0017, 'book', 12, 17, 'unmarked', "Viruses carry genetic information, mutate, evolve under selection, and are unambiguously subject to the processes this book describes.").
sentence(s_book_12_0018, 'book', 12, 17, 'unmarked', "They also cannot metabolize or reproduce without commandeering a host cell.").
sentence(s_book_12_0019, 'book', 12, 17, 'unmarked', "Their status has been argued for a century without resolution.").
hedged(s_book_12_0019).
sentence(s_book_12_0020, 'book', 12, 19, 'unmarked', "The viral case has become harder rather than easier.").
sentence(s_book_12_0021, 'book', 12, 19, 'unmarked', "Giant viruses discovered in the last two decades have genomes larger than those of some free-living bacteria and encode components of the protein-synthesis machinery that viruses were supposed to lack entirely.").
number(s_book_12_0021, 2, 'decade').
keywords(s_book_12_0021, ['bacteria', 'component', 'decade', 'discovered', 'encode', 'entirely', 'free-living', 'genome', 'giant', 'larger', 'machinery', 'protein-synthesi', 'supposed', 'viruse']).
sentence(s_book_12_0022, 'book', 12, 19, 'unmarked', "Meanwhile various bacteria — including those causing typhus and chlamydia — have lost so much of their own metabolism that they cannot reproduce outside a host cell either.").
sentence(s_book_12_0023, 'book', 12, 19, 'unmarked', "The property once used to separate viruses from organisms turns out to be held by neither group exclusively.").
sentence(s_book_12_0024, 'book', 12, 21, 'unmarked', "These cases demonstrate why it matters to distinguish growth, energy use, information, replication, heredity, metabolism, and evolution rather than treating them as a package.").
sentence(s_book_12_0025, 'book', 12, 21, 'unmarked', "They come apart.").
sentence(s_book_12_0026, 'book', 12, 21, 'unmarked', "Different systems hold different subsets.").
sentence(s_book_12_0027, 'book', 12, 25, 'unmarked', "Attempts at a formal definition exist in quantity.").
sentence(s_book_12_0028, 'book', 12, 25, 'unmarked', "One compilation counts over a hundred and twenty distinct published definitions of life, which is itself the most informative fact in this section: a concept with one definition has been pinned down, and a concept with a hundred and twenty has not.").
number(s_book_12_0028, 120, 'distinct').
number(s_book_12_0028, 120, 'has').
keywords(s_book_12_0028, ['compilation', 'concept', 'count', 'definition', 'distinct', 'hundred', 'informative', 'itself', 'pinned', 'published', 'section', 'twenty']).
sentence(s_book_12_0029, 'book', 12, 27, 'unmarked', "The most widely used working version — adopted by a NASA committee needing something operational for the purpose of looking for life elsewhere, and originally suggested by Carl Sagan — describes life as a self-sustaining chemical system capable of Darwinian evolution.").
sentence(s_book_12_0030, 'book', 12, 27, 'unmarked', "It is compact and does real work.").
sentence(s_book_12_0031, 'book', 12, 29, 'unmarked', "It also has a well-known problem, and it is the obvious one.").
sentence(s_book_12_0032, 'book', 12, 29, 'unmarked', "An individual organism that cannot reproduce — through sterility, age, or being the only one of its kind — is not itself capable of Darwinian evolution, though nobody would call it non-living.").
sentence(s_book_12_0033, 'book', 12, 29, 'unmarked', "The definition describes populations and lineages better than individuals.").
sentence(s_book_12_0034, 'book', 12, 29, 'unmarked', "Adjusting it to cover individuals tends to let in things it was meant to exclude.").
sentence(s_book_12_0035, 'book', 12, 31, 'unmarked', "This pattern is general.").
sentence(s_book_12_0036, 'book', 12, 31, 'unmarked', "Every proposed definition either rules out something uncontroversially alive or admits something uncontroversially not, and the usual response is a further clause, which produces a definition that is accurate and no longer says anything.").
hedged(s_book_12_0036).
sentence(s_book_12_0037, 'book', 12, 31, 'unmarked', "A hundred and twenty attempts have not converged, and the failure to converge may not be a failure of effort.").
number(s_book_12_0037, 120, 'attempt').
keywords(s_book_12_0037, ['attempt', 'converge', 'converged', 'effort', 'failure', 'hundred', 'twenty']).
hedged(s_book_12_0037).
sentence(s_book_12_0038, 'book', 12, 35, 'unmarked', "It is worth being precise about what kind of problem this is, because the obvious reading is wrong.").
sentence(s_book_12_0039, 'book', 12, 37, 'unmarked', "Consider a heap of sand.").
sentence(s_book_12_0040, 'book', 12, 37, 'unmarked', "Removing one grain never turns a heap into a non-heap.").
certainty_word(s_book_12_0040, 'never').
sentence(s_book_12_0041, 'book', 12, 37, 'unmarked', "Yet a single grain is not a heap.").
sentence(s_book_12_0042, 'book', 12, 37, 'unmarked', "There is no particular grain at which the transition occurs, and this is not because the matter has been inadequately investigated.").
sentence(s_book_12_0043, 'book', 12, 37, 'unmarked', "The concept has fuzzy edges, and no amount of further study of sand will sharpen them.").
sentence(s_book_12_0044, 'book', 12, 39, 'unmarked', "\"Life\" appears to be the same kind of concept.").
hedged(s_book_12_0044).
sentence(s_book_12_0045, 'book', 12, 39, 'unmarked', "It picks out a cluster of properties that usually travel together, and it works well in the ordinary case precisely because they usually do.").
sentence(s_book_12_0046, 'book', 12, 39, 'unmarked', "It gives no answer at the edges because it was never the kind of thing that had one.").
certainty_word(s_book_12_0046, 'never').
sentence(s_book_12_0047, 'book', 12, 41, 'unmarked', "The consequence matters for everything in chapters 3 through 5 and 8.").
xref(s_book_12_0047, 3).
xref(s_book_12_0047, 5).
xref(s_book_12_0047, 8).
sentence(s_book_12_0048, 'book', 12, 41, 'unmarked', "\"When did life begin\" is malformed in the same way \"when did it become a heap\" is malformed.").
sentence(s_book_12_0049, 'book', 12, 41, 'unmarked', "Those chapters describe properties accumulating one at a time — chemistry that persists, boundaries that localize, networks that sustain themselves, structures that copy — each step small, each step chemical, no step requiring anything the preceding one lacked.").
sentence(s_book_12_0050, 'book', 12, 41, 'unmarked', "The question expects a moment.").
sentence(s_book_12_0051, 'book', 12, 41, 'unmarked', "There is no moment, and the absence is not a hole in the account.").
sentence(s_book_12_0052, 'book', 12, 43, 'unmarked', "This should not be mistaken for the claim that there is no problem.").
sentence(s_book_12_0053, 'book', 12, 43, 'unmarked', "There is a large one, named in chapter 8 and again in chapter 17: how a chemical system first came to copy a pattern reliably enough for selection to accumulate is not known.").
xref(s_book_12_0053, 8).
xref(s_book_12_0053, 17).
sentence(s_book_12_0054, 'book', 12, 43, 'unmarked', "What dissolves is the expectation of a single threshold event with a single explanation.").
sentence(s_book_12_0055, 'book', 12, 43, 'unmarked', "What remains is a sequence of transitions, at least one of which is genuinely unexplained.").
sentence(s_book_12_0056, 'book', 12, 43, 'unmarked', "That is a different shape of ignorance, and a more tractable one.").
sentence(s_book_12_0057, 'book', 12, 47, 'unmarked', "One further limit, more serious than the definitional one.").
sentence(s_book_12_0058, 'book', 12, 49, 'unmarked', "Every characteristic in the opening list was derived from examples of a single kind: terrestrial, carbon-based, water-dependent, cellular, descended from a common ancestor.").
sentence(s_book_12_0059, 'book', 12, 49, 'unmarked', "The definition of life is a generalization from one case.").
sentence(s_book_12_0060, 'book', 12, 51, 'unmarked', "A category built from one example cannot be known to be general.").
certainty_word(s_book_12_0060, 'cannot be').
sentence(s_book_12_0061, 'book', 12, 51, 'unmarked', "There may be organized, energy-driven systems that fail the familiar criteria and are nonetheless the kind of thing the category was reaching for.").
hedged(s_book_12_0061).
sentence(s_book_12_0062, 'book', 12, 51, 'unmarked', "There may equally be none.").
hedged(s_book_12_0062).
sentence(s_book_12_0063, 'book', 12, 51, 'unmarked', "The possibility is open, and openness is not evidence.").
sentence(s_book_12_0064, 'book', 12, 53, 'unmarked', "What can be said is narrow: it is possible to measure familiar biological life with great precision while still being unsure how widely the category should extend.").
sentence(s_book_12_0065, 'book', 12, 53, 'unmarked', "Those are different competencies, and the first does not supply the second.").
chapter('book', 13, "13-cognition.md", "13. Cognition: information becomes representation").
sentence(s_book_13_0001, 'book', 13, 3, 'unmarked', "Biological systems developed increasingly sophisticated ways of sensing and responding to their environments.").
sentence(s_book_13_0002, 'book', 13, 5, 'unmarked', "Nervous systems allow organisms to process signals, coordinate behaviour, and respond to changing conditions.").
sentence(s_book_13_0003, 'book', 13, 5, 'unmarked', "In more complex brains, information can be integrated into representations that support memory, prediction, categorization, and decision-making.").
sentence(s_book_13_0004, 'book', 13, 7, 'unmarked', "Cognition can be understood partly as a process of information compression.").
sentence(s_book_13_0005, 'book', 13, 11, 'unmarked', "The compression claim is easy to state and worth making concrete, because the quantity discarded is the surprising part.").
sentence(s_book_13_0006, 'book', 13, 13, 'unmarked', "The discarding starts before anything reaches the brain, and it can be counted.").
sentence(s_book_13_0007, 'book', 13, 13, 'unmarked', "A human retina holds something like ninety-six million photoreceptors.").
number(s_book_13_0007, 9.6e+07, 'photoreceptor').
keywords(s_book_13_0007, ['human', 'million', 'ninety-six', 'photoreceptor', 'retina', 'something']).
sentence(s_book_13_0008, 'book', 13, 13, 'unmarked', "The optic nerve carrying their output to the brain contains roughly one million fibres.").
number(s_book_13_0008, 1e+06, 'fibre').
keywords(s_book_13_0008, ['brain', 'carrying', 'contain', 'fibre', 'million', 'nerve', 'optic', 'output']).
sentence(s_book_13_0009, 'book', 13, 13, 'unmarked', "Around a hundred receptors feed each one, and the reduction is not uniform — at the centre of vision each receptor has an output fibre to itself, and may have two, while towards the edge a single fibre serves hundreds.").
number(s_book_13_0009, 100, 'receptor').
number(s_book_13_0009, 2, 'while').
keywords(s_book_13_0009, ['centre', 'fibre', 'hundred', 'itself', 'output', 'receptor', 'reduction', 'serve', 'single', 'toward', 'uniform', 'vision', 'while']).
hedged(s_book_13_0009).
sentence(s_book_13_0010, 'book', 13, 15, 'unmarked', "So the eye is not a camera sending pictures inward.").
sentence(s_book_13_0011, 'book', 13, 15, 'unmarked', "It is a device that throws away about ninety-nine per cent of what it collects before transmission, and what survives is already processed into edges, motion, contrast boundaries, and change rather than a faithful record of light levels.").
number(s_book_13_0011, 99, 'cent').
keywords(s_book_13_0011, ['already', 'boundary', 'change', 'collect', 'contrast', 'device', 'faithful', 'level', 'light', 'motion', 'ninety-nine', 'processed', 'rather', 'record', 'survive', 'throw', 'transmission']).
sentence(s_book_13_0012, 'book', 13, 15, 'unmarked', "By the time anything reaches awareness it has passed through several further stages of selection and summary.").
sentence(s_book_13_0013, 'book', 13, 15, 'unmarked', "The experience of seeing a room does not involve holding the room in mind.").
sentence(s_book_13_0014, 'book', 13, 15, 'unmarked', "It involves holding a model adequate for acting in the room.").
sentence(s_book_13_0015, 'book', 13, 17, 'unmarked', "The model is built from regularities.").
sentence(s_book_13_0016, 'book', 13, 17, 'unmarked', "A brain identifies what recurs, treats recurrences as instances of a category, and stores the category rather than the instances.").
sentence(s_book_13_0017, 'book', 13, 17, 'unmarked', "This is why a familiar object is recognized from an angle never seen before, and also why an eyewitness account degrades towards the typical case.").
certainty_word(s_book_13_0017, 'never').
sentence(s_book_13_0018, 'book', 13, 19, 'unmarked', "Cognitive processes include:").
sentence(s_book_13_0019, 'book', 13, 21, 'unmarked', "- Pattern recognition. - Categorization. - Association. - Memory. - Prediction. - Learning. - Attention. - Abstraction.").
sentence(s_book_13_0020, 'book', 13, 30, 'unmarked', "Every item on that list discards something.").
sentence(s_book_13_0021, 'book', 13, 30, 'unmarked', "Attention discards most of the available input.").
sentence(s_book_13_0022, 'book', 13, 30, 'unmarked', "Categorization discards the differences between members of a category.").
sentence(s_book_13_0023, 'book', 13, 30, 'unmarked', "Memory discards detail and reconstructs it on demand, which is why recollection is more like rebuilding than like retrieval.").
sentence(s_book_13_0024, 'book', 13, 32, 'unmarked', "The payoff is prediction.").
sentence(s_book_13_0025, 'book', 13, 32, 'unmarked', "A system holding a compressed model of its environment can anticipate what has not happened yet, and act before it does.").
sentence(s_book_13_0026, 'book', 13, 32, 'unmarked', "An organism responding only to present stimuli is always late.").
certainty_word(s_book_13_0026, 'always').
sentence(s_book_13_0027, 'book', 13, 34, 'unmarked', "This is the same trade that appeared in chapter 8, running on different hardware.").
xref(s_book_13_0027, 8).
sentence(s_book_13_0028, 'book', 13, 34, 'unmarked', "The genetic code tolerates error where error is cheap and resists it where error is expensive.").
sentence(s_book_13_0029, 'book', 13, 34, 'unmarked', "A nervous system discards detail where detail does not change what to do, and preserves it where it does.").
sentence(s_book_13_0030, 'book', 13, 34, 'unmarked', "Neither system was designed to compress.").
sentence(s_book_13_0031, 'book', 13, 34, 'unmarked', "Both ended up compressing, because a system that keeps everything cannot act in time.").
sentence(s_book_13_0032, 'book', 13, 38, 'unmarked', "A model of the environment is useful.").
sentence(s_book_13_0033, 'book', 13, 38, 'unmarked', "A model that includes the modeller is a different kind of thing.").
sentence(s_book_13_0034, 'book', 13, 40, 'unmarked', "An organism that represents its own body, its own position, and eventually its own representing has begun to do something recursive.").
sentence(s_book_13_0035, 'book', 13, 40, 'unmarked', "Douglas Hofstadter gave this the name strange loop: a system that, by moving through its own levels of description, arrives back where it started.").
sentence(s_book_13_0036, 'book', 13, 40, 'unmarked', "His argument, developed in Gödel, Escher, Bach and more directly in I Am a Strange Loop, is that the sense of being a unified self is what such recursion feels like from inside.").
sentence(s_book_13_0037, 'book', 13, 40, 'unmarked', "Not a thing located somewhere in the brain.").
sentence(s_book_13_0038, 'book', 13, 40, 'unmarked', "A pattern the brain produces by modelling itself modelling.").
sentence(s_book_13_0039, 'book', 13, 42, 'unmarked', "Marvin Minsky's The Society of Mind approaches the same conclusion from the other direction.").
sentence(s_book_13_0040, 'book', 13, 42, 'unmarked', "On his account the mind was never unified to begin with.").
certainty_word(s_book_13_0040, 'never').
sentence(s_book_13_0041, 'book', 13, 42, 'unmarked', "It is a large number of specialized processes — handling vision, sound, balance, memory, planning, threat — none of which individually contains a self, and which collectively generate the appearance of one through their interaction.").
sentence(s_book_13_0042, 'book', 13, 44, 'unmarked', "A murmuration of starlings is a useful comparison, provided it is held as a comparison.").
sentence(s_book_13_0043, 'book', 13, 44, 'unmarked', "The flock turns as a unit and appears to be directed.").
hedged(s_book_13_0043).
sentence(s_book_13_0044, 'book', 13, 44, 'unmarked', "No bird is directing it.").
sentence(s_book_13_0045, 'book', 13, 44, 'unmarked', "Each responds to a handful of neighbours, and the coordinated shape is what those local responses produce at scale.").
sentence(s_book_13_0046, 'book', 13, 44, 'unmarked', "The pattern is entirely real.").
sentence(s_book_13_0047, 'book', 13, 44, 'unmarked', "A central decider behind the pattern is not.").
sentence(s_book_13_0048, 'book', 13, 44, 'unmarked', "The resemblance to a mind is structural rather than mechanistic — neurons and starlings have little in common beyond both being many things interacting locally — but it makes the point that unified-looking behaviour does not require a unifier.").
sentence(s_book_13_0049, 'book', 13, 46, 'unmarked', "This recursion also marks a threshold worth naming, because it is the one the rest of the book runs through:").
sentence(s_book_13_0050, 'book', 13, 48, 'unmarked', "- Self-replicating chemistry carries a minimal kind of self-reference: make more of this. - Genetic systems extend it: encode the pattern for making more patterns. - Nervous systems model the world. - Some nervous systems model their own modelling. - Language externalizes that model, so another mind can receive it. - Culture accumulates externalized models across generations.").
sentence(s_book_13_0051, 'book', 13, 55, 'unmarked', "Each step reuses what the previous one built.").
sentence(s_book_13_0052, 'book', 13, 55, 'unmarked', "None of them required the next one to follow.").
sentence(s_book_13_0053, 'book', 13, 57, 'unmarked', "None of this explains why information processing is accompanied by experience — why there is something it is like to be a system modelling itself.").
sentence(s_book_13_0054, 'book', 13, 57, 'unmarked', "Hofstadter and Minsky describe an architecture.").
sentence(s_book_13_0055, 'book', 13, 57, 'unmarked', "The question of felt experience is not answered by describing it, and chapter 17 returns to this as one of the places the framework stops.").
xref(s_book_13_0055, 17).
sentence(s_book_13_0056, 'book', 13, 61, 'unmarked', "Underneath representation sits something older and simpler.").
sentence(s_book_13_0057, 'book', 13, 63, 'unmarked', "Organisms assign value.").
sentence(s_book_13_0058, 'book', 13, 63, 'unmarked', "Approach this, avoid that.").
sentence(s_book_13_0059, 'book', 13, 63, 'unmarked', "A bacterium swimming up a nutrient gradient is doing a rudimentary version; a plant growing towards light is doing another.").
sentence(s_book_13_0060, 'book', 13, 63, 'unmarked', "These are not decisions, and nothing needs to be experienced for them to work.").
sentence(s_book_13_0061, 'book', 13, 63, 'unmarked', "But they are the beginning of a system that sorts the world into better and worse.").
sentence(s_book_13_0062, 'book', 13, 65, 'unmarked', "As environments and bodies became more complicated, so did the sorting.").
sentence(s_book_13_0063, 'book', 13, 65, 'unmarked', "More signals, more possible responses, longer time horizons, and eventually states that integrate many inputs at once — the layered and often contradictory things humans call emotions.").
sentence(s_book_13_0064, 'book', 13, 67, 'unmarked', "There is a tempting move here, and it should be resisted.").
sentence(s_book_13_0065, 'book', 13, 67, 'unmarked', "It is tempting to say that consciousness is this valuation system, scaled up and nothing more.").
sentence(s_book_13_0066, 'book', 13, 67, 'unmarked', "That claim does real work: it makes the capacity continuous rather than a sudden arrival, which fits everything else in this book, and it explains why the machinery of value is so deeply conserved.").
sentence(s_book_13_0067, 'book', 13, 67, 'unmarked', "But it does not touch the question of experience raised above, and treating it as though it does would be the kind of overreach this book is trying to avoid.").
sentence(s_book_13_0068, 'book', 13, 69, 'unmarked', "What can be said is narrower and still useful.").
sentence(s_book_13_0069, 'book', 13, 69, 'unmarked', "The sophistication of information processing varies continuously across living systems.").
sentence(s_book_13_0070, 'book', 13, 69, 'unmarked', "Drawing a line somewhere on that continuum and calling everything above it conscious is a decision about where to put a word.").
sentence(s_book_13_0071, 'book', 13, 69, 'unmarked', "It is not the discovery of a boundary in nature.").
sentence(s_book_13_0072, 'book', 13, 73, 'unmarked', "One concrete case of how a brain might be reshaped by what it processes.").
hedged(s_book_13_0072).
sentence(s_book_13_0073, 'book', 13, 75, 'unmarked', "Following a Bach fugue means tracking several melodic lines at once.").
sentence(s_book_13_0074, 'book', 13, 75, 'unmarked', "Each is independent, each is mathematically related to the others, and the relationships — inversion, transposition, one voice entering against another already in progress — have to be held simultaneously rather than in sequence.").
sentence(s_book_13_0075, 'book', 13, 75, 'unmarked', "The listener is not receiving a melody.").
sentence(s_book_13_0076, 'book', 13, 75, 'unmarked', "The listener is running several, in parallel, and detecting their relations.").
sentence(s_book_13_0077, 'book', 13, 77, 'unmarked', "That is a demanding exercise, and the theory is that demanding exercises change the systems that perform them.").
sentence(s_book_13_0078, 'book', 13, 77, 'unmarked', "The body offers an undisputed version: a guitarist's fingertips harden into calluses where the strings press, and nobody suspects guitarists of being born with hard fingertips.").
sentence(s_book_13_0079, 'book', 13, 77, 'unmarked', "A brain is harder to read, because most of the evidence compares different people rather than the same person before and after.").
sentence(s_book_13_0080, 'book', 13, 77, 'unmarked', "Trained musicians show measurable differences in auditory and motor regions relative to non-musicians, and the differences scale with training.").
sentence(s_book_13_0081, 'book', 13, 79, 'unmarked', "The direction of causation is genuinely unsettled, and the honest version has to say so: people who take up music may differ beforehand in ways that predispose them both to continue and to show those differences.").
hedged(s_book_13_0081).
sentence(s_book_13_0082, 'book', 13, 79, 'unmarked', "Longitudinal work has found changes that follow training, which argues for real effect, but the size of that effect and how far it generalizes beyond music are both disputed.").
hedged(s_book_13_0082).
sentence(s_book_13_0083, 'book', 13, 81, 'unmarked', "What survives the dispute is the structural point.").
sentence(s_book_13_0084, 'book', 13, 81, 'unmarked', "A fugue is a piece of external structure whose internal organization requires parallel, recursive processing to follow.").
sentence(s_book_13_0085, 'book', 13, 81, 'unmarked', "Engaging with it exercises exactly that.").
sentence(s_book_13_0086, 'book', 13, 81, 'unmarked', "Whether or not the benefit generalizes, the arrangement is worth noticing: a cultural artefact built to be complex in a specific way, which exercises the capacity needed to handle it and, if the theory holds, builds it.").
sentence(s_book_13_0087, 'book', 13, 87, 'unmarked', "These processes are powerful and they are not reliable.").
sentence(s_book_13_0088, 'book', 13, 89, 'unmarked', "The faculty that finds genuine structure also finds structure that is not there.").
sentence(s_book_13_0089, 'book', 13, 89, 'unmarked', "Humans are unusually good at transferring patterns across domains — noticing that two unlike systems seem to work alike — and this supports analogy, invention, scientific insight, and storytelling.").
number(s_book_13_0089, 2, 'unlike').
keywords(s_book_13_0089, ['across', 'alike', 'analogy', 'domain', 'human', 'insight', 'invention', 'noticing', 'pattern', 'scientific', 'storytelling', 'support', 'system', 'transferring', 'unlike', 'unusually']).
hedged(s_book_13_0089).
sentence(s_book_13_0090, 'book', 13, 89, 'unmarked', "It also produces confident connections between things that have nothing to do with each other.").
sentence(s_book_13_0091, 'book', 13, 91, 'unmarked', "The capacity has no reliable internal signal distinguishing the two cases.").
number(s_book_13_0091, 2, 'case').
keywords(s_book_13_0091, ['capacity', 'distinguishing', 'internal', 'reliable', 'signal']).
sentence(s_book_13_0092, 'book', 13, 91, 'unmarked', "In experiments, solutions that arrive with a feeling of sudden fit are more often right than solutions worked out step by step, and the feeling is stronger for right ones; but wrong ones can bring it too, and a feeling of fit borrowed from something unrelated can make a false statement seem truer.").
hedged(s_book_13_0092).
sentence(s_book_13_0093, 'book', 13, 93, 'unmarked', "This is the problem the Preface describes from the inside, and it is the reason this book keeps marking which claims are established, which are contested, and which belong to its author.").
hedged(s_book_13_0093).
sentence(s_book_13_0094, 'book', 13, 93, 'unmarked', "The marking is not modesty.").
sentence(s_book_13_0095, 'book', 13, 93, 'unmarked', "It is the only available correction for a faculty that cannot reliably audit itself.").
chapter('book', 14, "14-language.md", "14. Language as cultural protochemistry").
sentence(s_book_14_0001, 'book', 14, 3, 'unmarked', "Language is a system in which small units combine into larger ones.").
sentence(s_book_14_0002, 'book', 14, 5, 'unmarked', "Sounds combine into words.").
sentence(s_book_14_0003, 'book', 14, 5, 'unmarked', "Words combine into phrases and sentences.").
sentence(s_book_14_0004, 'book', 14, 5, 'unmarked', "Grammar constrains how elements may be arranged, and meaning arises from the relationships among them together with shared social convention.").
hedged(s_book_14_0004).
sentence(s_book_14_0005, 'book', 14, 7, 'unmarked', "Language changes through use, variation, selection, retention, and transmission.").
sentence(s_book_14_0006, 'book', 14, 7, 'unmarked', "New words and expressions appear; some are adopted widely and others disappear.").
hedged(s_book_14_0006).
sentence(s_book_14_0007, 'book', 14, 7, 'unmarked', "Pronunciations shift, grammatical structures change, and meanings move.").
sentence(s_book_14_0008, 'book', 14, 9, 'unmarked', "The phrase language as protochemistry describes the combinatorial part of this: small reusable units, constrained ways of joining them, and complexity built from both.").
sentence(s_book_14_0009, 'book', 14, 9, 'unmarked', "It is an analogy and not a claim that language operates through chemical reactions.").
sentence(s_book_14_0010, 'book', 14, 9, 'unmarked', "What the two have in common is a combinatorial structure with rules about what may attach to what.").
number(s_book_14_0010, 2, 'have').
keywords(s_book_14_0010, ['attach', 'combinatorial', 'common', 'structure']).
hedged(s_book_14_0010).
sentence(s_book_14_0011, 'book', 14, 9, 'unmarked', "The mechanisms have nothing else in common at all.").
sentence(s_book_14_0012, 'book', 14, 11, 'unmarked', "Some recurring sounds across unrelated languages reflect shared anatomy rather than shared history.").
sentence(s_book_14_0013, 'book', 14, 11, 'unmarked', "Words resembling mama and dada recur widely in part because the consonants involved are among the earliest an infant vocal tract produces reliably, and because caregivers are present to interpret those sounds as referring to them.").
sentence(s_book_14_0014, 'book', 14, 11, 'unmarked', "Similar forms can arise from common constraints as easily as from common descent.").
sentence(s_book_14_0015, 'book', 14, 15, 'unmarked', "This is the question the chapter has to handle carefully, because it is the one where popular accounts and the evidence diverge most.").
sentence(s_book_14_0016, 'book', 14, 19, 'unmarked', "The standard illustration is that Inuit languages have an extraordinary number of words for snow, and that this lets their speakers perceive distinctions other speakers cannot.").
sentence(s_book_14_0017, 'book', 14, 21, 'unmarked', "The claim as usually told is not reliable, and the chain by which it became unreliable is documented in detail.").
sentence(s_book_14_0018, 'book', 14, 23, 'unmarked', "Franz Boas, in 1911, noted four distinct roots — for snow on the ground, falling snow, drifting snow, and a snowdrift.").
year(s_book_14_0018, 1911).
number(s_book_14_0018, 4, 'distinct').
keywords(s_book_14_0018, ['distinct', 'drifting', 'falling', 'franz', 'ground', 'noted', 'snowdrift']).
cites(s_book_14_0018, 'Boas', 1911).
sentence(s_book_14_0019, 'book', 14, 23, 'unmarked', "He did not suggest this was a large number or that it meant anything in particular.").
hedged(s_book_14_0019).
sentence(s_book_14_0020, 'book', 14, 23, 'unmarked', "Benjamin Lee Whorf, in a 1940 article, repeated the observation with seven, three of which he did not source.").
year(s_book_14_0020, 1940).
number(s_book_14_0020, 7, 'three').
number(s_book_14_0020, 3, 'none').
keywords(s_book_14_0020, ['article', 'benjamin', 'observation', 'repeated', 'seven', 'source', 'three', 'whorf']).
cites(s_book_14_0020, 'Whorf', 1940).
sentence(s_book_14_0021, 'book', 14, 23, 'unmarked', "Later retellings escalated into dozens and then hundreds, each citing the retelling before it.").
sentence(s_book_14_0022, 'book', 14, 23, 'unmarked', "Laura Martin traced this history in 1986, and Geoffrey Pullum's 1989 essay popularizing her case gave it the name it is now known by, the Great Eskimo Vocabulary Hoax.").
year(s_book_14_0022, 1986).
year(s_book_14_0022, 1989).
keywords(s_book_14_0022, ['eskimo', 'essay', 'geoffrey', 'great', 'history', 'known', 'laura', 'martin', 'popularizing', 'pullum', 'traced', 'vocabulary']).
cites(s_book_14_0022, 'Pullum', 1989).
cites(s_book_14_0022, 'Martin', 1986).
sentence(s_book_14_0023, 'book', 14, 23, 'unmarked', "A reader who knows this will discount any argument leaning on the popular version, and should.").
sentence(s_book_14_0024, 'book', 14, 25, 'unmarked', "Two things are nonetheless true and worth separating out.").
number(s_book_14_0024, 2, 'thing').
keywords(s_book_14_0024, ['nonetheless', 'separating', 'thing', 'worth']).
sentence(s_book_14_0025, 'book', 14, 27, 'unmarked', "Counting words is the wrong question for these languages.").
sentence(s_book_14_0026, 'book', 14, 27, 'unmarked', "They are polysynthetic, building long words from stacked affixes, so the number of constructible \"words\" for anything is effectively unbounded and a count measures nothing.").
sentence(s_book_14_0027, 'book', 14, 29, 'unmarked', "And when researchers went and asked — working with speakers who travel on sea ice and need these distinctions to survive — the vocabularies turned out to be both large and highly structured.").
sentence(s_book_14_0028, 'book', 14, 29, 'unmarked', "Surveys across roughly ten Inuit and Yupik dialects have recorded on the order of seventy terms for ice conditions in one Alaskan dialect, around forty snow descriptors in Central Siberian Yupik, and some fifty in a Canadian Inuit dialect.").
number(s_book_14_0028, 10, 'inuit').
number(s_book_14_0028, 70, 'term').
number(s_book_14_0028, 40, 'snow').
number(s_book_14_0028, 50, 'canadian').
keywords(s_book_14_0028, ['across', 'alaskan', 'canadian', 'central', 'condition', 'descriptor', 'dialect', 'fifty', 'forty', 'inuit', 'order', 'recorded', 'seventy', 'siberian', 'survey', 'yupik']).
sentence(s_book_14_0029, 'book', 14, 29, 'unmarked', "These are not synonyms.").
sentence(s_book_14_0030, 'book', 14, 29, 'unmarked', "They mark whether a surface will bear weight, how it formed, and how it is likely to fail.").
hedged(s_book_14_0030).
sentence(s_book_14_0031, 'book', 14, 31, 'unmarked', "So the popular claim is wrong in form and there is something real underneath it.").
sentence(s_book_14_0032, 'book', 14, 31, 'unmarked', "Both halves have to be said, because saying only the first is now the more common error.").
sentence(s_book_14_0033, 'book', 14, 31, 'unmarked', "The example is set aside here not because the underlying observation is false but because the version in circulation cannot be defended, and because better evidence exists.").
certainty_word(s_book_14_0033, 'cannot be').
sentence(s_book_14_0034, 'book', 14, 34, 'unmarked', "The sea-ice vocabulary also points at a question that is better supported than the famous one, and it runs in the opposite direction: not whether words shape what speakers notice, but whether what speakers need to notice shapes their words.").
sentence(s_book_14_0035, 'book', 14, 34, 'unmarked', "A tempting extension is that landscapes multiply colour words — more greens where there is forest, more shades of sand in deserts.").
sentence(s_book_14_0036, 'book', 14, 34, 'unmarked', "The evidence points elsewhere.").
sentence(s_book_14_0037, 'book', 14, 34, 'unmarked', "Across the 110 languages of the World Color Survey, warm colours are communicated more precisely than cool ones, and in large collections of photographs the objects people single out are mostly warm-coloured while backgrounds — foliage, sky — are cool.").
number(s_book_14_0037, 110, 'language').
keywords(s_book_14_0037, ['across', 'background', 'collection', 'color', 'colour', 'communicated', 'foliage', 'language', 'large', 'mostly', 'object', 'people', 'photograph', 'precisely', 'single', 'survey', 'warm-coloured', 'while', 'world']).
sentence(s_book_14_0038, 'book', 14, 34, 'unmarked', "Colour words appear to accumulate where something has to be picked out against its surroundings, and how many a language has tracks how useful colour is to its speakers.").
hedged(s_book_14_0038).
sentence(s_book_14_0039, 'book', 14, 34, 'unmarked', "The Tsimane' of the Bolivian Amazon, surrounded by green, use colour words less than speakers in industrial societies, and use them more for artificially coloured objects than for natural ones.").
sentence(s_book_14_0040, 'book', 14, 34, 'unmarked', "Where a forest people's colour vocabulary is rich, it can turn out not to be about hue at all.").
sentence(s_book_14_0041, 'book', 14, 34, 'unmarked', "Among the Hanunóo of the Philippines, the term that covers green also means fresh and the term that covers red also means dried out, so a newly cut length of brown bamboo takes the \"green\" word.").
sentence(s_book_14_0042, 'book', 14, 36, 'unmarked', "What landscapes reliably multiply is vocabulary for the states of things that matter — the sea-ice terms above, and in deserts the kinds of ground, which geologists found useful enough to borrow: erg, hamada, sabkha, and wadi from Arabic, barchan from Kazakh, as glaciology took nunatak, pingo, and sastrugi from Greenlandic, Inuvialuktun, and Russian.").
sentence(s_book_14_0043, 'book', 14, 38, 'unmarked', "Colour has one geographic pattern of its own.").
sentence(s_book_14_0044, 'book', 14, 38, 'unmarked', "Languages spoken where sunlight carries more ultraviolet are more likely to lack a separate word for blue, covering it with their word for green or for dark.").
hedged(s_book_14_0044).
sentence(s_book_14_0045, 'book', 14, 38, 'unmarked', "One proposed explanation is physical — ultraviolet exposure yellows the lens of the eye and weakens the distinction.").
hedged(s_book_14_0045).
sentence(s_book_14_0046, 'book', 14, 38, 'unmarked', "An experiment comparing older and younger observers, whose lenses differ in exactly that way, found no difference in how they named blues and greens, which counts against the mechanism; a larger later analysis found ultraviolet exposure to be one influence among several, cultural complexity among them.").
sentence(s_book_14_0047, 'book', 14, 38, 'unmarked', "The pattern is real and its cause is still argued about.").
hedged(s_book_14_0047).
sentence(s_book_14_0048, 'book', 14, 38, 'unmarked', "What none of it licenses is a claim about any particular language's colour words read off from its landscape — the form of argument this section has just finished taking apart.").
sentence(s_book_14_0049, 'book', 14, 42, 'unmarked', "The better evidence comes from studies that test performance rather than count vocabulary.").
sentence(s_book_14_0050, 'book', 14, 44, 'unmarked', "Russian has no single word covering the range English calls blue; it obligatorily distinguishes a lighter category and a darker one.").
sentence(s_book_14_0051, 'book', 14, 44, 'unmarked', "In a 2007 study, Russian speakers were faster at telling two blues apart when the pair straddled that boundary than when both fell inside one category.").
