sentence(s_book_14_0066, 'book', 14, 58, 'unmarked', "The quantity experiments found something specific.").
sentence(s_book_14_0067, 'book', 14, 58, 'unmarked', "Speakers matched exact quantities accurately, including large ones, when the objects were in front of them.").
sentence(s_book_14_0068, 'book', 14, 58, 'unmarked', "Accuracy collapsed when the array was shown and then hidden before they were asked to reproduce it.").
sentence(s_book_14_0069, 'book', 14, 58, 'unmarked', "The researchers' reading is that the difficulty lies not in perceiving or matching exact quantity but in holding one in memory without a symbol for it.").
sentence(s_book_14_0070, 'book', 14, 60, 'unmarked', "That is a narrower claim than \"they cannot count,\" and a better one: number words look like a memory technology rather than a perceptual one.").
sentence(s_book_14_0071, 'book', 14, 62, 'unmarked', "A caution specific to this case.").
sentence(s_book_14_0072, 'book', 14, 62, 'unmarked', "The broader claims made about this language — particularly about grammatical recursion — are vigorously disputed, the researcher's own analysis changed substantially between publications, and very few linguists have field experience with it.").
hedged(s_book_14_0072).
sentence(s_book_14_0073, 'book', 14, 62, 'unmarked', "The quantity results are the best-supported part of a contested body of work, and the contested parts should not be borrowed to prop up the rest.").
hedged(s_book_14_0073).
sentence(s_book_14_0074, 'book', 14, 66, 'unmarked', "The strong version of this idea — that language determines thought, and that what a language lacks words for is unthinkable to its speakers — is not supported and is not claimed here.").
sentence(s_book_14_0075, 'book', 14, 66, 'unmarked', "Speakers readily perceive distinctions their language does not encode, borrow words, coin them, and describe things by circumlocution.").
sentence(s_book_14_0076, 'book', 14, 66, 'unmarked', "No one is trapped.").
sentence(s_book_14_0077, 'book', 14, 68, 'unmarked', "The supported version is narrower.").
sentence(s_book_14_0078, 'book', 14, 68, 'unmarked', "Habitually used linguistic categories appear to be recruited during cognitive tasks, and to affect speed and accuracy where the categories are relevant.").
hedged(s_book_14_0078).
sentence(s_book_14_0079, 'book', 14, 68, 'unmarked', "The effects are modest where they are found.").
sentence(s_book_14_0080, 'book', 14, 70, 'unmarked', "Replication in this area is genuinely uneven, and the colour case above is not an isolated wobble.").
sentence(s_book_14_0081, 'book', 14, 70, 'unmarked', "The grammatical-gender results have had a mixed record.").
sentence(s_book_14_0082, 'book', 14, 70, 'unmarked', "Effects that look robust in one language pair sometimes fail to appear in another.").
hedged(s_book_14_0082).
sentence(s_book_14_0083, 'book', 14, 70, 'unmarked', "The pattern is consistent with real effects that are small enough to be fragile, and it is also consistent with a literature that published its positive findings more readily than its negative ones.").
sentence(s_book_14_0084, 'book', 14, 70, 'unmarked', "Both readings remain available, and anyone claiming the question is settled in either direction is ahead of the evidence.").
sentence(s_book_14_0085, 'book', 14, 72, 'unmarked', "The direction of influence also runs both ways, which complicates any simple story.").
sentence(s_book_14_0086, 'book', 14, 72, 'unmarked', "A community that needs to distinguish ice conditions develops terms for them, and the terms then make the distinctions easier to notice and transmit.").
sentence(s_book_14_0087, 'book', 14, 72, 'unmarked', "Vocabulary is as much a record of what has mattered to a group as a cause of what its members attend to.").
sentence(s_book_14_0088, 'book', 14, 72, 'unmarked', "Asking which came first is usually the wrong question.").
sentence(s_book_14_0089, 'book', 14, 76, 'unmarked', "A word is an extreme act of compression.").
sentence(s_book_14_0090, 'book', 14, 76, 'unmarked', "A single short token stands for a category with indefinitely many members, no two identical, and makes that category available for combination with others.").
number(s_book_14_0090, 2, 'identical').
keywords(s_book_14_0090, ['available', 'category', 'combination', 'identical', 'indefinitely', 'member', 'short', 'single', 'stand', 'token']).
sentence(s_book_14_0091, 'book', 14, 78, 'unmarked', "The economy is enormous.").
sentence(s_book_14_0092, 'book', 14, 78, 'unmarked', "It is also lossy in exactly the way chapter 8 described for the genetic code and chapter 13 for perception.").
xref(s_book_14_0092, 8).
xref(s_book_14_0092, 13).
sentence(s_book_14_0093, 'book', 14, 78, 'unmarked', "Every category discards the differences among the things it covers.").
sentence(s_book_14_0094, 'book', 14, 78, 'unmarked', "Naming a thing makes it easier to think with and slightly harder to see freshly, because the name arrives with a set of expectations attached.").
sentence(s_book_14_0095, 'book', 14, 80, 'unmarked', "This is the same trade made at every level of this book, and language makes it visible because the units are inspectable.").
sentence(s_book_14_0096, 'book', 14, 80, 'unmarked', "The structure of a vocabulary is a record of which distinctions a community found worth the cost of maintaining — and, by omission, which it did not.").
sentence(s_book_14_0097, 'book', 14, 84, 'unmarked', "The consequence that matters most is not individual.").
sentence(s_book_14_0098, 'book', 14, 84, 'unmarked', "Language lets a representation formed in one mind be reconstructed in another, and reconstructed again after the first is gone.").
sentence(s_book_14_0099, 'book', 14, 86, 'unmarked', "Before that, everything an organism learned died with it, and each generation rediscovered the same things.").
sentence(s_book_14_0100, 'book', 14, 86, 'unmarked', "After it, knowledge accumulates: a practice can be transmitted, refined, and transmitted again, and no single person needs to hold the reasoning behind it or even to be capable of reconstructing it.").
sentence(s_book_14_0101, 'book', 14, 88, 'unmarked', "That is the condition for everything in chapter 15, which shows with a specific and consequential example that the mechanism can preserve knowledge nobody involved possesses.").
xref(s_book_14_0101, 15).
chapter('book', 15, "15-culture-economics-religion.md", "15. Culture, economics, land use, and religion").
sentence(s_book_15_0001, 'book', 15, 3, 'unmarked', "Culture can be understood as a system of information, practices, beliefs, technologies, and institutions transmitted between people and across generations.").
sentence(s_book_15_0002, 'book', 15, 5, 'unmarked', "Cultural elements vary, spread, persist, and disappear.").
sentence(s_book_15_0003, 'book', 15, 5, 'unmarked', "Their success depends on usefulness, familiarity, social status, emotional weight, institutional support, environmental conditions, and much else.").
sentence(s_book_15_0004, 'book', 15, 7, 'unmarked', "This creates parallels with biological evolution, with two differences large enough that the parallel has to be held loosely.").
number(s_book_15_0004, 2, 'difference').
keywords(s_book_15_0004, ['biological', 'create', 'difference', 'enough', 'evolution', 'large', 'loosely', 'parallel']).
sentence(s_book_15_0005, 'book', 15, 7, 'unmarked', "Cultural transmission is far faster, and it is not restricted to parent and offspring — a practice can pass between strangers, across populations, and backwards in age.").
sentence(s_book_15_0006, 'book', 15, 7, 'unmarked', "It is also far lower in fidelity.").
sentence(s_book_15_0007, 'book', 15, 7, 'unmarked', "A gene is copied as a sequence; a practice is reconstructed from observation by someone who may have understood it incompletely.").
hedged(s_book_15_0007).
sentence(s_book_15_0008, 'book', 15, 11, 'unmarked', "Ideas and practices spread through imitation, teaching, storytelling, social pressure, institutions, and communication networks.").
sentence(s_book_15_0009, 'book', 15, 13, 'unmarked', "Some persist because they solve practical problems.").
sentence(s_book_15_0010, 'book', 15, 13, 'unmarked', "Others persist because they reinforce identity, create cohesion, offer explanation, or become embedded in institutions that have their own reasons to continue.").
sentence(s_book_15_0011, 'book', 15, 15, 'unmarked', "Cultural systems experience bottlenecks and founder effects.").
sentence(s_book_15_0012, 'book', 15, 15, 'unmarked', "A small group may establish conventions that later become dominant for no reason except that they arrived first.").
hedged(s_book_15_0012).
sentence(s_book_15_0013, 'book', 15, 15, 'unmarked', "Isolation, migration, conflict, and social boundaries cause traditions to diverge.").
sentence(s_book_15_0014, 'book', 15, 17, 'unmarked', "The concept of a meme is one way of describing a unit of cultural transmission.").
sentence(s_book_15_0015, 'book', 15, 17, 'unmarked', "The word was coined in 1976 by the evolutionary biologist Richard Dawkins, in The Selfish Gene, on the model of gene, for a tune, a catchphrase or a fashion copied from one mind to another as a gene is copied from parent to offspring.").
year(s_book_15_0015, 1976).
keywords(s_book_15_0015, ['biologist', 'catchphrase', 'coined', 'copied', 'dawkin', 'evolutionary', 'fashion', 'model', 'offspring', 'parent', 'richard', 'selfish']).
sentence(s_book_15_0016, 'book', 15, 17, 'unmarked', "It is useful as shorthand and strained as a mechanism: cultural ideas are frequently not discrete, not copied with anything like genetic fidelity, and not separable from the people holding them.").
sentence(s_book_15_0017, 'book', 15, 21, 'unmarked', "The most important property of cultural transmission is one the biological analogy obscures entirely: a practice can carry knowledge that no one performing it possesses.").
sentence(s_book_15_0018, 'book', 15, 23, 'unmarked', "Maize was domesticated in Mesoamerica and became a staple.").
sentence(s_book_15_0019, 'book', 15, 23, 'unmarked', "It was also, from early on, processed in a particular way before eating: soaked and cooked in an alkaline solution of wood ash or slaked lime, then hulled and ground.").
sentence(s_book_15_0020, 'book', 15, 23, 'unmarked', "The technique is called nixtamalization.").
sentence(s_book_15_0021, 'book', 15, 25, 'unmarked', "How early is worth stating carefully, because the evidence comes in two kinds.").
number(s_book_15_0021, 2, 'kind').
keywords(s_book_15_0021, ['because', 'carefully', 'early', 'evidence', 'stating', 'worth']).
sentence(s_book_15_0022, 'book', 15, 25, 'unmarked', "Equipment associated with the process has been recovered from Guatemala's southern coast dating to roughly 1500–1200 BCE, which would put it well over three thousand years ago.").
year(s_book_15_0022, -1500).
year(s_book_15_0022, -1200).
number(s_book_15_0022, 3000, 'year').
keywords(s_book_15_0022, ['associated', 'coast', 'dating', 'equipment', 'guatemala', 'process', 'recovered', 'southern', 'thousand', 'three', 'would']).
sentence(s_book_15_0023, 'book', 15, 25, 'unmarked', "Direct identification of nixtamalized maize — microscopic residues that can only have come from the process itself — is much more recent, first reported from the Maya site of San Bartolo and dating to the Late and Terminal Classic, around the eighth and ninth centuries CE.").
sentence(s_book_15_0024, 'book', 15, 25, 'unmarked', "The practice is unquestionably ancient; the equipment is suggestive and the direct evidence is late, and the gap between them is a limit on how precisely the claim can be made.").
sentence(s_book_15_0025, 'book', 15, 27, 'unmarked', "The immediate reasons to do it are obvious to anyone cooking.").
sentence(s_book_15_0026, 'book', 15, 27, 'unmarked', "The hull comes away easily.").
sentence(s_book_15_0027, 'book', 15, 27, 'unmarked', "The grain grinds into a dough that holds together.").
sentence(s_book_15_0028, 'book', 15, 27, 'unmarked', "It tastes and smells better.").
sentence(s_book_15_0029, 'book', 15, 29, 'unmarked', "The reason that mattered was invisible, and worth getting right, because the standard explanation of it turns out to be wrong.").
sentence(s_book_15_0030, 'book', 15, 31, 'unmarked', "Maize is poor in niacin and poor in the amino acid tryptophan, which the human body converts into niacin.").
sentence(s_book_15_0031, 'book', 15, 31, 'unmarked', "Without enough of either, a population eating maize as a staple develops niacin deficiency.").
sentence(s_book_15_0032, 'book', 15, 31, 'unmarked', "That deficiency is pellagra: skin lesions, digestive failure, neurological deterioration, and eventually death.").
sentence(s_book_15_0033, 'book', 15, 33, 'unmarked', "Alkaline treatment prevents it.").
sentence(s_book_15_0034, 'book', 15, 33, 'unmarked', "The usual account of how is that maize contains niacin in a chemically bound form the gut cannot absorb, and that alkali breaks the bond and releases it.").
sentence(s_book_15_0035, 'book', 15, 33, 'unmarked', "That explanation is widely repeated and multiple experiments have failed to support it.").
sentence(s_book_15_0036, 'book', 15, 33, 'unmarked', "The better-supported mechanism is less tidy: the alkali makes maize protein more digestible, which makes its tryptophan absorbable, and the body makes its own niacin from there.").
sentence(s_book_15_0037, 'book', 15, 35, 'unmarked', "The correction is worth pausing on, given what this section is about.").
sentence(s_book_15_0038, 'book', 15, 35, 'unmarked', "The practice worked for more than a thousand years, and perhaps for over three thousand, without anyone knowing why.").
number(s_book_15_0038, 3000, 'anyone').
keywords(s_book_15_0038, ['anyone', 'knowing', 'perhap', 'practice', 'thousand', 'three', 'worked']).
hedged(s_book_15_0038).
sentence(s_book_15_0039, 'book', 15, 35, 'unmarked', "Then it was explained, and the explanation was wrong, and the wrong explanation is still the one in general circulation.").
sentence(s_book_15_0040, 'book', 15, 35, 'unmarked', "Knowledge embedded in a practice is hard to recover; knowledge embedded in a plausible story about a practice may be harder still.").
hedged(s_book_15_0040).
sentence(s_book_15_0041, 'book', 15, 37, 'unmarked', "Then maize crossed the Atlantic, and this is where the case becomes an experiment that nobody designed.").
sentence(s_book_15_0042, 'book', 15, 37, 'unmarked', "The crop spread rapidly through Europe, Africa, and later the American South, because it was productive and grew where other grains did not.").
sentence(s_book_15_0043, 'book', 15, 37, 'unmarked', "The processing technique did not travel with it.").
sentence(s_book_15_0044, 'book', 15, 37, 'unmarked', "There was no reason it would have — it looked like a culinary preference, not a nutritional requirement, and nobody on either side of the exchange knew otherwise.").
sentence(s_book_15_0045, 'book', 15, 39, 'unmarked', "Pellagra followed the crop.").
sentence(s_book_15_0046, 'book', 15, 39, 'unmarked', "Epidemics appeared in northern Italy, in Spain and southern France, in Egypt.").
sentence(s_book_15_0047, 'book', 15, 39, 'unmarked', "In the American South it became a mass health crisis: between 1906 and 1940 it affected more than three million people and killed over a hundred thousand.").
year(s_book_15_0047, 1906).
year(s_book_15_0047, 1940).
number(s_book_15_0047, 3e+06, 'people').
number(s_book_15_0047, 100000, 'none').
keywords(s_book_15_0047, ['affected', 'american', 'became', 'crisi', 'health', 'hundred', 'killed', 'million', 'people', 'south', 'thousand', 'three']).
sentence(s_book_15_0048, 'book', 15, 39, 'unmarked', "At its peak in the late 1920s it was among the leading causes of death in the region.").
sentence(s_book_15_0049, 'book', 15, 41, 'unmarked', "For years it was attributed to an infectious agent, and frequently to the character and habits of the people suffering from it — who were overwhelmingly poor, and whose poverty was the actual reason their diet had narrowed to cornmeal.").
sentence(s_book_15_0050, 'book', 15, 41, 'unmarked', "Dietary cause was established through deliberate investigation in the 1910s and 1920s, against considerable resistance, and the specific vitamin was identified in 1937.").
year(s_book_15_0050, 1937).
keywords(s_book_15_0050, ['against', 'cause', 'considerable', 'deliberate', 'dietary', 'established', 'identified', 'investigation', 'resistance', 'specific', 'vitamin']).
sentence(s_book_15_0051, 'book', 15, 43, 'unmarked', "Mesoamerican cooks had solved the problem centuries or millennia before anyone could state what the problem was, and could not have stated it themselves.").
sentence(s_book_15_0052, 'book', 15, 45, 'unmarked', "That is the thing worth sitting with.").
sentence(s_book_15_0053, 'book', 15, 45, 'unmarked', "The knowledge was real, it was accurate, and it was load-bearing — and it did not exist in anyone's head.").
sentence(s_book_15_0054, 'book', 15, 45, 'unmarked', "It existed in a sequence of actions passed from one person to the next with the instruction that this is how maize is prepared.").
sentence(s_book_15_0055, 'book', 15, 45, 'unmarked', "The explanation was not merely absent; it was unavailable in principle, since nothing in the available conceptual vocabulary could have contained it.").
sentence(s_book_15_0056, 'book', 15, 47, 'unmarked', "A practice is a compressed representation of a relationship with the world.").
sentence(s_book_15_0057, 'book', 15, 47, 'unmarked', "It is lossy in a specific and dangerous way: it discards the reason.").
sentence(s_book_15_0058, 'book', 15, 47, 'unmarked', "That makes it cheap to transmit, since a child can learn it by watching and needs to understand nothing.").
sentence(s_book_15_0059, 'book', 15, 47, 'unmarked', "It also makes it fragile, because a practice separated from its reason cannot defend itself.").
sentence(s_book_15_0060, 'book', 15, 47, 'unmarked', "Anyone can see that a step is laborious.").
sentence(s_book_15_0061, 'book', 15, 47, 'unmarked', "Nobody can see what it is for.").
sentence(s_book_15_0062, 'book', 15, 49, 'unmarked', "This is also a corrective to a familiar condescension.").
sentence(s_book_15_0063, 'book', 15, 49, 'unmarked', "\"They did not know why\" is often taken to mean \"they did not know.").
sentence(s_book_15_0064, 'book', 15, 49, 'unmarked', "The maize case shows these are different claims, and that the second can be false while the first is true.").
sentence(s_book_15_0065, 'book', 15, 53, 'unmarked', "Economic arrangements develop through the interaction of resources, technologies, institutions, incentives, and behaviour.").
sentence(s_book_15_0066, 'book', 15, 55, 'unmarked', "Practices suited to particular environmental and material conditions spread.").
sentence(s_book_15_0067, 'book', 15, 55, 'unmarked', "Others become unsustainable and disappear.").
sentence(s_book_15_0068, 'book', 15, 55, 'unmarked', "Agriculture, trade, settlement patterns, property systems, and technologies all shape how land is used and resources organized.").
sentence(s_book_15_0069, 'book', 15, 57, 'unmarked', "The terms economic memetics and land-use evolution are used here as ways of examining persistence and change in these systems.").
sentence(s_book_15_0070, 'book', 15, 57, 'unmarked', "Neither implies that economies or land-use patterns evolve by the mechanisms that operate on organisms.").
sentence(s_book_15_0071, 'book', 15, 57, 'unmarked', "The resemblance is in the shape of the process — variation, differential persistence, transmission — and not in the machinery.").
sentence(s_book_15_0072, 'book', 15, 59, 'unmarked', "One caution carries over from the previous section.").
sentence(s_book_15_0073, 'book', 15, 59, 'unmarked', "Practices that persist are not thereby good, and they are not thereby understood by those maintaining them.").
sentence(s_book_15_0074, 'book', 15, 59, 'unmarked', "Nixtamalization persisted and was beneficial.").
sentence(s_book_15_0075, 'book', 15, 59, 'unmarked', "Other practices persist because they benefit whoever is positioned to maintain them, because nobody has examined them, or because the cost of changing exceeds the cost of continuing.").
sentence(s_book_15_0076, 'book', 15, 59, 'unmarked', "Persistence indicates that something has been transmitted.").
sentence(s_book_15_0077, 'book', 15, 59, 'unmarked', "It indicates nothing about why.").
sentence(s_book_15_0078, 'book', 15, 63, 'unmarked', "Religion can be examined as a cultural system combining explanation, narrative, ritual, symbol, moral framework, and institution.").
sentence(s_book_15_0079, 'book', 15, 63, 'unmarked', "What follows looks at how such systems are organized and transmitted.").
sentence(s_book_15_0080, 'book', 15, 63, 'unmarked', "It does not assess whether any of them is true, and nothing in it should be read as doing so.").
sentence(s_book_15_0081, 'book', 15, 65, 'unmarked', "Human beings have always faced uncertainty about death, illness, weather, hunger, conflict, disaster, and origins — questions that are urgent, that arrive without warning, and that in most times and places could not be answered by investigation.").
certainty_word(s_book_15_0081, 'always').
sentence(s_book_15_0082, 'book', 15, 67, 'unmarked', "Shared narratives do real work under those conditions.").
sentence(s_book_15_0083, 'book', 15, 67, 'unmarked', "They make events interpretable, provide a common frame in which a community can coordinate, carry moral expectation in memorable form, and offer a way of approaching mortality and suffering that can be held collectively rather than alone.").
sentence(s_book_15_0084, 'book', 15, 67, 'unmarked', "Ritual and institution transmit them across generations with far more stability than individual memory allows.").
sentence(s_book_15_0085, 'book', 15, 69, 'unmarked', "Religion can therefore be examined through several overlapping functions:").
sentence(s_book_15_0086, 'book', 15, 71, 'unmarked', "- Providing explanations for uncertain or difficult events. - Establishing shared narratives and identities. - Supporting cohesion and collective action. - Transmitting moral expectations and social rules. - Offering ways to approach mortality, suffering, and purpose. - Creating institutions and traditions that persist over time.").
sentence(s_book_15_0087, 'book', 15, 78, 'unmarked', "One experimental finding is worth bringing in here, because it is more specific than the functional list and does not depend on it.").
sentence(s_book_15_0088, 'book', 15, 78, 'unmarked', "Researchers have studied cultural transmission directly by passing material along a chain of people and measuring what survives each retelling — the method chapter 17 returns to.").
xref(s_book_15_0088, 17).
sentence(s_book_15_0089, 'book', 15, 78, 'unmarked', "In such chains, content that is mildly counterintuitive survives better than content that is either entirely ordinary or wildly strange.").
sentence(s_book_15_0090, 'book', 15, 78, 'unmarked', "A story in which almost everything behaves normally and one thing does not is retained and retransmitted more faithfully than a story in which nothing is unusual, or in which everything is.").
sentence(s_book_15_0091, 'book', 15, 80, 'unmarked', "That is a narrow and testable claim about memory and transmission, and it has an obvious bearing on the shape of religious narrative across unrelated traditions — which tends strongly towards the mostly ordinary world containing a few specific exceptions, rather than towards the uniformly strange.").
sentence(s_book_15_0092, 'book', 15, 80, 'unmarked', "It says nothing whatever about whether any such narrative is true.").
sentence(s_book_15_0093, 'book', 15, 80, 'unmarked', "It says something about which narratives, true or false, are likely to still be in circulation.").
hedged(s_book_15_0093).
sentence(s_book_15_0094, 'book', 15, 82, 'unmarked', "Two things need saying plainly about the list of functions, because lists of this kind are easy to misread.").
number(s_book_15_0094, 2, 'thing').
keywords(s_book_15_0094, ['because', 'function', 'misread', 'plainly', 'saying', 'thing']).
sentence(s_book_15_0095, 'book', 15, 84, 'unmarked', "The first is that identifying a function is not an explanation of origin, and still less a debunking.").
sentence(s_book_15_0096, 'book', 15, 84, 'unmarked', "The observation that a practice does something useful is compatible with its being true, with its being false, and with the question not being the kind that admits an answer.").
sentence(s_book_15_0097, 'book', 15, 84, 'unmarked', "Many true things are also useful; usefulness is evidence of neither truth nor falsity.").
sentence(s_book_15_0098, 'book', 15, 84, 'unmarked', "The functional analysis here and the question of what is actually the case are different inquiries, and running them together is a mistake regardless of which direction it is run in.").
sentence(s_book_15_0099, 'book', 15, 86, 'unmarked', "The second is that religious systems are enormously diverse and have no single origin or single function.").
sentence(s_book_15_0100, 'book', 15, 86, 'unmarked', "Treating them as one thing with one explanation would be the same error the rest of this book warns against — noticing a similarity and assuming a shared mechanism.").
sentence(s_book_15_0101, 'book', 15, 90, 'unmarked', "One further observation, offered carefully.").
sentence(s_book_15_0102, 'book', 15, 92, 'unmarked', "Different explanatory frameworks develop their own vocabularies, and vocabularies that grew up answering different questions are rarely interchangeable.").
sentence(s_book_15_0103, 'book', 15, 92, 'unmarked', "Two people may be addressing genuinely overlapping concerns — why there is suffering, what obligations people have to one another, what happens at the end — in terms that do not map onto each other at any point.").
number(s_book_15_0103, 2, 'people').
keywords(s_book_15_0103, ['addressing', 'concern', 'genuinely', 'happen', 'obligation', 'overlapping', 'people', 'point', 'suffering']).
hedged(s_book_15_0103).
sentence(s_book_15_0104, 'book', 15, 92, 'unmarked', "Mutual unintelligibility is easy to mistake for fundamental disagreement, and conversations frequently fail at the translation step before reaching the substance.").
sentence(s_book_15_0105, 'book', 15, 94, 'unmarked', "This observation has a limit that matters more than the observation does.").
sentence(s_book_15_0106, 'book', 15, 94, 'unmarked', "It does not follow that all disagreements are merely verbal, that every framework is equally correct, or that apparent conflicts dissolve on inspection.").
sentence(s_book_15_0107, 'book', 15, 94, 'unmarked', "Some disagreements are real, some claims are about matters of fact, and some factual claims are wrong.").
sentence(s_book_15_0108, 'book', 15, 94, 'unmarked', "A framework can be internally coherent, socially valuable, deeply meaningful, and mistaken about something checkable, and noting the translation problem does not dissolve any of that.").
sentence(s_book_15_0109, 'book', 15, 96, 'unmarked', "What the observation is good for is narrow: it suggests that the first question in a disagreement should be whether both parties are using their words the same way, and that the answer is more often no than it appears.").
hedged(s_book_15_0109).
sentence(s_book_15_0110, 'book', 15, 98, 'unmarked', "The interest here is in religion as a form of cultural organization and transmission.").
sentence(s_book_15_0111, 'book', 15, 98, 'unmarked', "The theological and philosophical questions are left open, for the straightforward reason that nothing in this framework is equipped to settle them.").
chapter('book', 16, "16-the-recurring-architecture.md", "16. The recurring architecture").
sentence(s_book_16_0001, 'book', 16, 3, 'unmarked', "Sixteen chapters in, the shape of the argument can be set out in one place.").
number(s_book_16_0001, 16, 'chapter').
keywords(s_book_16_0001, ['argument', 'chapter', 'place', 'shape', 'sixteen']).
sentence(s_book_16_0002, 'book', 16, 7, 'unmarked', "Physical conditions → chemical networks → compartments → biological systems → metacompartmentalization → nervous systems → language → culture → social and economic systems").
sentence(s_book_16_0003, 'book', 16, 9, 'unmarked', "This is not a ladder and not a predetermined path.").
sentence(s_book_16_0004, 'book', 16, 9, 'unmarked', "Each level contains its own feedback, constraints, and forms of selection; levels interact in both directions; and nothing required the sequence to continue past any particular point.").
sentence(s_book_16_0005, 'book', 16, 9, 'unmarked', "It is an ordering of what became possible, not of what had to happen.").
sentence(s_book_16_0006, 'book', 16, 25, 'unmarked', "The table compares organizational patterns.").
sentence(s_book_16_0007, 'book', 16, 25, 'unmarked', "It does not claim the rows share a process, and chapter 2's version of this table — which takes a single term and shows the machinery differing underneath it — is the corrective that should be read alongside it.").
xref(s_book_16_0007, 2).
sentence(s_book_16_0008, 'book', 16, 29, 'unmarked', "This is the chapter's real work, because the progression above is the book's central claim and it is not uniformly supported.").
sentence(s_book_16_0009, 'book', 16, 31, 'unmarked', "Mechanically continuous, from physics to compartments — in principle.").
sentence(s_book_16_0010, 'book', 16, 31, 'unmarked', "Chemistry is physics.").
sentence(s_book_16_0011, 'book', 16, 31, 'unmarked', "Self-sustaining reaction networks are chemistry: chapter 4 shows autocatalysis demonstrated, and small collectively self-sustaining networks built in the laboratory.").
xref(s_book_16_0011, 4).
sentence(s_book_16_0012, 'book', 16, 31, 'unmarked', "Whether prebiotic chemistry was rich enough to produce them unaided is, as chapter 4 says, not settled.").
xref(s_book_16_0012, 4).
sentence(s_book_16_0013, 'book', 16, 31, 'unmarked', "Compartments form unaided from amphiphiles, and chapter 5's osmotic competition between vesicles is not an analogy to selection — it is differential persistence under constraint, operating on compartments, observed in a laboratory.").
xref(s_book_16_0013, 5).
sentence(s_book_16_0014, 'book', 16, 31, 'unmarked', "Nothing in this stretch requires a new principle at any step; what remains open is whether early Earth supplied the conditions, not whether the chemistry is possible.").
sentence(s_book_16_0015, 'book', 16, 33, 'unmarked', "A genuine break at heredity.").
sentence(s_book_16_0016, 'book', 16, 33, 'unmarked', "How a chemical system first came to copy a pattern reliably enough for differences to accumulate across generations is not known.").
sentence(s_book_16_0017, 'book', 16, 33, 'unmarked', "Chapters 8 and 17 say so; chapter 12 argues the absence of a single threshold moment is a feature of the category rather than a gap, which is true and does not fill this particular gap.").
xref(s_book_16_0017, 8).
xref(s_book_16_0017, 17).
xref(s_book_16_0017, 12).
sentence(s_book_16_0018, 'book', 16, 33, 'unmarked', "It remains the one place in the progression where the account cannot describe the transition.").
sentence(s_book_16_0019, 'book', 16, 35, 'unmarked', "Mechanically continuous again, from heredity through cognition.").
sentence(s_book_16_0020, 'book', 16, 35, 'unmarked', "Once templates are copied with variation in a population, standard evolutionary biology carries the account through multicellularity, specialization, nervous systems, and the capacity to build and use internal models.").
sentence(s_book_16_0021, 'book', 16, 35, 'unmarked', "This stretch is the best-supported part of the book and the least original to it.").
sentence(s_book_16_0022, 'book', 16, 37, 'unmarked', "Weaker at language.").
sentence(s_book_16_0023, 'book', 16, 37, 'unmarked', "That representation became externally transmissible is clear.").
sentence(s_book_16_0024, 'book', 16, 37, 'unmarked', "How, and in what stages, is not, and this book says little about it that would survive a linguist's scrutiny.").
sentence(s_book_16_0025, 'book', 16, 39, 'unmarked', "Shared vocabulary rather than shared mechanism, above language.").
sentence(s_book_16_0026, 'book', 16, 39, 'unmarked', "Cultural selection, economic persistence, and religious transmission are described here with the same terms used for chemistry and biology, and the machinery is unrelated.").
sentence(s_book_16_0027, 'book', 16, 39, 'unmarked', "Chapter 2's table makes this explicit for \"selection.").
xref(s_book_16_0027, 2).
sentence(s_book_16_0028, 'book', 16, 39, 'unmarked', "Chapter 15 makes it explicit for transmission fidelity.").
xref(s_book_16_0028, 15).
sentence(s_book_16_0029, 'book', 16, 39, 'unmarked', "The terms are useful for asking the same question of different systems.").
sentence(s_book_16_0030, 'book', 16, 39, 'unmarked', "They are not evidence that the systems answer it the same way.").
sentence(s_book_16_0031, 'book', 16, 41, 'unmarked', "An honest reader should take the progression as firm in principle in its lower half, broken at one specific joint, firm again through biology, and increasingly a matter of description rather than mechanism towards the top.").
sentence(s_book_16_0032, 'book', 16, 45, 'unmarked', "Four things appear at nearly every level, and unlike the vocabulary they are structural rather than terminological.").
number(s_book_16_0032, 4, 'thing').
keywords(s_book_16_0032, ['appear', 'level', 'rather', 'structural', 'terminological', 'thing', 'unlike', 'vocabulary']).
hedged(s_book_16_0032).
sentence(s_book_16_0033, 'book', 16, 47, 'unmarked', "Membrane, cell wall, organism, group, institution.").
sentence(s_book_16_0034, 'book', 16, 47, 'unmarked', "Something distinguishes inside from outside, and the distinction is what makes a unit comparable to other units.").
sentence(s_book_16_0035, 'book', 16, 49, 'unmarked', "Nothing on the list maintains itself without energy or material flowing through it.").
sentence(s_book_16_0036, 'book', 16, 49, 'unmarked', "Stop the flow and the organization does not freeze — it disperses.").
sentence(s_book_16_0037, 'book', 16, 49, 'unmarked', "This is as true of an institution as of a convection cell.").
sentence(s_book_16_0038, 'book', 16, 51, 'unmarked', "Variants exist and do not last equally.").
sentence(s_book_16_0039, 'book', 16, 51, 'unmarked', "This requires no copying, no competition in any intentional sense, and no population — chapter 5's vesicles demonstrate it with osmotic pressure alone.").
xref(s_book_16_0039, 5).
sentence(s_book_16_0040, 'book', 16, 53, 'unmarked', "Something carried forward.").
sentence(s_book_16_0041, 'book', 16, 53, 'unmarked', "A stable structure, a copied template, a memory, a practice.").
sentence(s_book_16_0042, 'book', 16, 53, 'unmarked', "Without it each cycle starts over and nothing accumulates, which is chapter 11's point.").
xref(s_book_16_0042, 11).
sentence(s_book_16_0043, 'book', 16, 55, 'unmarked', "And a fifth that is easy to miss: every level has to suppress the one below it.").
sentence(s_book_16_0044, 'book', 16, 55, 'unmarked', "Chapter 6 made this concrete with cancer — a multicellular organism persists only while it holds down the replication that many of its component cells remain capable of.").
xref(s_book_16_0044, 6).
sentence(s_book_16_0045, 'book', 16, 55, 'unmarked', "The same tension recurs with selfish genetic elements inside genomes and with reproductive policing inside colonies.").
sentence(s_book_16_0046, 'book', 16, 55, 'unmarked', "Organization at a higher level is not a state that was reached.").
sentence(s_book_16_0047, 'book', 16, 55, 'unmarked', "It is a cost paid continuously against a lower level that has not forgotten how to act for itself.").
sentence(s_book_16_0048, 'book', 16, 59, 'unmarked', "The progression above describes organization arising by nesting — components incorporated into larger units.").
sentence(s_book_16_0049, 'book', 16, 61, 'unmarked', "The human microbiome shows a second route.").
sentence(s_book_16_0050, 'book', 16, 61, 'unmarked', "A host and its microbial communities are not nested in that sense; they remain distinct organisms with separate evolutionary interests, exchanging resources and shaping one another's environments.").
sentence(s_book_16_0051, 'book', 16, 61, 'unmarked', "System-level properties arise anyway, from the relationships rather than from incorporation.").
sentence(s_book_16_0052, 'book', 16, 63, 'unmarked', "Endosymbiosis is what happens when the second route runs to completion and becomes the first.").
sentence(s_book_16_0053, 'book', 16, 63, 'unmarked', "A free-living bacterium associated with a host, then depended on it, then handed over its genome.").
sentence(s_book_16_0054, 'book', 16, 63, 'unmarked', "The two routes are the same process at different stages, and most relationships never finish the journey.").
number(s_book_16_0054, 2, 'route').
keywords(s_book_16_0054, ['different', 'finish', 'journey', 'never', 'process', 'relationship', 'route', 'stage']).
certainty_word(s_book_16_0054, 'never').
sentence(s_book_16_0055, 'book', 16, 65, 'unmarked', "That matters for reading the progression correctly.").
sentence(s_book_16_0056, 'book', 16, 65, 'unmarked', "Complexity does not only accumulate by things becoming parts of larger things.").
sentence(s_book_16_0057, 'book', 16, 65, 'unmarked', "It also accumulates between things that stay separate — and much of what any organism does is performed by organisms it is not.").
heading_count('book', 16, 57, "Two routes, not one", 2, 0).
chapter('book', 17, "17-distinctions-and-limitations.md", "17. Important distinctions and limitations").
sentence(s_book_17_0001, 'book', 17, 3, 'unmarked', "This framework depends on analogy, and analogy must not be confused with mechanism.").
sentence(s_book_17_0002, 'book', 17, 5, 'unmarked', "A chemical reaction network, a biological ecosystem, a brain, a language, and an economy can all display variation, feedback, persistence, and emergent properties.").
sentence(s_book_17_0003, 'book', 17, 5, 'unmarked', "That does not mean they are governed by identical processes.").
sentence(s_book_17_0004, 'book', 17, 5, 'unmarked', "It may mean no more than that these are the terms available for describing anything that changes.").
hedged(s_book_17_0004).
sentence(s_book_17_0005, 'book', 17, 7, 'unmarked', "Several distinctions should remain clear:").
sentence(s_book_17_0006, 'book', 17, 9, 'unmarked', "- Physical stability is not biological fitness. - Chemical autocatalysis is not biological reproduction. - Genetic inheritance is not cultural transmission. - Neural representation is not symbolic language. - Cultural persistence is not genetic selection. - Specialization does not always increase stability. - Complexity does not necessarily increase over time. - Emergence does not imply intention or a predetermined direction.").
certainty_word(s_book_17_0006, 'always').
sentence(s_book_17_0007, 'book', 17, 18, 'unmarked', "Living systems also do not violate the second law of thermodynamics.").
sentence(s_book_17_0008, 'book', 17, 18, 'unmarked', "They maintain local organization by using energy and exchanging matter with their surroundings, while producing entropy in the larger environment.").
sentence(s_book_17_0009, 'book', 17, 18, 'unmarked', "Local order is compatible with, and in fact paid for by, a larger increase in disorder.").
sentence(s_book_17_0010, 'book', 17, 18, 'unmarked', "Nothing in this book requires an exception to physics, and any argument that appeared to grant one would be an error in the argument.").
sentence(s_book_17_0011, 'book', 17, 22, 'unmarked', "An account that only listed its minor caveats would not be worth much.").
sentence(s_book_17_0012, 'book', 17, 22, 'unmarked', "The serious objection to this framework is the following, stated at full strength:").
sentence(s_book_17_0013, 'book', 17, 24, 'unmarked', "It is an interesting unifying narrative, and too broad to count as a strong theory.").
sentence(s_book_17_0014, 'book', 17, 24, 'unmarked', "It connects many domains by analogy without isolating sharp, testable mechanisms that would let it be decisively right or wrong.").
sentence(s_book_17_0015, 'book', 17, 24, 'unmarked', "It risks explaining too much with the same pattern.").
sentence(s_book_17_0016, 'book', 17, 24, 'unmarked', "Its key terms — search space, selection, compression — need operational definitions before they can do work.").
sentence(s_book_17_0017, 'book', 17, 24, 'unmarked', "And it generates no predictions that differ from standard accounts in any of the fields it spans.").
sentence(s_book_17_0018, 'book', 17, 26, 'unmarked', "Each clause is fair, and they are not equally serious.").
sentence(s_book_17_0019, 'book', 17, 28, 'unmarked', "This is partly answered by discipline.").
sentence(s_book_17_0020, 'book', 17, 28, 'unmarked', "Every comparison in this book is supposed to be labelled as a comparison, and chapters 9, 10, and 14 go out of their way to show where surface similarity hides unrelated mechanisms.").
number(s_book_17_0020, 14, 'go').
keywords(s_book_17_0020, ['chapter', 'comparison', 'labelled', 'mechanism', 'similarity', 'supposed', 'surface', 'unrelated']).
xref(s_book_17_0020, 9).
xref(s_book_17_0020, 10).
sentence(s_book_17_0021, 'book', 17, 28, 'unmarked', "Partly answered is not answered.").
sentence(s_book_17_0022, 'book', 17, 28, 'unmarked', "Labelling an analogy does not convert it into an explanation, and a book full of correctly labelled analogies is still a book full of analogies.").
sentence(s_book_17_0023, 'book', 17, 30, 'unmarked', "On explaining too much.").
sentence(s_book_17_0024, 'book', 17, 30, 'unmarked', "This is the serious one.").
sentence(s_book_17_0025, 'book', 17, 30, 'unmarked', "A pattern that can be found everywhere constrains nothing, and a framework that cannot be embarrassed by any observation is not telling anyone anything.").
certainty_word(s_book_17_0025, 'cannot be').
sentence(s_book_17_0026, 'book', 17, 30, 'unmarked', "Worse, the capacity to find such patterns is exactly the faculty chapter 13 describes as unreliable and the Preface describes the author exercising at unusual intensity.").
xref(s_book_17_0026, 13).
sentence(s_book_17_0027, 'book', 17, 30, 'unmarked', "The person most likely to see variation-selection-retention in every system is the person predisposed to see it, and no amount of care fully corrects for that.").
hedged(s_book_17_0027).
sentence(s_book_17_0028, 'book', 17, 32, 'unmarked', "The honest position is that some of this framework's apparent reach is real continuity and some is the vocabulary being elastic enough to wrap around anything.").
sentence(s_book_17_0029, 'book', 17, 32, 'unmarked', "Which parts are which is not fully settled here.").
sentence(s_book_17_0030, 'book', 17, 34, 'unmarked', "On operational definitions.").
sentence(s_book_17_0031, 'book', 17, 34, 'unmarked', "Fair and largely unmet.").
sentence(s_book_17_0032, 'book', 17, 34, 'unmarked', "\"Compression\" is used in this book for the genetic code's error tolerance, for perceptual abstraction, for the meaning of a word, and for a cooking technique that carries nutritional knowledge.").
sentence(s_book_17_0033, 'book', 17, 34, 'unmarked', "These have something in common.").
sentence(s_book_17_0034, 'book', 17, 34, 'unmarked', "Whether that something is a measurable quantity or a family resemblance is not established, and the book does not establish it.").
sentence(s_book_17_0035, 'book', 17, 36, 'unmarked', "Nothing here predicts an observation that standard accounts in chemistry, biology, cognitive science, or anthropology would not also predict.").
sentence(s_book_17_0036, 'book', 17, 36, 'unmarked', "A framework earns its place by forbidding something, and this one currently forbids very little.").
sentence(s_book_17_0037, 'book', 17, 40, 'unmarked', "The correct response to the last objection is not a defence but a set of claims specific enough to fail.").
sentence(s_book_17_0038, 'book', 17, 40, 'unmarked', "An earlier draft of this chapter offered three, each tied to a particular chapter, and presented them as tests someone might run.").
number(s_book_17_0038, 3, 'tied').
