keywords(s_book_17_0040, ['already', 'anything', 'describe', 'investigated', 'people', 'themselve', 'three', 'working', 'would']).
sentence(s_book_17_0041, 'book', 17, 44, 'unmarked', "Environmental cycling increases the retention of prebiotic chemistry.").
sentence(s_book_17_0042, 'book', 17, 44, 'unmarked', "Chapter 3 argues that cycle frequency matters more than elapsed time.").
xref(s_book_17_0042, 3).
sentence(s_book_17_0043, 'book', 17, 44, 'unmarked', "This has been tested extensively.").
sentence(s_book_17_0044, 'book', 17, 44, 'unmarked', "Repeated wet–dry cycling drives nucleotides to polymerize into long chains without chemical activation, in conditions resembling those at volcanic hot springs; material that fails to incorporate is washed away while polymers remain, so each cycle both builds and selects.").
sentence(s_book_17_0045, 'book', 17, 44, 'unmarked', "The effect is well enough established that it is now a standard experimental setup rather than a question.").
