xref(s_book_17_0052, 15).
sentence(s_book_17_0053, 'book', 17, 48, 'unmarked', "Transmission-chain experiments — passing material along a line of participants and measuring what degrades — have identified several specific biases.").
sentence(s_book_17_0054, 'book', 17, 48, 'unmarked', "Social content survives better than non-social content.").
sentence(s_book_17_0055, 'book', 17, 48, 'unmarked', "So does content that is mildly counterintuitive.").
sentence(s_book_17_0056, 'book', 17, 48, 'unmarked', "Material tends to lose detail and drift towards what the receiver already expected.").
sentence(s_book_17_0057, 'book', 17, 48, 'unmarked', "Claim survives, and the real findings are sharper than the prediction.").
sentence(s_book_17_0058, 'book', 17, 50, 'unmarked', "So the framework's three checkable claims were checked, and all three held.").
