sentence(s_book_17_0060, 'book', 17, 52, 'unmarked', "These predictions were not derived from the framework and then tested.").
sentence(s_book_17_0061, 'book', 17, 52, 'unmarked', "They were assembled by someone who had read around these fields, from directions the evidence was already pointing.").
sentence(s_book_17_0062, 'book', 17, 52, 'unmarked', "A prediction reverse-engineered from results already in circulation is not a prediction.").
