sentence(s_bookhs_15_0045, 'book-hs', 15, 37, 'unmarked', "And the wrong explanation is still the one in general circulation, including in my own head until recently.").
sentence(s_bookhs_15_0046, 'book-hs', 15, 39, 'unmarked', "Knowledge hidden inside a practice is hard to dig out.").
sentence(s_bookhs_15_0047, 'book-hs', 15, 39, 'unmarked', "Knowledge hidden inside a plausible story about a practice may be harder, because a plausible story stops people looking.").
