sentence(s_bookhs_15_0065, 'book-hs', 15, 61, 'unmarked', "It was accurate.").
sentence(s_bookhs_15_0066, 'book-hs', 15, 61, 'unmarked', "People's lives depended on it.").
sentence(s_bookhs_15_0067, 'book-hs', 15, 61, 'unmarked', "And it did not exist in anybody's head.").
sentence(s_bookhs_15_0068, 'book-hs', 15, 63, 'unmarked', "It existed in a sequence of actions, passed from one person to the next, with no explanation attached beyond this is how you make corn.").
sentence(s_bookhs_15_0069, 'book-hs', 15, 65, 'unmarked', "A practice is a compressed version of a relationship with the world — and it's lossy in a specific, dangerous way.").
sentence(s_bookhs_15_0070, 'book-hs', 15, 65, 'unmarked', "It throws away the reason.").
sentence(s_bookhs_15_0071, 'book-hs', 15, 67, 'unmarked', "That makes it cheap to transmit: a child can learn it by watching and needs to understand nothing.").
sentence(s_bookhs_15_0072, 'book-hs', 15, 67, 'unmarked', "It also makes it fragile, because a practice separated from its reason can't defend itself.").
