sentence(s_bookhs_15_0074, 'book-hs', 15, 67, 'unmarked', "Nobody can see what it's for.").
sentence(s_bookhs_15_0075, 'book-hs', 15, 69, 'unmarked', "And it's a correction to a common bit of condescension.").
sentence(s_bookhs_15_0076, 'book-hs', 15, 69, 'unmarked', "\"They didn't know why\" gets heard as \"they didn't know.").
sentence(s_bookhs_15_0077, 'book-hs', 15, 69, 'unmarked', "The corn case shows those are different claims, and the second one can be false while the first is true.").
sentence(s_bookhs_15_0078, 'book-hs', 15, 73, 'unmarked', "Religion can be looked at the same way — as a system of explanations, stories, rituals, and institutions that get passed between people and across generations.").
sentence(s_bookhs_15_0079, 'book-hs', 15, 75, 'unmarked', "I want to be clear about what this section does.").
