sentence(s_bookhs_15_0081, 'book-hs', 15, 75, 'unmarked', "It does not assess whether any of them is true, and nothing here should be read that way.").
sentence(s_bookhs_15_0082, 'book-hs', 15, 77, 'unmarked', "People have always faced things that were urgent, arrived without warning, and could not be investigated: death, illness, weather, famine, disaster, where everything came from.").
certainty_word(s_bookhs_15_0082, 'always').
sentence(s_bookhs_15_0083, 'book-hs', 15, 77, 'unmarked', "Shared stories do real work under those conditions.").
sentence(s_bookhs_15_0084, 'book-hs', 15, 77, 'unmarked', "They make events interpretable.").
sentence(s_bookhs_15_0085, 'book-hs', 15, 77, 'unmarked', "They give a community a common frame to coordinate around.").
sentence(s_bookhs_15_0086, 'book-hs', 15, 77, 'unmarked', "They carry moral expectations in a form people remember.").
sentence(s_bookhs_15_0087, 'book-hs', 15, 77, 'unmarked', "They offer a way of facing death that can be held together rather than alone.").
sentence(s_bookhs_15_0088, 'book-hs', 15, 79, 'unmarked', "Here's one specific experimental finding, because it's narrow and checkable.").
sentence(s_bookhs_15_0089, 'book-hs', 15, 81, 'unmarked', "When you pass a story along a chain of people — each one retelling it to the next — content that's mildly strange survives better than content that's either completely ordinary or completely bizarre.").
sentence(s_bookhs_15_0090, 'book-hs', 15, 81, 'unmarked', "A story where almost everything behaves normally and one thing doesn't gets retold more faithfully than one where nothing is odd, or where everything is.").
sentence(s_bookhs_15_0091, 'book-hs', 15, 83, 'unmarked', "That has an obvious bearing on the shape religious stories tend to take across completely unrelated traditions: a mostly ordinary world containing a few specific exceptions.").
sentence(s_bookhs_15_0092, 'book-hs', 15, 85, 'unmarked', "It says nothing at all about whether any of them is true.").
sentence(s_bookhs_15_0093, 'book-hs', 15, 85, 'unmarked', "It says something about which stories, true or false, are likely to still be around.").
hedged(s_bookhs_15_0093).
sentence(s_bookhs_15_0094, 'book-hs', 15, 87, 'unmarked', "And that distinction needs stating plainly, because it's easy to misread.").
sentence(s_bookhs_15_0095, 'book-hs', 15, 87, 'unmarked', "Finding a function is not an explanation of origin and it is not a debunking.").
sentence(s_bookhs_15_0096, 'book-hs', 15, 87, 'unmarked', "That something is useful is compatible with it being true, with it being false, and with the question being the kind that doesn't get settled this way.").
sentence(s_bookhs_15_0097, 'book-hs', 15, 87, 'unmarked', "Plenty of true things are also useful.").
sentence(s_bookhs_15_0098, 'book-hs', 15, 87, 'unmarked', "Usefulness is evidence of neither.").
sentence(s_bookhs_15_0099, 'book-hs', 15, 89, 'unmarked', "The functional question and the truth question are different questions.").
sentence(s_bookhs_15_0100, 'book-hs', 15, 89, 'unmarked', "Running them together is a mistake in either direction.").
