sentence(s_bookhs_16_0002, 'book-hs', 16, 5, 'unmarked', "Chemistry finds ways to last.").
sentence(s_bookhs_16_0003, 'book-hs', 16, 5, 'unmarked', "Life finds ways to copy.").
sentence(s_bookhs_16_0004, 'book-hs', 16, 5, 'unmarked', "Bodies find ways to split up the work.").
sentence(s_bookhs_16_0005, 'book-hs', 16, 5, 'unmarked', "Brains find ways to model.").
sentence(s_bookhs_16_0006, 'book-hs', 16, 5, 'unmarked', "Language finds ways to transmit.").
sentence(s_bookhs_16_0007, 'book-hs', 16, 5, 'unmarked', "Culture finds ways to pile up.").
sentence(s_bookhs_16_0008, 'book-hs', 16, 7, 'unmarked', "Or, as Ian Malcolm, Jeff Goldblum's chaos theorist in Spielberg's Jurassic Park (1993), puts it: \"Life, uh, finds a way.\"").
