sentence(s_bookhs_16_0009, 'book-hs', 16, 9, 'unmarked', "Every one of those sentences is slightly dishonest, and it's better to say so at the end than to let the rhythm carry it past you.").
sentence(s_bookhs_16_0010, 'book-hs', 16, 9, 'unmarked', "None of those things finds anything.").
sentence(s_bookhs_16_0011, 'book-hs', 16, 9, 'unmarked', "Nothing is searching and nothing is wanted.").
sentence(s_bookhs_16_0012, 'book-hs', 16, 9, 'unmarked', "The phrasing is a compression — exactly the kind this book has been describing — and like all compression it throws something away.").
sentence(s_bookhs_16_0013, 'book-hs', 16, 9, 'unmarked', "What it throws away here is the absence of anybody doing it.").
sentence(s_bookhs_16_0014, 'book-hs', 16, 13, 'unmarked', "The honest summary is that the continuity is real and uneven.").
