sentence(s_bookhs_16_0026, 'book-hs', 16, 19, 'unmarked', "Once things copy with variation, ordinary biology carries you through multicellular life, specialization, nervous systems, and animals that model their world.").
sentence(s_bookhs_16_0027, 'book-hs', 16, 19, 'unmarked', "This stretch is the best-supported part of the book and the least original to it.").
sentence(s_bookhs_16_0028, 'book-hs', 16, 21, 'unmarked', "Shakier at language, and this book says little about it that a linguist would respect.").
