sentence(s_bookhs_16_0068, 'book-hs', 16, 57, 'unmarked', "Whether complexity actually goes anywhere.").
sentence(s_bookhs_16_0069, 'book-hs', 16, 57, 'unmarked', "This book describes organization piling up.").
sentence(s_bookhs_16_0070, 'book-hs', 16, 57, 'unmarked', "It also says evolution has no push towards complexity.").
sentence(s_bookhs_16_0071, 'book-hs', 16, 57, 'unmarked', "Both are defensible and I haven't squared them.").
