sentence(s_bookhs_16_0073, 'book-hs', 16, 59, 'contested', "Whether anything pushes life towards complexity at all.").
sentence(s_bookhs_16_0074, 'book-hs', 16, 61, 'unmarked', "Here's the uncomfortable alternative.").
sentence(s_bookhs_16_0075, 'book-hs', 16, 61, 'unmarked', "Imagine a wall, and something wandering randomly next to it.").
sentence(s_bookhs_16_0076, 'book-hs', 16, 61, 'unmarked', "It can't go through the wall, so over time it drifts away from it — with nothing pushing it.").
sentence(s_bookhs_16_0077, 'book-hs', 16, 61, 'unmarked', "If there's a floor below which life can't get any simpler and still work, then random variation alone will spread things out away from that floor, and you'd see exactly what we see.").
sentence(s_bookhs_16_0078, 'book-hs', 16, 63, 'unmarked', "Where this has been studied properly, the evidence has tended to favour that boring explanation over a drive towards complexity, and so against the version of the story this book is built around.").
sentence(s_bookhs_16_0079, 'book-hs', 16, 63, 'unmarked', "The most common organisms on Earth are still single-celled.").
sentence(s_bookhs_16_0080, 'book-hs', 16, 63, 'unmarked', "What's increased is the maximum, not the typical.").
sentence(s_bookhs_16_0081, 'book-hs', 16, 65, 'unmarked', "A book organized around things getting more complicated has an obvious reason to underweight that, and probably has.").
