sentence(s_bookhs_16_0082, 'book-hs', 16, 67, 'unmarked', "Whether groups do what minds do.").
sentence(s_bookhs_16_0083, 'book-hs', 16, 69, 'author', "My own idea.").
sentence(s_bookhs_16_0084, 'book-hs', 16, 69, 'author', "A shaky one.").
sentence(s_bookhs_16_0085, 'book-hs', 16, 69, 'author', "Individual minds model themselves.").
sentence(s_bookhs_16_0086, 'book-hs', 16, 69, 'author', "Cultures accumulate models.").
sentence(s_bookhs_16_0087, 'book-hs', 16, 69, 'author', "Whether a whole society can be said to model its own modelling in any way that isn't merely a metaphor is unclear, and people treating it as settled in either direction haven't convinced me.").
